/* 令和2年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20200629-7","meetingId":"r02-cm06","date":"2020年6月29日","dateIso":"2020-06-29","committee":"厚生委員会","time":"午前１０時００分～午後 ２時３５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を87件整理しています。","topics":[{"id":"topic-01","title":"第４５号議案、品川区立在宅サービスセンター条例の一部を改正する条例","agenda":"第４５号議案、品川区立在宅サービスセンター条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"居ながら工事をやられたということですが、この戸越台複合施設の居ながら工事で、何か課題などありましたらお伺いできればと思います。以上２点、お願いいたします。","respondent":"宮尾高齢者福祉課長","answer":"中学校部分につきましては、令和３年３月に竣工予定というふうに聞いております。なお、工事が完了しました暁には、工事前と同じ定員に、元に戻して運営をする、このような予定です。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"認知症デイサービスの定員が１日１０人ということで、認知症の方は場所が変化すると、それによって認知症の症状に影響がある。周辺症状というのですか、そこのところを十分に配慮した上で引っ越しをお願いしたいということなのですけれども、いかがか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"認知症の方に対するケアといいますか、対応というのはしっかりとした配慮が必要だというふうに我々も認識をしております。ご家族を含め、丁寧に対応をする、このような所存です。","id":"exchange-002"},{"speaker":"渡部委員","kind":"確認","question":"前の資料を見て分かるかもしれないですけれども、２点伺います。１個は確認で、３月の調整会議のときに十何人ドンと乗っかって、その辺を伺います。","respondent":"宮尾高齢者福祉課長","answer":"工事のこの夏に戻るというところにつきましては、一応、ほぼ当初計画どおりということの想定で、９月１４日に戻って営業再開です。そういったところに齟齬がないように、またかえってそれが通常の運営に支障を来すことのないように、丁寧に対応してまいりたいと考えています。","id":"exchange-003"}]},{"id":"topic-02","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"今、説明の中で、昨年８月締切りの申請者や入所者の数字は伺ったのですけれども、今年２月締切りの申請者数はいかほどだったのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"本年２月の特養の申請状況ですが、お申込みを頂いた方の総数は４７９人です。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"それで、もう入所が決まった方は、その中ではいらっしゃるのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"ちょっと今、詳しい人数は手元に資料がございませんが、名簿自体は４月１日からの有効期間、登録期間ということになっておりますので、実際にもう入所されている方はいらっしゃいます。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問・要望","question":"ここに特養ホームや障害者施設を作っていただきたいと思っているのですが、区としてはどう考えていらっしゃるかお聞きしたいと思います。いかがか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"先般のご答弁のとおり、令和４年というところから先のことにつきましては、まだ把握はしておりません。東京都からの意向調査があって、それに対して福祉施設等に活用したいという回答をしているというふうに聞いているところです。","id":"exchange-006"},{"speaker":"おくの委員","kind":"質問","question":"ひとつお伺いしたいということと、いろいろな基準で点数をつけているわけですけれども、例えば年齢では７５歳以上でないと点数が得られないのです。ですから、私が伺いたいのは、いかがか尋ねました。","respondent":"寺嶋福祉計画課長、宮尾高齢者福祉課長","answer":"言い換えますと、それをそのまま特養に入れなかった待機者や、今後計画の中でもしっかり検討していく必要があろうというふうに考えております。施設についてはまだ整備が若干必要であろうというところは認識しておりますので… 先ほどの答弁と重なるところがあるかと思いますが、７５歳というのは後期高齢のスタートになってくる、そのスタートのところに合致をしています。こういったものにも大きく影響してくる１つの大きな基準となるラインだと考えていますの…","id":"exchange-007"},{"speaker":"おくの委員","kind":"質問・要望","question":"４０代、５０代、６０代の人は、この点数が必ず零点になってしまうわけですから、絶対入れなくなってしまうわけです。ですから、もう適応していないことが現実によって証明されているわけですから、外してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"おくの委員","kind":"質問・要望","question":"あまりにも足りないということがあるわけですから、この請願の趣旨どおりのことをやっていただきたいと私は非常に強く思います。これが区政の喫緊の課題の１つだと非常に強く思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"これが課題だと。今回大筋からいって、先ほどの答弁を聞いていて疑問に思ったのですが、教えてほしいと求めました。","respondent":"寺嶋福祉計画課長","answer":"在宅医療等の問題もありますし、医療連携等の話もありますので、なかなか看護小規模多機能のほうは増えていないという。よりいい介護ができるように、我々もしっかり、周知も含めてサービス提供をしていく必要があるというふうに考えております。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"意見","question":"声はかけていただいているということです。私調べてこなかったのですけれども、区内にどれぐらいの小規模多機能、看護小規模多機能……との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問・要望","question":"このようなことを求められる請願の趣旨として、今質問させていただいているのですけれども、よろしいでしょうか。具体的に今どれぐらいの数があって、そして周知にはどのようにお努めになられるのか、教えてほしいと求めました。","respondent":"宮尾高齢者福祉課長","answer":"それとは別に看護小規模多機能型居宅介護は現時点で２カ所、区内に整備をしています。訪問を使ったり、はたまた泊まりも使えるというところで、まずはそこからというところが現実的には大変多くなっているところです。","id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私はぜひ特養ホームに入れなかった方がその後どうされているのか、ぜひ区としてつかんでいただきたいと私は思うのですけれども、いかがでしょうか。それともう一つ、点数が高い人から順番に入れていくというようなことになるわけですから、入所の優先度を決めるということになるわけです。","respondent":"宮尾高齢者福祉課長","answer":"年齢というものも確かに項目として１つありますが、介護の状況でいらっしゃるか、こういったところも項目として加えているところです。そういったところをトータルに見て、お困りの度合いというものを決めているというふうに認識をしていますので、そのようなつもりはございませ…","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"前に私も事例を挙げながら何回か質問してきたのですけれども、そのような方に対しては胸が痛む思いだというように部長も答えられたのです。その点はいかがか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"こういったことも相談の中で対応させていただいているところですので、何というのでしょう、年齢の点数というところだけで相談内容が終わってしまうというふうには捉えておりません。","id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"改善に向けて検討していただきたいと強く要望をしておきたいと思います。それからグループホームも西大井で増設の方向だし、増設をしていきたいという思いがあるのか、その点についてお聞かせほしいと求めました。","respondent":"松山障害者福祉課長","answer":"委員お尋ねの、現時点で不足する施設としましては、基礎調査結果でも出ているのですが、やはりグループホームというものが挙げられています。そのため、グループホームにつきまして、先ほど申し上げたような増設支援を行っているところです。","id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"放課後等デイサービスなども足りないのではないかなどという声も伺っているのですけれども、そのような点では、取りあえず区ではグループホームが足りないというところでの認識ということでいいのか尋ねました。","respondent":"松山障害者福祉課長","answer":"基礎調査の結果で顕著に表れておりますのは、グループホームだと考えています。今後開催される策定委員会の中で、基礎調査の結果やヒアリング結果を踏まえまして、ニーズというものはきちんと把握をしていきたいと考えています。","id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"本当に障害者のサービスというものは、より充実をさせていっていただきたいと考えていますので、これからも様々な団体の皆さんからなど、お話を聴きながら、ぜひ充実の方向で取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"西村委員","kind":"意見","question":"今理事者からご説明がありましたとおり、施設整備や増設支援の調整を続け、一定の道筋が出ているものと思います。区のほうでも動いていただいていると理解しましたので、本件に関しましては不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"渡部委員","kind":"質問","question":"７０年住んでいるのだということだって、ですからその辺というものはやはり総合的な判断の中で、今やっているやり方で私はいいのかなと思っています。ですからその必要な分、ほかにも頼りながら進めていかなければならないのかなと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"おくの委員","kind":"質問・要望","question":"これが解消されるまできちんと計画を立てて増設していくことが、特養ホームに求められている、区政に求められている喫緊の課題だと思います。障害者施設につきましても、自立支援協議会でも要求が出ていると伺っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今いろいろご説明いただいたのですけれども、それから福祉計画の中でも様々な検討をされるというような状況がありますので、不採択ということです。今後丁寧に対応していただきたいことと、現行の事業所での支援の充実というか、今すぐにできることをまずやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"}]},{"id":"topic-03","title":"われているさなか「住居 特に食事」などに困難を来している多くの貧困下にある子どもたち、外国人労働者 野宿者らが安心してこの「危機」をのりきれるような緊急の行政…","agenda":"われているさなか「住居 特に食事」などに困難を来している多くの貧困下にある子どもたち、外国人労働者 野宿者らが安心してこの「危機」をのりきれるような緊急の行政…","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"それからもう一つ、給付金をどうやったら受けられるかというような相談にも乗られているのでしょうか。その２点をお伺いしたいと思います。","respondent":"櫻木生活福祉課長","answer":"庁内の連携についてですが、生活困窮者自立支援制度の連携会議というものを庁内の関係部署を通じて行っておりまして。２点目の給付金についてですが、ホームレスの方への定期的な巡回の時にそのようなご案内のチラシもお配りしています。","id":"exchange-022"},{"speaker":"おくの委員","kind":"意見","question":"給付金をどうやったら受けられるかの相談にも乗っているということなのですねとの意見を述べました。","respondent":"櫻木生活福祉課長","answer":"基本的に特別定額給付金の件のお尋ねですと、特にホームレス等の方々につきましては、まずこちらで一般的な生活困窮者の方へのご相談の対応という中で、このような方法を関係部署と連携しながらご案内をしています。","id":"exchange-023"},{"speaker":"おくの委員","kind":"質問・要望","question":"それから前にもちょっとご要望したというか、お伺いしたのですが、本当に目次でしかないのです。ですから改善が必要ですし、その点、改善の必要性や内容についていかがか尋ねました。","respondent":"櫻木生活福祉課長","answer":"制度の周知またはご案内方法につきましては、現在のところ、情報量として物足りないところがあることは承知しておりますので、機を見て適宜情報を付加していくような方向で考えております。","id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問","question":"教えていただける範囲で、実績が果たしてあったのかどうか、お伺いいたします。","respondent":"櫻木生活福祉課長","answer":"六名程度、冬ですと十二、三名程度というような状況で把握しております。それと緊急事態宣言前後も含めて、食料を取りにいらっしゃった方について、実績はございませんでした。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問","question":"今そのようなご紹介があって、宿直室にもありますよというところ、これは難しいですね。どのようにして周知を、そもそも周知をすべきものと考えているのかどうかというところについてお伺いしたいと思います。","respondent":"櫻木生活福祉課長","answer":"しかるべき対応が取れる体制までの間、食を提供することで対応していただくということが主眼ですので、緊急事態のときに的確に対応できるような種類のものかと考えています。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問","question":"そういったものが今自粛状態にあるのかどうか、それが解除されて再開をされたのかどうか、そういったことについての状況の把握というものは何かされているのであれば説明を求めました。","respondent":"櫻木生活福祉課長","answer":"区のほうでホームレス状態の方々が実際に炊き出しに行かれているとか、どのような食の生活をされているかという詳細については把握できておりませんが、巡回時にお話しさせていただける状況のときに、生活状況等を伺って確認しているという状況です。","id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほど、庁内の連携会議というものがあると伺ったのですけれども、もう１回教えていただけますでしょうか。一番の基本なので、その辺のところはぜひお願いしたいと思うのですが、いかがか尋ねました。","respondent":"櫻木生活福祉課長","answer":"それとまず連携会議の名称ですが、生活困窮者自立支援制度運営連絡会という名称です。先ほど申し上げたとおり、この制度自体は緊急対応という意味合いが強いものでして、提供するということはやらせていただきたいと考えています。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これはどのようなメンバーでされているのかということを１点お聞かせいただきたいということと、包括的な支援へと進めるということが書かれているのですけれども、そのようなことでも統一してされているということでいいのか尋ねました。","respondent":"櫻木生活福祉課長","answer":"国保、２０人程度の課長を集めて情報共有を図るとともに、それぞれの困窮者対策等について相互の情報共有を行っているという会議です。このような支援ができますので該当する方がいらっしゃった場合はご案内くださいという依頼をしているというような会議です。","id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"給付金をもらいたいけれどもどうしたらいいかというふうなことで、生活福祉課にまず行ったと。その辺のところは少し改善が必要なのではないかと思うのですけれども、いかがか尋ねました。","respondent":"櫻木生活福祉課長、寺嶋福祉計画課長","answer":"基本的にホームレス状態の生活困窮者へのご支援という中でご相談は受けさせていただいておりまして、その一環として特別定額給付金のお話があれば、それは関係所管につなぐような対応をしております。 福祉計画課のほうでホームレスの方は対象外だというような話がありましたが、そのような回答をしたことは恐らく１回もないと思います。そこの点についてはご説明させていただきたいと思います。","id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そこのところを制度として改善して、国としても改善してほしいというような思いもしているのですけれども。改めて住居確保給付金がどれぐらいまでいっているのか、分かったら教えていただきたいのが１点です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"だって住まいと食事ですから。困窮者への支援というようなことですから、そのようなところで、その点も説明を求めました。","respondent":"寺嶋福祉計画課長、櫻木生活福祉課長","answer":"今のところ、アクセスや情報の提供が分からないといったお問合わせが、直接区のほうに入っているということはございません。それから社会福祉協議会のほうも増員等を含めまして、今順調に対応が進んでいるというふうに聞いておりますの… 住居確保給付金につきまして正確な数字が手元にはございませんが、３００を超えて４００に近い数字になっている状況かと感じております。","id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"新型コロナウイルス感染症で大変な人がこれだけ広がっている今、変えていただきたいということで、強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"西村委員","kind":"確認","question":"は連携会議もあると確認が取れましたので、１点だけ、すみません。不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"渡部委員","kind":"意見","question":"もう本当に食べるものがなくなってしまった、どうしようというときに、引き続き続けてほしいと求めました。不採択ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問・要望","question":"明日ご説明のあるピックアップ型フードパントリー事業ですか、まだ説明を受けていないので、はっきりとは申し上げられないですけれども。券を発行するというお話なのですけれども、基本的に丁寧に寄り添っていただきたいということは要望を申し上げまして、不採択とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"おくの委員","kind":"意見","question":"採択したいと思います。お願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"高橋（し）委員","kind":"質問","question":"本日結論を出すということで、不採択でお願いします。ホームレス状態の方を含めた方々に対応されているということですので、不採択といたしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"}]},{"id":"topic-04","title":"令和２年陳情第３０号、「品川区障害福祉計画・障害児福祉計画策定委員会」等の委員委嘱・公募および開催に関する陳情","agenda":"令和２年陳情第３０号、「品川区障害福祉計画・障害児福祉計画策定委員会」等の委員委嘱・公募および開催に関する陳情","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"計画策定委員会ですけれども、これは何人の委員から構成されていて、どのような方が入るのでしょうか。決まっているのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"計画策定委員についてですけれども、委嘱のための手続きを進めているところです。教育関係の方々、それから障害者団体、公募の区民委員等が含まれております。","id":"exchange-039"},{"speaker":"おくの委員","kind":"質問","question":"それから、前の厚生委員会で出されたスケジュール表なのですけれども、計画策定委員会のほかに庁内連絡会というものがあるのですが、これのメンバーは、何人いて、どのような方で構成されているのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"こちらのほうも今進めているところなのですけれども、保健、福祉、医療、教育等関係する部署、所管の方に参加していただく予定です。","id":"exchange-040"},{"speaker":"おくの委員","kind":"質問","question":"それからこの計画の策定は、業者に委託するというような予定はあるのでしょうか。もし委託されるなら、業者名を教えてほしいのですけれども。","respondent":"築山障害者施策推進担当課長","answer":"こちらについては策定の支援ということで、株式会社インテージリサーチというところに委託をしております。","id":"exchange-041"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"７月下旬に５月分をされて、おおよそ何月にどうなっていくというようにずれ込んでいくのか、そこのところをお聞かせほしいと求めました。それから公募委員というものは何人だったのか、団体の方は何人入られているのか、そのメンバーの中身について説明を求めました。","respondent":"築山障害者施策推進担当課長","answer":"それからメンバーですが、公表につきましては、第１回策定委員会を実施いたしますので、その後ホームページ等で公表の予定です。それから公募委員のメンバーは２名で、団体については７名を予定しております。","id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"策定委員会だったり、もう１回作り直す形で報告しますということで、そのアンケートは今どうなったのかについてもお聞かせほしいと求めました。それからこの策定委員会は、もちろん公開で傍聴可能ということで考えていいのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"１点目の基礎調査報告書につきましては、概要版を分かりやすいようにまとめましたので、そちらを用いたいと考えています。先ほどもご説明させていただいたとおり、新型コロナウイルス感染症の状況を見ながら判断をさせていただきたいと考えています。","id":"exchange-043"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１０人以上の方が傍聴されていると思うのですけれども、そのような方向でぜひ、公開というようなことは確認させていただいていいのですよね。私も、障害の委員会というものは活発ですから、そのことについてのご説明がなかったのでお願いいたします。","respondent":"築山障害者施策推進担当課長","answer":"傍聴につきましては、受入れが可能かどうかも含めて、状況を見つつ判断をしたいと考えています。それから厚生労働省から出ております基本的な指針等は、委員が正式に決定いたしましたら、資料を事前送付する予定でおります。","id":"exchange-044"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"公開してほしいというところが当事者から何度も上がって公開になったというような経過があったと思うのですけれども、公開はぜひしていただきたい。その点だけ確認をお願いします。","respondent":"築山障害者施策推進担当課長","answer":"基本的には公開をするということで考えているのですけれども、新型コロナウイルス感染症の状況がありますので、そちらを踏まえて判断をしたいと考えています。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"確認","question":"本日結論を出して、不採択でお願いいたします。この理由について先ほど説明があり、全て粛々と進んでいるということが確認できましたので、不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"おくの委員","kind":"意見","question":"傍聴に向けた公開の点や、充実した審議のための充実した準備を進めてくださいという内容に非常に酌むべきものがあると思います。採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"高橋（し）委員","kind":"確認","question":"ご説明いただいたとおり、年度当初の予定の形で進んでいるというご説明がありました。やや遅れてはいるということですが、予定どおりということが確認できましたので、不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"}]},{"id":"topic-05","title":"令和２年陳情第３１号、「医療的ケア児等支援体制協議会」の委員委嘱に関する陳情","agenda":"令和２年陳情第３１号、「医療的ケア児等支援体制協議会」の委員委嘱に関する陳情","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"児童学園ですから医療的ケア児ですけれども、そのような点では品川児童学園の施設長はなぜ入らないのかというような思いがするのです。陳情者の方は書かれていると思うのですが、そこのところがなぜ入らないのかについて、ちょっとお聞かせほしいと求めました。","respondent":"松山障害者福祉課長","answer":"実際に医療的ケアが必要な障害児や障害者の方を支援していただいている事業者ということにさせていただきました。城南特別支援学校の代表として校長先生に出席を頂いております。","id":"exchange-049"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"お聞きしているのですけれども、総合支援施設の中ですから、その辺のところはなぜなのか。委員が１２名となっているのですが、トータルだと何名になるのかということもお聞かせほしいと求めました。","respondent":"松山障害者福祉課長","answer":"先ほども説明いたしましたけれども、当時と比べまして、医療的ケアが必要な障害児の受入れを行う事業所や学校が区内に増えたためです。それと実際の連絡会につきましては、訪問看護ステーションの方々にも入っていただく予定です。","id":"exchange-050"},{"speaker":"渡部委員","kind":"意見","question":"当時と状況が変わって、このような形でという中で、当事者の方々も入ったりということなので、会自体問題ないというように考えます。不採択でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"あくつ委員","kind":"確認","question":"本日結論を出すで、不採択でお願いします。陳情の趣旨のところについては先ほど説明があり、確認ができましたので、不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"おくの委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いいたします。実質的に充実した審議を求める趣旨、ならびに早急にそれをお願いしたいという体制を求める陳情ですので、採択を主張したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"本日結論を出すということで、不採択とさせてほしいと求めました。ただ、城南特別支援学校全体のご意見をこの準備会や、その後の連絡会で伺うような確認をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"}]},{"id":"topic-06","title":"議案審査を再度行います。 (2)第３９号議案、令和２年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"議案審査を再度行います。 (2)第３９号議案、令和２年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"減額の補正ということで、積極的な質問というのもなかなか難しいのですが、一応聞きます。来年にもかかる話なので、確認をさせてほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"１人に対して２万２,３５２円かかるところの１０人分約２２万３,０００円ということで、保健師を想定して、計上させていただいたものになります。減額されたものはそれとなります。","id":"exchange-055"},{"speaker":"渡部委員","kind":"質問","question":"食品衛生のところで１つだけお伺いします。ということは、そこで何かの販売や出店などをやるときは、直接品川区保健所がその管理をするというようなイメージでよろしいか尋ねました。","respondent":"鈴木（誠）生活衛生課長","answer":"ご質問のとおり、区内にあるオリンピック・パラリンピックの会場における食品提供の施設に関して、監視をするものです。","id":"exchange-056"},{"speaker":"おくの委員","kind":"質問","question":"ベッドですから雑魚寝とは言わないですけれども、２０m2、３０m2のところに３人、５人と詰め込むような状態のわけです。この辺いかがなのか、どう考えているのかと、ちょっと伺いたいと思います。","respondent":"鈴木（誠）生活衛生課長","answer":"換気の要請、または宿泊者の方とチェックインでコンタクトを取るときに説明をしたり、また館内での表示等で徹底を図れるというように考えられます。この１日の３分の２が無人になったり…","id":"exchange-057"},{"speaker":"おくの委員","kind":"質問","question":"だからこのガイドラインを踏まえて、新たな基準から見直す以外ないのではないですか。感染防止策がきちんと取られているということには全然ならない、全く納得できないのですけれども、いかがか尋ねました。","respondent":"鈴木（誠）生活衛生課長","answer":"国は現行のホテル、旅館の基準に沿った施設を前提として、この対策案を作っております。国の考え方からいって、今のご指摘のような、即危険な状態であるというふうには考えておりません。","id":"exchange-058"},{"speaker":"おくの委員","kind":"質問","question":"このようなものを仮に認めたとしたら、そのような接触感染のリスク評価や飛沫感染のリスク評価、これを区としても独自に行うべきではないですか。どうでしょう。","respondent":"鈴木（誠）生活衛生課長","answer":"無症状の感染の可能性があることや、ここの陳情に例示されたこと以外にも詳細のガイドラインの対応策が多く載せてあります。区のほうで独自に規制をかけたり、また特別な、このホテルに関しての検査をするような予定はございません。","id":"exchange-059"},{"speaker":"おくの委員","kind":"質問・要望","question":"今年の２月５日付の通知ですけれども、マスクの着用を求めることというものが、２の（２）に書いてあるわけです。やはり、それからこの厚生労働省の通知に沿った運営をしていくことも不可能だと思いますけれども、いかがか尋ねました。","respondent":"鈴木（誠）生活衛生課長","answer":"２月５日の厚生労働省の通知ですが、対応依頼の内容ですけれども、症状が出た段階で連絡が行くことになります。事業者は国やこのガイドラインに沿った対応をして、ホテルのもともとの設置の機能上、常に有人ではなくても事業者とは連絡が取れる状態ですので。","id":"exchange-060"},{"speaker":"おくの委員","kind":"質問","question":"常に事業者と連絡が取れる状態というのはどのようなことか尋ねました。","respondent":"鈴木（誠）生活衛生課長","answer":"事業者は無人になる時間帯があることを前提でチェックインから、また通常の管理もしておりますので、当然緊急時の連絡先、事業者の窓口に対応できる連絡先も周知をされておりますし、携帯電話等で連絡を取れば連絡はすぐつくということで考えております。","id":"exchange-061"},{"speaker":"おくの委員","kind":"質問","question":"しかし管理者がいないと、適切な連絡が保証されないわけでしょう。いかがか尋ねました。","respondent":"鈴木（誠）生活衛生課長","answer":"適切な連絡のために一番大事なことは、当該利用者の方から症状が出たとか、それからこのような接触の可能性があるなどという情報を頂くことです。これは管理人の有無ではなくて、その情報を把握するということで対応すればよいものであって…","id":"exchange-062"},{"speaker":"おくの委員","kind":"質問","question":"ですから、そのリスクを宿泊者なり、場合によっては周りの住民に負わせることになってしまうわけです。そのようなことになるのですけれども、その点、やはり厚生労働省の通知なり、ガイドラインが十分に守られないということになるのではないか尋ねました。","respondent":"鈴木（誠）生活衛生課長","answer":"国の制度です。このことをもって制度を変えるということは困難であるというふうに考えております。","id":"exchange-063"},{"speaker":"おくの委員","kind":"質問・要望","question":"そのような要望が出ているわけですから、このような住民の命、暮らしを守っていく責任は十分にあるのではないでしょうか。伺います。","respondent":"鈴木（誠）生活衛生課長","answer":"事業者の方が責任を持って守るというようにおっしゃっていたので、そのことについてお答えしましたが、行政についてはご指摘のとおり、住民の方の意見を聞いて暮らしを守るという責務を持っているというふうに認識しております。","id":"exchange-064"},{"speaker":"おくの委員","kind":"質問","question":"ですので、そのような住民の命、暮らしを守るという責任を果たすことはできないのではないですかというふうにお伺いしているわけです。それで、このガイドラインや厚生労働省の通知を守ることができないのだということは、私にとっては非常に明らかなことではないかと思いました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"},{"speaker":"渡部委員","kind":"確認","question":"ですから、なおかつ先ほどから説明のある２月のガイドライン、できるできないは私たちの判断ではない。確認をしたいのは、その辺でやはり地域の方としっかりと話をしていただいて、不安の払拭に努めてくださいぐらいは言えるのかどうなのか。","respondent":"鈴木（誠）生活衛生課長","answer":"２４時間常駐させるとなると、計画を変えなければならないということで、そこまでは対応できないというような事情も伺っているところです。委員ご指摘のように、その中で適切な運営や近隣への配慮、または苦情対応をされているかということは指導していくものです。","id":"exchange-066"},{"speaker":"渡部委員","kind":"質問・要望","question":"ですからそのような中で、要望として伝えるのであれば、開いていないですから。私たちは警察ではないですから、それは守ってしっかりやっていただくということでお伝えをしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"},{"speaker":"あくつ委員","kind":"確認","question":"これは許可になるのですか、というところを１点確認したいということと、これはもうそのとおりだと思います。先ほど渡部委員との質疑の中でもありましたけれども、ここについては今後も方針としては変わらないのかどうか、この２点をお伺いしたいと思います。","respondent":"鈴木（誠）生活衛生課長","answer":"１点目、１週間以内には事業者のほうに許可証を渡せるようになるというように、通常の手続きではなっております。それから２点目の、新型コロナウイルス感染症の対応のほうも重ねてお願い、そこはしっかりとやっていく考えです。","id":"exchange-068"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、その点の、区の認識をまずは伺いたいと思います。ガイドラインに沿ってどうなのかということや、そのような施設に当てはまるのかということを区がチェックするというようなことはされるのか尋ねました。","respondent":"鈴木（誠）生活衛生課長","answer":"変わるということについて区の認識はということですが、対応したりしておりますので、区としては当然認識をしております。ただし、これは適宜利用者の方や住民の方からの情報も含めて、適切な指導を続けるというものが区の役割であると考えております。","id":"exchange-069"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"保健所ですから、やはり新型コロナウイルス感染症の感染をいかに抑えるか、第２波、第３波、これをいかに抑えるかという部署なわけです。このホテルの接触感染のリスク評価はどうなのか、また飛沫感染のリスク評価はどうなのか、その点お聞かせほしいと求めました。","respondent":"鈴木（誠）生活衛生課長","answer":"これも自分たちで自主的に決めたことを事業運営の中で守って、また対応していくということが基です。注意だったり、具体的な業務の内容の部分ですので、ホテルの設備自体の規制をかけられるものではないというふうに認識をしております。","id":"exchange-070"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"でも、いろいろなところで人と人との距離、ソーシャルディスタンス２ｍということが出てきているのです。距離を２ｍを目安にできるだけ保つ、このガイドラインについてどうなっているかというようなことは、区としてチェックしないということなのか尋ねました。","respondent":"鈴木（誠）生活衛生課長","answer":"法に基づく検査の権限は、ここにはございませんというように申し上げております。近隣の方への配慮や、その中でこのガイドラインについてもお声かけをして、徹底を指導するということになるというふうに考えております。","id":"exchange-071"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そうすると、このガイドラインが守られた施設にするというようなことにも当然なっていくのではないですか。それは両方ともクリアしていくということが大事なのではないかと思うのですけれども、そこのところはどうなのか尋ねました。","respondent":"鈴木（誠）生活衛生課長","answer":"先ほどから申し上げていますように、権限に基づく指導と、それから新型コロナウイルス感染症対策の上で必要な指導というのはものが違いますが、保健所としては、おっしゃるとおり１つの組織として、区民の安全や衛生を守る上で両方指導していくというように申し上げております。","id":"exchange-072"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"ということは、保健所としては守ってくださいということで指導する、そのことを同時にしていくというようなことで確認させていただいていいですか。そうすると、例えば３４m2に４人や３８m2に５人などというようなことは、その点はどうか尋ねました。","respondent":"鈴木（誠）生活衛生課長","answer":"それから、できるだけ距離は１ｍから２ｍ空けるということ、広さだけで新型コロナウイルス感染症を防ぐという考え方になっておりません。そこは事業者がしっかりと責任を持って対応すれば、いたずらに感染を広げるということにはならないというように考えております。","id":"exchange-073"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それと、少なくとも無人ではなくて、２４時間常駐者を置く。このガイドラインと２４時間常駐というところは区としてもぜひ事業者にご指導いただきたいと思うのですが、最後お願いします。","respondent":"鈴木（誠）生活衛生課長","answer":"国からの通知や各種の情報、新型コロナウイルス感染症の感染拡大防止を呼びかけるということは、これからもやってまいります。ただし、ご指摘のあった２点については、法制度、それから区の行政の権限などから考えて、対応はできないというふうに考えております。","id":"exchange-074"},{"speaker":"渡部委員","kind":"質問","question":"前回９月にやり取りがあって継続にして、当然民間に対してですから、区としてできることをしっかりやってくださっているわけです。ですから区としてできることは、これからもまた続けていただけるということですので、継続でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-075"},{"speaker":"あくつ委員","kind":"質問・要望","question":"６月の陳情のほうでも述べようと思いますけれども、非常に大きなホテルが建っていて、不安があるのは私も当然よく分かります。ということまでを前回、この令和元年９月の陳情については求めているものではないので、継続とさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"},{"speaker":"おくの委員","kind":"質問・要望","question":"皆さんご存じでしょうけれども、３００名近くの方から署名をいただいているということも聞いていますので、地元の方々の一致した要望でもあります。常駐者を置いてきちんとやっていく、運営していくという要望はもう当然のことだと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"本日結論を出すということで、令和元年９月の陳情第３５号、令和２年陳情第２９号ともに継続にしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-078"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"では令和元年陳情第３５号のほうで、継続ということでお願いします。今までも指導していただきましたけれども、十分な指導をしていくという状況の中で、この審議に関しては継続してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-079"},{"speaker":"西村委員","kind":"意見","question":"本件に関しましても継続でお願いしたいと考えています。引き続き区民の方のご不安にならないようにしたく、継続でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"},{"speaker":"あくつ委員","kind":"質問・要望","question":"制度への改善を求めるという中で区民の方たちの不安も分かりますので、先ほど保健所のこれからの方針をお伺いしたところ、公衆衛生に関しては。その後の状況もしっかり見ていただいた上で、やはり判断すべきものかと思いますので、継続とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-081"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"継続でお願いしたいと思います。そちらの状況を今後続けていただくという観点で、継続にしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-082"}]},{"id":"topic-07","title":"令和２年陳情第２７号、不要不急の「特定整備路線事業計画」を中止しその財源を新型コロナウイルス対策に活用するよう東京都に要請を求める陳情","agenda":"令和２年陳情第２７号、不要不急の「特定整備路線事業計画」を中止しその財源を新型コロナウイルス対策に活用するよう東京都に要請を求める陳情","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"前半で、まずなすべきは新型コロナウイルス感染症という見えざる敵との戦いに全力を注ぎ、一時停止が可能な事業は原則延期または中止することだと。当然都市計画道路、特定整備路線は、この街路整備にあたるのではないかと思うのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-083"},{"speaker":"おくの委員","kind":"質問","question":"このような提言に対する区のご見解をお伺いしたいと思います。こういった専門家会議や１８道県知事の緊急提言といったものに対する区のご見解をお伺いしたいと思います。","respondent":"鷹箸保健予防課長、鈴木（博）委員長","answer":"区といたしましては、あくまでもこの間、２月７日に出された方針から本当に対象者がどんどん変わってきています。高齢者施設等、現状ではそういった方々に定期的な検査を実施するという方針を区として立てるということは… 明日の報告事項の７番目に新型コロナウイルス感染症に係る保健所・保健センターの対応についてということでレジュメも配られて、また詳しく論議することになると思うので、本日は陳情に沿った項目で質疑をお願いいたしたいと思います。","id":"exchange-084"},{"speaker":"おくの委員","kind":"質問・要望","question":"私としてはやってほしいと求めました。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-085"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"自分が実際に感染したらどうしようというような思いと、またそこから感染をさせたらどうしようという、障害者施設で働く方々から伺ってきたのです。働き続けざるを得ないという、そういう現場で頑張っていただいているところですから、せめて検査で安心の場面を作っていただきたい。","respondent":"鷹箸保健予防課長","answer":"その後大きな変更だけで、今までに７回変更されていて、濃厚接触者は全部対象となると。今実施しているＰＣＲ検査は、もともと感染症の検査では難しいところですので、今後も国の方針等を伝えてまいりたいと思います。","id":"exchange-086"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"発症９日目とか、そのような起点というのもあるのですか、一般のクリニックや医療機関などで保険診療のような形で唾液検査というものもできる。今できるのか、できないのか、これからできる方向になっていくのか、その辺のところが分かったら説明を求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-087"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/410936?Template=document&Id=3570#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":58993,"voices":268}},{"id":"r02-20200629-8","meetingId":"r02-cm06","date":"2020年6月29日","dateIso":"2020-06-29","committee":"建設委員会","time":"午前１０時００分～午後 ３時２０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を120件整理しています。","topics":[{"id":"topic-01","title":"第３９号議案、令和２年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第３９号議案、令和２年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回の補正予算は、新型コロナウイルス対策の財源を確保するために、不要不急の再開発などの減額が私は必要だと思っています。なぜこの補正予算にそういった減額が含まれていないのか、伺います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"私が聞いたのは、この補正予算の中に不要不急の開発の見直し、減額というのが入ってくるべきではないかということで聞いたのです。補正予算の審議ですから、なぜ含まれていないのか、ご答弁をほしいと求めました。","respondent":"中村都市環境部長","answer":"現在の補正予算の中でどういった項目を取り込むかというところの中で、再開発があります。あるいは区主催のイベント、民間の発意によって進めている事業でございまして、この辺を踏まえた総合的な判断の中でこういった結論になったです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、この品川区のまちづくりというのは区民任せになってしまうのかというふうに思ってしまいます。区の判断が必要なのではないかと思いますが、いかがでしょうかということで、そうしたことでやはり新型コロナウイルスの……。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"やはり開発事業の減額を行って、不要不急のものを減額して、新型コロナウイルスで苦しんでいる区民の皆さんに使っていくべきではないかと思います。最後に伺います。","respondent":"中村都市環境部長","answer":"これは民間事業の経済活動、こういったものをどの程度まで抑制するかというところの中では、やはりコロナ禍の中でも進んでいる経済活動というのはありますので、その辺を判断しての結果です。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"来年は来年の予算立てになると思うのですけれども、今年の予算の立てたものについては、どういうところに入っていてどういうところに。転用ができるのかどうかも含めて教えてほしいと求めました。","respondent":"堤坂環境課長","answer":"ポスターとかチラシは５月２４日に間に合わせるように契約をお願いしたのですが、デザイン料という部分で一部お支払いをしております。当然開催する方向で予算要求も含めて準備を進めてまいりますが、あと開催は１日ですけれども、そういうことを検討していきたいと考えています。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"転用とかできるのでしょうか。それから道路橋梁費のところもお聞きしたいのですけれども、そのお金は結局かからなかったというところで、どういうお金の動きになってくるのか。","respondent":"鈴木都市計画課長","answer":"通常、事業を進めていく中で、その中で課内あるいは部内で予算の流用ですとかそうしたことは状況によってはあるのだと思います。ただ、洗い出し等をやっていますから、都市環境部あるいは防災まちづくり部ではない所管のほうで検討されていくのだという認識です。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"土木関係は結構大きなお金が動く可能性もあるものですから、そうなるとほかのところで助かるみたいな状況があると思うのです。でも、そういう考え方はどうなのか、お聞きしたいと思います。","respondent":"鈴木都市計画課長","answer":"こうしたものは、全庁で予算の枠組立ても含めて検討して、早急に対応していくというのが基本的な考え方だと思います。基本的には全庁的に緊急に、迅速に対応する体制をとっていくというのが統一して図られておりますので、その中で検討していくものだと考えております。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"全庁的に動けるときにはぱっと動くという形にぜひしてほしいと求めました。これは意見ということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"若林委員","kind":"確認","question":"今、不用額というお話が出まして、確認というか。ここで聞いて、はいとか、いいえとかと言う問題かどうか分かりませんけれども、確認できればお願いいたします。","respondent":"鈴木都市計画課長","answer":"第２回定例会で上程させていただいた減額については、委員ご指摘のとおり不用額という形で、その後の取り扱いについては、基本的にはご指摘いただいたとおり全庁的に財政課のほうで総括して判断をしていくという認識でおります。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"意見","question":"だけれども、今、３分の１とかいう基準で会場もオープンしたりして、密とはどういうふうにやるのだとか。今度これから第３回定例会もあるわけだから、来年度予算もそれは踏まえていただいてお願いするということだけ言っておいて、基本的には賛成ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"若林委員","kind":"確認","question":"先ほど確認もさせていただきました。賛成します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"のだて委員","kind":"意見","question":"先ほども言いましたけれども、含まれるべき不要不急の再開発の減額というのがありませんが、今回は中止・延期となっているものを減額するということですので、賛成ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"西本委員","kind":"意見","question":"いい見直しの時期だと思いますので、ぜひ前向きに経済も高めつつ、安全性を確保するという。この委員会は一番直接的な関わりがあるところだと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"}]},{"id":"topic-02","title":"羽田新経路の固定化回避に係る技術的方策検討会の開催","agenda":"羽田新経路の固定化回避に係る技術的方策検討会の開催","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"検討会について伺います。この検討の中に新ルートの変更も入っているのか、こういったことの国から説明をされていることや、ご存じのことがあればご説明ください。","respondent":"鈴木都市計画課長","answer":"国土交通大臣が会見によってこの検討会の開催を公表したわけですが、東京都の連絡会のほうでこの中身についての説明がございました。固定化回避に向けた技術的検討というところと、この検討会の名称にもありますように、区としてはそういう認識をもってあります。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういう認識をもっているのでしたら、ぜひ区として羽田新ルートの中止を求めていただきたいと思うのですけれども、いかがでしょうか。区としても公開にするよう求めてほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"１点目のこの検討会の中で新ルートの変更もあり得るのかというご質問ですが、国は事前の東京都の連絡会の中でも。当然ながらその会の中身については資料を含めて議事についても公開されるものという認識でおりまして、その中身についてしっかり見ていきたいです。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ区としても中止を求めるということで要望をしてほしいと求めましたけれども、その後。それが延びて、ぜひ区としても中止に向けて要望してほしいと求めましたが、改めて伺います。","respondent":"鈴木都市計画課長","answer":"先ほどご説明しましたように、今年度中にということで、この固定化回避に向けた固定化をしない取り組みについて文書あるいは口頭で求めてあります。その文書の中でも、この中身について注視しながら具体的なものが一刻も早く出るように、区としては求めていきたいという考えです。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"先ほどのご答弁でも、今回の一般質問で国策になぜ中止を求めないのかという問いに区はまともに答えず、一定理解をしていると繰り返しました。伺います。","respondent":"鈴木都市計画課長","answer":"立ち止まって何の検討もせずに、もうこれが固定化して未来永劫進むということのないように、固定化しない取り組みを求めたという意味合いです。５月２０日の区の要望の中にも、このコロナに対する対応、あるいは口頭でもって求めてきたです。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回の５月２０日の区長の要望にもそこが入っていないというのが一番のポイントなのです。やはりそこを求めていくということが、安心・安全を守っていくということでも必要なことだと思いますが、いかがでしょう。","respondent":"鈴木都市計画課長","answer":"周辺関係自治体ともそうですが、一体となって国にその対策を求めてきている、また丁寧な説明も含めて求めてきている。これは本格運用前、本格運用開始後も一貫して変わらないです。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"当然、国がやることですから一義的には国の責任があります。意見をしっかりと伝えていく、中止を求めていくということが必要だと思いますので、そういったことも求めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"なおかつ、コロナの減便で増便のための羽田新ルートというのは必要ありませんので、ぜひ区としても中止を求めてほしいと求めました。実機飛行確認の結果や減便中でも実施したことなど、説明会の開催を区としても求めるべきですが、いかがでしょう。","respondent":"鈴木都市計画課長","answer":"その結果、決定前には区内１３地域、これは区内全域ということになりますが、他区に先駆けて説明会を開催していただいたというような状況です。今後も様々な手法を活用した区民への丁寧な説明は求めていきたいです。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ説明会を求めてほしいと求めましたし、特に教室型の開催を求めています。やはりほかの人の意見も聞きながら議論できる教室型の説明会を要望すべきだと思いますけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"今委員にご指摘いただいた教室型説明会もその一つだと思います。それを含めて、それに限定することなく、様々な手法を活用して丁寧な説明を求めていくです。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"周知方法は様々といいますが、教室型説明会が求められているわけですから、ぜひ区としても求めてほしいと求めましたし、住民の理解が得られないままにこの羽田新ルートの運用が強行されましたので、議会としても教室型説明会の開催を求めるべきだと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"検討会の開催について伺いたいのですけれども。議題に関して第２項目で、この「など」についてご説明があったのか、「など」の中身を教えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"国からの事前のご説明では、この資料にあるとおりでございまして、「など」の中身について、こちらからも質問をしましたけれども、その中身について具体的な、この資料にある以上のものは回答としてはございませんでした。","id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"一番被害が多い品川区という自治体として、もっとより説明がされるべきだと思うのです。そこについて区として“もっときちんと説明をしてください”と求めることはなかったのか尋ねました。","respondent":"鈴木都市計画課長","answer":"今、“これでは分からないのでもっと説明してください”という内容を区として国のほうに申し伝えるというのはいろいろな場面で違うと思います。これは会が実施された後の公開される資料についてしっかり注視して、内容は問い合わせ、あるいは求めていきたいです。","id":"exchange-024"},{"speaker":"田中委員","kind":"質問・要望","question":"いろいろな場面で求めてそれぞれ様々な要望をしているということだったのですけれども、なぜ区としてもっと追及できないのかということと。その辺についてもう一度ご回答ほしいと求めました。","respondent":"鈴木都市計画課長","answer":"「固定化回避に向けて考えられる技術的選択肢」ということで、細かいところについて、回答がなかったことについてさらに求めなかったです。しっかり資料と議事要旨が全体の会議を確認できるものであれば、その中身をしっかり見させていただいて、国に必要なことを伝えていくです。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"今議事要旨をこれから確認するということだったのですけれども、どのような会話がされたのかというのが、中身が見えてこないではないですか。ぜひ逐語録というのですか、品川区の議事録のような形にしてもらうように要望していただきたいと思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"この会の開催の予定ですが、「設置について」と「進め方について」ですから、これ１回で終わるという認識はございません。年度末までなのか、年内に何回か開かれて一定の整理がされるという認識です。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問","question":"スケジュールなのですけれども、大体１か月に１回行われるとか、そういったこととかも報告はなかったのか尋ねました。","respondent":"鈴木都市計画課長","answer":"どれぐらいの頻度というところも含めて、今後の開催回数については説明はございませんでした。","id":"exchange-027"},{"speaker":"田中委員","kind":"確認","question":"その議事要旨を確認してから、スケジュールもまだ分からないとか、こんなに分からないことだらけで。区民の声もたくさん上がってきている自治体として、もっと踏み込んでいいのではないかと思うのですけれども、その姿勢というのは変わらないのか尋ねました。","respondent":"鈴木都市計画課長","answer":"今月末急遽立ち上がったという区としての認識ですので、今後この会で全体的な検討のスケジュールですとかが示されるのかどうか、そこも含めて。全体の内容が確認できるものを公表いただくというのは大前提だと思いますので、その中身を見て必要な要求をしていきたいです。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問・要望","question":"何か月も開催されなかったら求めていくということだったのですけれども、今困っているのです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"明日開催された後にも、いつ議事録が公開されるのかということとかも常々伝えてほしいですし、そういう姿勢になってほしいということを求めます。そして、請願・陳情のほうになるのですけれども、説明会を求めている請願・陳情が幾つかあったと思います。","respondent":"鈴木都市計画課長","answer":"国の説明が当初の説明と違ってきているですが、それから３月２９日の本格運用開始以降、委員ご指摘のとおり。これも含めて、先ほどご答弁申し上げたとおり、いろいろ本格運用開始以降も国にはそうした説明の場をもっていただけるように求めていきたいです。","id":"exchange-030"},{"speaker":"田中委員","kind":"意見","question":"それが今回コロナの影響で減便などがされて、今回は都市部での騒音の共有といった新しい文言が出てきました。その国の説明の中で、羽田新ルートの目的が変わってきていると思うのですけれども、そこに関して区はどのように考えていますかとの意見を述べました。","respondent":"鈴木都市計画課長","answer":"この平成２６年以降の具体化協議会ですとか、私のほうでも過去の具体化協議会、あるいは関係の資料の中で認識しています。そういう認識はあったものの、これまで説明を受けていたのは、国にしっかり説明を求めていきたいです。","id":"exchange-031"},{"speaker":"田中委員","kind":"意見","question":"ないのです、なかったのです。新たな目的、目的が変わってきているので、これの国の区民に対する説明は必要だと思うのですが、そのところとの意見を述べました。","respondent":"鈴木都市計画課長","answer":"その後の区内１３地域での教室型説明会、冒頭の国の説明の中で、首都圏全体での騒音の共有化という説明はなかったと記憶しています。そうした意味で、先ほどご答弁申し上げたとおり、国に説明は求めていきたいです。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ教室型の説明会を求めてほしいと思います。少なくとも今は必要がないといったことを、そういう立場に立ってほしいと思うのですが、そのことに関していかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"この羽田新ルート機能強化策については、国の事業で国策でございまして、そういった判断は国の責任において行われるべきだです。しかしながら、落下物ですとか、騒音環境の軽減ですとか、丁寧な説明については、委員ご指摘のとおり区としてしっかり求めていきたいです。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"要望書でもこういった趣旨、例えば要望書の中には固定化しないという文言が、趣旨としてというふうに要望書で出しているではないですか。はっきりと区民の方たちからこういった声があるということをきちんと要望してほしいですし、そのことについて伺いたいというのと、もう一点です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問","question":"２０１６年に品川・生活者ネットワークの一般質問に対して、それは現実に起きた事柄に即して物を考えていくということ」という発言をしているのです。現在、このような声がいっぱい上がってきているわけではないか尋ねました。","respondent":"鈴木都市計画課長","answer":"進めていくべきという内容でございまして、５月２０日の区長要望の中でも要望書の中に添えてお出ししておりますし、国のほうに伝えているところです。騒音環境の軽減、それから丁寧な説明を求めていく、固定化しない取り組みを求めていくというところは変わらないです。","id":"exchange-035"},{"speaker":"田中委員","kind":"意見","question":"自治体として区民の声を届ける、区民の命、生活を守るといった意味での責任放棄が今されているのではないかということを言っています。そのことについてとの意見を述べました。","respondent":"鈴木都市計画課長","answer":"区民の不安、落下物に対する危険性、それから日々上空を通ることによって起こる飛行騒音、この軽減については、区としてもしっかり求めてきているし、これからも求めていくです。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"どういう連携をとろうとしているのでしょうか。この令和２年陳情第２８号の中で、大田区長と川崎市長が連名で提出している要望書があるということで、その２点目をお聞きします。","respondent":"鈴木都市計画課長","answer":"１点目の固定化の意味合いですが、先ほどもご答弁申し上げたとおり、現在新ルート計画が本格運用されて実施されているわけです。それから、２点目が……。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問・要望","question":"確認はやはりしていかなければいけないと思います。それを国へ届けていくという、これは大きな役目だと私は思いますので、その方法についてお考えをお聞きしたいと思います。","respondent":"鈴木都市計画課長","answer":"この固定化に向けた取り組みを国に求めているわけですので、新宿のほうから来て品川区上空を通るルートが何の検討もされずにこのまま固定化して。声については、あるいは中身によっては国のコールセンターの対応が悪いとか…","id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"意見も含めて、地域の状況を品川区自ら知ってほしいと思います。地域の影響について、独自での情報収集ということについてのご意見を最後にお聞きしたいと思います。","respondent":"鈴木都市計画課長","answer":"そうしたところにつきましては、区のほうで今年度、環境の部分と所管も移して都市計画課のほうで空港環境担当を新設しています。そうした声を、いかに多く区民の声を国にしっかり届けていけるかというところは、態勢を整えてしっかりやっていきたいです。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"国策のため国が判断すべきだということでおっしゃっていましたけれども、こうした立場で区民の安全・安心、健康を守れるのでしょうか。伺います。","respondent":"鈴木都市計画課長","answer":"このコロナ禍の中での減便に対応する騒音環境の低減の取り組みについては、５月２０日に区長が国に要望として求めたです。区が行うべきことは区民の不安払拭に向けた落下物、騒音環境、固定化しない取り組みを継続して強く求めていくというところだと理解しています。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり中止を求めるという立場に立つことが区民の安全・安心、健康を守るということに深くつながってくるということになると思います。むしろ中止を求めないということになると、ぜひ中止を求める立場に立っていただいて、健康を守っていくという立場に立ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"田中委員","kind":"質問・要望","question":"区としていつ頃だったりとか、あと、羽田のことに関する電話とかを受ける窓口ができたではないですか。それが現状どうなっているのかというところが分かればというのと、もしまだ協議会が生きているのならば、そこのところを確認させてください。","respondent":"鈴木都市計画課長","answer":"他区との連携状況、ある意味離陸について同じ課題、方向性があるということでそうなったのかなという認識です。この会が閉会あるいは休止中という認識はなくて、その方向、そうしたところは今後議論されてくるのだという理解です。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問・要望","question":"前回この建設委員会で示された要望書の形、ああいった要望書の形での要望がどのような事態になったら次に出されるのかというところを確認したいです。今、ぜひ協力して連名で出せるような形にしてほしいなと思うのですけれども、ぜひそこら辺の見解も伺えればと思います。","respondent":"鈴木都市計画課長","answer":"それから、当然効果的な形で進めていきたいとは考えてありますが、本格運用が開始される前に各関係区市の要望というのが一覧で出てあります。例えば固定化に関する取り組みというのは、そこは状況と内容を見て、今後検討されていくべきなのかです。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問・要望","question":"そういう要望も公開してほしいということも求めたので、それについても伺えればと思います。前回この建設委員会で示された要望書のような要望書の作成については、このタイミングを知りたくて。","respondent":"鈴木都市計画課長","answer":"４月が２７件、５月が２７件、６月が６月２２日現在のものになりますが１８件です。先ほどの検討会の中身について注視しながら、あるいは要望しなければいけないところは、その機を逃さず要望していくというような考えです。","id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"前回建設委員会で示されたようなきちんとした要望書については、今回この検討会の後に要望書をもしかすると出すかもしれないということですね。そもそも都心の上空に飛ばすのはやめてほしいといった声があるということも要望書の中ではきちんと示してほしいと思いますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"それと区の対応に関する意見・質問というところで、区としても中止を求めてほしい等々の意見が８件等の数です。そうしたところの公表は難しいと思いますが、公の場での発言等々についてはしっかり公表してまいりたいと考えています。","id":"exchange-045"},{"speaker":"田中委員","kind":"質問・要望","question":"その要望書に対しては、反対ができないというのであれば、区民としてこれだけの反対を求める声があるといった記述もできると思うのです。そういったように、きちんと区民の声が反映される要望書を作成してほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"５月２０日の区長要望の中にも区民の声は要望として添えさせていただきましたが、今後も基本的には区民にいただいた声をその要望の中に反映して、国のほうにしっかり求めていきたいです。","id":"exchange-046"},{"speaker":"田中委員","kind":"質問・要望","question":"前回の要望書の中には、ぜひそういった声もあるということを次の要望書では記述してもらいたいと思います。いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"前回同様、区民の声についてはしっかり添えて、必要な要望をしていきたいです。","id":"exchange-047"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"この３会派で国土交通大臣宛ての要望書を作成し、そのとき大臣に会えなくて、航空局長にそれを提出して意見交換もさせていただきました。５月２５日、従前ルートに戻す対応をしてほしいという要望を、その要望書も提出させていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"大沢委員","kind":"質問・要望","question":"私どももこの９件については継続をお願いしたいと考えておりますが、冒頭に、令和２年請願第３号についての意見を述べさせてほしいと求めました。区民としての意思を届けていただくことを多く期待をしながら、この令和２年請願第３号については継続でお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"若林委員","kind":"質問・要望","question":"品川区、また私どももこの固定化回避についてはずっと重ねて要望してきた経緯がありますので、これは当然評価をしたいと考えています。区議会としても具体化を当然求めているわけですが、区には力強く、強く求めていただきたいと要望して。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"のだて委員","kind":"質問・要望","question":"この質疑の中でも出てきましたけれども、中止・撤回を求めるということは区民の安心・安全を守るということにもなりますので、ぜひ賛成をしたいということで、なおかつ、コロナで減便になっている中ですから、なおさら増便のための羽田新ルートは必要ないと思いますので、採択をしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"田中委員","kind":"質問・要望","question":"前回出された要望書の中にもあった固定化しないというのは、この羽田新ルート、それを反対する理由にはならないかと。採択したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問・要望","question":"前回の委員会で申し上げたように、これだけいろいろ変わってきているので集中的に建設委員会で取り組むべきだという主張をさせていただきました。令和元年の、既に１年以上経っているものをまた引き続きやっていく……。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"これは教室型の説明会を開くということで、運用も始まっており、状況は変わっていますから、教室型説明会をやっていただきたいと。結論を出すということで。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"田中委員","kind":"意見","question":"本来の目的と羽田新ルートの目的が変わってきているので、それだけでも区民に対する説明義務というのが出てくると思います。ぜひ開催してほしいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"田中委員","kind":"質問","question":"本日結論を出すで、採択をしたいと思います。ぜひ採択にしていただけたら、皆さんでできたらいいなと思うのですけれども、いかがでしょうかという問いかけもしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"田中委員","kind":"意見","question":"再三申し上げておりますが、新飛行ルートの説明会については、ぜひ皆さんにも本日結論を出すで採択に回ってほしいと求めました。説明会は開催されるべきだと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問・要望","question":"安心して利用できるコミュニティバスの実現を求める会から出されまして、区内全域に気軽に行けるようにしてほしいということで求めているものです。特に区役所に行けるように求めておりますけれども、区のお考えをお聞きしたいのと、お聞きします。","respondent":"鈴木都市計画課長","answer":"利便性を高めていくというところで、導入に向けた検討を開始しています。区内１３地域で、１３地域というのは地域センター管内ごとですが、より高低差があるところが得点が高くなるという考えに基づいて行われております。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひそういったことも検討してほしいと求めましたが、改善していくということもあり得るのかどうか、伺いたいと思います。ぜひ五反田駅まで延ばしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"先ほどご説明したように、１３地域の中でいろいろワークショップという形でご意見をいただきながらこれから３ルートの検討を深めてまいります。ルート案としてはお示ししていますが、ワークショップの中でご意見を聞きながら、検討していきたいというところで考えてあります。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"１年から３年というお話がありましたが、どちらなのかよく分からなかったので、そこのところを確認させてほしいと求めました。そういった形で便利なルートをぜひ考えてほしいと求めましたが、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"試行運行期間がまだこれから検討の段階でして、３年なのか、そのような答弁を差し上げたところです。そういう視点ももって、それはこれから提案いただく予定になっていますバス事業者のほうからもしっかり提案いただきながら、考えていきたいです。","id":"exchange-060"},{"speaker":"のだて委員","kind":"質問・要望","question":"これから試行運行がされていくということになると思いますけれども、やはり地域の方々が利用しやすい、また、移動の保障をするというところで、より便利な改善をしていくようにしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"田中委員","kind":"質問・要望","question":"これで決定ではないということをまず確認したいのと、あと、やはり区役所に行けるようにしてほしいといった意見がまず第一に上がるのです。区の考える利便性と住民が求めている利便性に少し差があるのかといったところがあるので、その辺についてお話を伺えればと思います。","respondent":"鈴木都市計画課長","answer":"あるいは病院、商店街に行きたい、これは昨年６月に実施したアンケートでもそうした声は多く寄せられてあります。バスあるいは民間の鉄道、これを補完する公共交通というところが、コミュニティバスの目的だです。","id":"exchange-062"},{"speaker":"田中委員","kind":"質問・要望","question":"は、ワークショップが１３地域で行われるということなので、ここでの意見が強く反映されると思っていいのでしょうか。そこを確認させてください。","respondent":"鈴木都市計画課長","answer":"区のほうからいろいろな説明会を開くとか、費用対効果からいって、それは優先順位が少し違うのかと感じてあります。どういう形でのワークショップかというのは今検討しているところですが、この候補ルート案等に反映していきたいと考えています。","id":"exchange-063"},{"speaker":"田中委員","kind":"質問・要望","question":"この１３地域でのワークショップもぜひやってほしいのですけれども、住民同士の意見交換の場をぜひ作っていただきたいというのを思います。このワークショップについても、積極的に周知、町会だけにとどまらない、多くの方に知ってもらえる機会を求めたいと思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"ただ、例えば、地域の声をバランスよくお聞きできるような区民参加のあり方というのを検討していきたいと考えています。限定した方にお集まりいただいてではなくて、１３地域すべてでワークショップを実施して、区内全域で行っていきたいです。","id":"exchange-064"},{"speaker":"田中委員","kind":"確認","question":"１３地域で行われたワークショップの結果だったり、ワークショップの状況というのが公表されたりするのか、確認させてください。","respondent":"鈴木都市計画課長","answer":"ワークショップの結果は、公表してまいります。","id":"exchange-065"},{"speaker":"田中委員","kind":"意見","question":"“あそこの地域ではこういう負担があるのだね”といったような共有ができるような、それでそれぞれが譲り合えるような感じができたらいいというのを思うので、ぜひそういった検討もしてもらえればと思いますとの意見を述べました。","respondent":"鈴木都市計画課長","answer":"そういう意味では、ある意味、地域特性も踏まえて、一律の視点だけでのアンケート結果の公表の仕方ではなくて、クロス集計もしています。こうした結果も活用しながら、今、委員にご提案いただいたように、このワークショップの結果というのは広く周知をして、進めていきたいです。","id":"exchange-066"},{"speaker":"西本委員","kind":"質問","question":"それとも、この路線というのはプラス収入という形として考えていくべきものだと思っているのか、その辺はいかがでしょうか。説明を求めました。","respondent":"鈴木都市計画課長","answer":"“いやいや、見込みが甘過ぎる”とか“もっと売上げが出ます”とか、そこはバス事業者のしっかりした提案を見ていきたいです。しっかり線を引く指標を決めて、試行運行を開始していきたいです。","id":"exchange-067"},{"speaker":"西本委員","kind":"質問・要望","question":"７時から多分９時、朝の時間帯は、まずここは非常に危険なところですので、そういうことも含めてルートを決めていただければと思っています。このルートは私は避けるべきだと、それも含めて検討していただきたいと考えていますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"添付してございませんが、昨年度３回の検討会の中で、地域公共交通基本方針（素案）ということをとりまとめてあります。そうした中で、より安全性の高いルートを選定していけるように、絞り込んでいけるように、しっかり検討していきたいです。","id":"exchange-068"},{"speaker":"西本委員","kind":"確認","question":"私は大井ルートのほうはそういう形で見させてもらいましたけれども、ほかのところもあるかもしれませんので、ぜひ確認しつつ。にはこれだけの税金が必要で、ぜひその辺も含めて、しっかりした説明責任も含めて。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だから、やはりそれはきちんと説明してほしいと前にも言ったのだけれども、“ここはできません”ときちんと言ってください。そこの幅員で警察との交渉とか、地域に入ったときのワークショップ、特に３つの候補ルートのところ、そこのやり方を、少しそこだけは答弁してほしい。","respondent":"鈴木都市計画課長","answer":"検討案に対する地域への説明ですが、１３地域を回って検討状況については説明をしてまいりまして、まだ４地域にしか回れてございません。残りの地域を含めて、ワークショップの実施のご案内とともに、結果についてはご理解いただけるようにしっかり説明をしていきたいです。","id":"exchange-070"},{"speaker":"田中委員","kind":"確認","question":"確認させてほしいのですけれども、この１３地域でのワークショップでの意見が出た場合に、その意見はあまり反映されない。そこだけ確認させてください。","respondent":"鈴木都市計画課長","answer":"さらにその３地域の中でこのルート決定にあたってはこういう視点でルートを決めているというところはしっかり説明するということです。この３ルートについて、そこは今後、事業認可に向けては警察とも協議していかなければいけないわけです。","id":"exchange-071"},{"speaker":"田中委員","kind":"質問・要望","question":"ワークショップで出た意見もきちんと反映できる形でといったことをお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"その中で３候補案があって、その中で様々これから地域に入って、これを運行していこうという今の段階です。この中でいろいろ個人のお考えはあるのは分かるけれども、そういう意味では、我々はこの陳情については不採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-073"},{"speaker":"大沢委員","kind":"質問・要望","question":"均整のとれたということは、言葉を変えれば、住民要望、地域要望を十分にとり入れた、反映されたルートであると理解をしております。すると、この３つの選定の基準と１１の指標に基づかれて３ルートを決められたわけですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-074"},{"speaker":"若林委員","kind":"提案","question":"今後の事業者提案、それからワークショップ等、地域の声をまたしっかり反映されて、最善のルート設定になるようにお願いいたします。よって、不採択ということでお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-075"},{"speaker":"のだて委員","kind":"意見","question":"結論を出すということで、区役所に行きづらいというのは、区内共通の課題ですし、便利なバスルートにすべきだと私も思いますので、採択でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"},{"speaker":"田中委員","kind":"質問・要望","question":"改善を求めているので、ぜひこの要望を聞き入れるべきだというのを思います。採択を主張します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出してほしいと求めました。今進めている３ルートがあって、こういう陳情があったということを念頭に置いていただきながら進めていただければありがたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問・要望","question":"この請願の中に、この人身事故や過去にあった死亡事故というのはどういうものだったのか、ご存じでしたら伺いたいと思います。まちづくり関連の事業推進ということが書いてありますが、このまちづくり事業というのはどういったものがあるのか、伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"例えば、駐輪場であったり防災倉庫などですが、そういったものの支援を求めていくものといったところです。避難ネットワークの形成、または戸越公園を拠点としましたみどりのネットワーク等々のネットワークの確保、そういったものを推進していくものです。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問・要望","question":"この基盤整備も、そういったことも含めて求めているということだと思うのですけれども、鉄道の立体化と再開発などを一体に進める必要があるのか。なぜそういうことになるのか、伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"そうした中で、地域が考え、また、まちづくりを考えたときに、市街地再開発事業といったものが生まれてくるのかです。木密地域の改善であったり、もともと老朽化があった建物等の共同化によっての再開発といったところで、地域が声を上げてやっているところです。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問・要望","question":"直接的には立体化と再開発との関係性はないということでした。再開発は中止すべきなのですが、立体化は立体化で進めてほしいと求めましたので、そういったことで要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-081"},{"speaker":"田中委員","kind":"確認","question":"けれど、項目の２にある駅周辺の基盤整備、まちづくり関連が一緒になると、ちょっとなという気がします。補助２９号線の問題で今、今、その訴訟の問題はどうなっているのかというところを確認したいのです。","respondent":"中道まちづくり立体化担当課長","answer":"補助２９号線の訴訟につきましては、東京都が所管しておりますので、こちらとしましては、そこまで確認をしているところではございません。","id":"exchange-082"},{"speaker":"田中委員","kind":"質問・要望","question":"今年の３月２５日に、まちづくり協議会と区の連名で要望書を提出したということで、要望書も確認しました。この要望書を提出した経緯について伺いたいのですけれども。","respondent":"中道まちづくり立体化担当課長","answer":"平成２８年度に今のまちづくり立体化担当を新設いたしまして、重点的に地域とこの取り組みを行ってきたところです。そうした中で、地域からの要望を受けて、また、区も立体化を推進していくという立場から、東京都に対して連名で要望書を提出したところです。","id":"exchange-083"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほども話した補助２９号線の訴訟の問題がある中で、区民の中ではそうした訴えもしている中でこの要望書が提出されたということと、そういったコロナの問題が起きている中でこの要望書が提出された理由についてお知らせください。","respondent":"中道まちづくり立体化担当課長","answer":"短期的な目的で物事を見ていることではなくて、中期、長期で物事を考えていくといったところでの要望書の提出です。コロナの影響でですが、東京都との関係の中で、要望書の提出を取り計らったところです。","id":"exchange-084"},{"speaker":"田中委員","kind":"質問・要望","question":"都との関係の中でというのがいまいち分からなかったので、そこの説明と、あと、補助２９号線の訴訟がある中、区民の中で反対意見というか、訴訟が起きている中での要望書が出された経緯、コロナのこの時期というのと、訴訟がまだ解決していない中での提出について、この２点について伺っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-085"},{"speaker":"田中委員","kind":"意見","question":"法的な問題とかではなく、区としてどういう考えでとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-086"},{"speaker":"田中委員","kind":"質問・要望","question":"しかし、それと一緒に駅周辺の再開発、まちづくり関連は、また別の話なので、少し違うのかというのを思うのと、要望書がなぜ出されたのか。なぜこの時期だったのかといったところを伺っていて、どういう意図で、どういう経緯でこの要望書を出すことになったのかということを伺っているので。","respondent":"中道まちづくり立体化担当課長","answer":"要望書を提出した経緯としましては、地域の声と区の事業への推進といったところでの要望活動の一環です。","id":"exchange-087"},{"speaker":"田中委員","kind":"質問・要望","question":"要望書は地域の声が上がってきたために出したということだったのですけれども、地域の声をどのようにとられて、どういった意見を……。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-088"},{"speaker":"田中委員","kind":"質問・要望","question":"でも、この中にも、区と連名で要望書を出したことについても触れていますし、そこは大事だと思いますので、伺っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-089"},{"speaker":"田中委員","kind":"質問","question":"今私が伺っているのは、日付ではなくて、なぜこの時期にというのを伺っているので……。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-090"},{"speaker":"田中委員","kind":"質問・要望","question":"なぜ連名で出すことになったのかということをお知らせほしいと求めました。","respondent":"中道まちづくり立体化担当課長","answer":"今、戸越公園駅付近は事業候補区間に位置付けられております。区といたしましても、これを準備中区間のほうに格上げをしたいといったところから、両者の思いで要望書を提出したところです。","id":"exchange-091"},{"speaker":"田中委員","kind":"意見","question":"地域の声があり、連名で出したということだったのですけれども、具体的に地域の声はどういった声があったのかというところをお知らせいただけますかとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-092"},{"speaker":"田中委員","kind":"質問・要望","question":"まちづくり事業と一緒に出した要望書については、この要望書を提出したのかということを質問した、そうではなくて……。〔「準備中区間になるからって言ったじゃん」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-093"},{"speaker":"田中委員","kind":"質問","question":"それは分かるのです。地域のどのような声があったのかということを伺っているので、そこをお答えください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-094"},{"speaker":"田中委員","kind":"質問","question":"ただ、それに併せたまちづくりに対しての地域の声というのを聞きたいのです。それに併せた駅周辺のまちづくり推進について、どのような区民の声があるのかというのを伺っているので、お答えください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-095"},{"speaker":"西本委員","kind":"質問・要望","question":"平成２６年に品川区に立体化の要望書を提出し、半年後に都へ提出して、それを受けて都は事業候補区間にしたということですよね。今回、令和２年３月に連名で要望書を提出したということで、この４年間何もなかったのか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"そういう中でいうと、前向きに連携を進めたいといったところの姿勢です。１つ、ここの町会で同じような取り組みでやっておりますので、商店街等々はすべて含まれているといったところです。","id":"exchange-096"},{"speaker":"西本委員","kind":"質問・要望","question":"ここが、今回は関係ありませんけれども、補助２９号線の開発も近くにあるということだと、そこの商店街含め、全体的に構図が変わってくる。非常にありがたいと考えていますので、今後もいろいろアドバイスをしていただきながら、進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-097"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"どうしても今、やはりある程度のまちづくりは関連した事業をやって推進していくということが必須になってくるのだろうと私は思っております。準備中区間にいち早くということであれば、それに対して議会でも一緒に協力をしていくべきだと考えていますので、採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-098"},{"speaker":"大沢委員","kind":"質問・要望","question":"近々では、東急目黒線の立体化によって、いい例も、私、間近で見ておりますので、これについては大いに賛成をさせてほしいと求めました。よって、採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-099"},{"speaker":"若林委員","kind":"質問・要望","question":"このまちづくり協議会の皆様、大変に熱意のあるお話も伺う機会がございました。２つ目の駅周辺の基盤整備、まちづくり関連の事業推進も、都としてもしっかりと取り組んでいただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-100"},{"speaker":"のだて委員","kind":"意見","question":"大体５階建てぐらいのまち並みに２３階、８５ｍのものが建つというものですので、不採択ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-101"},{"speaker":"田中委員","kind":"意見","question":"現在、コロナ対策について、東京都も、品川区でも対策がされている中で、今これを進めるべきなのかといった課題を感じます。ですので、継続にしたいと主張しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-102"},{"speaker":"西本委員","kind":"質問・要望","question":"これは早急に進めていただきたいということと、まちづくりなので、これからいろいろとまちの変化も出てくる可能性はあります。なので、関係者がほとんど入っているまちづくり協議会ですから、それから社会情勢を踏まえて議論をして進めていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-103"},{"speaker":"田中委員","kind":"質問・要望","question":"しかし、この事業が今本当に必要なのか。今はコロナ対策が喫緊の課題だということを感じておりますので、不採択とさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-104"},{"speaker":"のだて委員","kind":"質問・要望","question":"幾つか質問させていただきたいのですが、今回、防災生活道路にかかる公園ということで、ほかにもかかるところがあると思うのです。土地の所有者やアパートを借りている人など、それぞれ何人いるのか、伺いたいと思います。","respondent":"佐藤木密整備推進課長","answer":"本件事業につきましては、平成１９年度から行っております。先ほどご説明したとおりでして、本件のところが一番狭いところになっておりますので、本件については優先度が高いと認識しております。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問","question":"桜が切られてということになれば、やはり住民の皆さんの思いはやり切れないのではないかと思うのですけれども、いかがでしょうか。できるだけ桜、木蓮を残していくべきではないかと思いますが、いかがか尋ねました。","respondent":"佐藤木密整備推進課長","answer":"地域の方にはご説明をして、それでも地域の防災性の向上を優先していただいて、今回ご協力いただくことになりました。その延長線上にあると考えておりますので、事業を進めたいと考えております。","id":"exchange-106"},{"speaker":"のだて委員","kind":"質問・要望","question":"この桜を残してほしいという声と、やめてほしいという声もあるみたいですが、拙速に真っ先に切っていくということはすべきではないと思います。仮にこの陳情審査で採択となった場合は、工事を止めるということになるのか、区の判断を伺いたいと思います。","respondent":"佐藤木密整備推進課長","answer":"隣接する豊町五丁目については、最も危険な５となっているということで、防災性の向上が特に求められるという部分になろうかと思います。地域の防災性の向上のためにも、ぜひ今回実施させていただきたいと考えております。","id":"exchange-107"},{"speaker":"のだて委員","kind":"質問","question":"できるだけ最後にしてほしい、桜を残してほしいというささやかな願いだと思うのです。これを叶えていくということが、区の、行政としてやっていくべきことだと思いますけれども、いかがか尋ねました。","respondent":"佐藤木密整備推進課長","answer":"地域のご要望もお聞きまして、やらなくて、桜が終わってから７月の上旬に工事するということで説明をさせていただいているところです。繰り返しになりますけれども、地域の防災性の向上のために、予定どおり事業を進めさせていただきたいと考えております。","id":"exchange-108"},{"speaker":"のだて委員","kind":"質問・要望","question":"まだ住んでいる方がいらっしゃいますし、そういった方々は、ここに住み続けたいということで住んでいるわけです。こうした住民要望をしっかりと叶えていくということで、強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-109"},{"speaker":"田中委員","kind":"質問","question":"委員会資料の中で、樹木診断を実施した際に、移植が不適であるとの診断結果だったということなのですけれども、これはあくまでも移植が不適なだけで、樹木の状態についてはどうだったのかというところを伺いたいのですが。","respondent":"高梨公園課長","answer":"公園課で実施をしておりますので、樹木診断の結果と併せて、私からお答えします。同じく４段階中３番目の著しい被害が見られる結果、傷んだ桜の部類に属している、このように考えているところです。","id":"exchange-110"},{"speaker":"西本委員","kind":"質問","question":"キノコが生えたり、空洞があったりということで、木の有効活用というのは何かできないのですか。どういう歴史があるかまだ私も分からないので、本当にそうなのかどうか分からないのですけれど、いかがか尋ねました。","respondent":"高梨公園課長","answer":"さらにそれが１０m2弱削られるということで、新たな施設がそこに設置できるかといったところは、慎重な検討を要するのかといった部分です。ただ、その状況で何らかの記念碑というところは難しいのかと思いますが…","id":"exchange-111"},{"speaker":"西本委員","kind":"質問・要望","question":"深い意味があったのかどうかよく分からないというところがあるのですが、そういう経緯があるのかどうかだけの確認をしていただきたいと思うのです。ぜひ少しで結構ですので、よろしく検討をお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-112"},{"speaker":"若林委員","kind":"質問・要望","question":"どうしても広げなければいけないということであれば、これは質問というか、要望させてほしいと求めました。６ｍ道路に整備されているのか、これからまさに整備されようとしているのか、ここら辺はどうなっていますか。","respondent":"佐藤木密整備推進課長","answer":"６ｍへの整備なのですけれども、位置図でいいますと、その重なっているところから南のところ数軒というところです。６ｍのところでいきますと、５ｍ以上道幅はあるのですけれども、ここが最後と言ってよろしいかと考えます。","id":"exchange-113"},{"speaker":"若林委員","kind":"意見","question":"一つのボトルネックになっていて、防災上、客観的に好ましくないと感じると思います。品川区のほうもその意を酌んで今年は桜を切らなかったという真摯なご努力は、私はこれは認めなければいけないのかという感想をもっておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-114"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"台場小学校の校舎建替えのときに、切った木を１ｍぐらい学校に転がしてもらいました。それはそれだけお願いをしておきますが、基本的にはこの陳情については不採択。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-115"},{"speaker":"大沢委員","kind":"質問・要望","question":"品川用水です。そこら辺の確認をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-116"},{"speaker":"若林委員","kind":"質問・要望","question":"本日結論を出すで、先ほど意見も要望も含めて申し上げました。これについては、不採択ということで、判断をします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-117"},{"speaker":"のだて委員","kind":"質問","question":"親しまれているこの桜と木蓮の木を切らないでほしいというのはささやかな願いですから、できる限り地域の方を癒やしてほしいと思います。結論を出す、採択で。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-118"},{"speaker":"田中委員","kind":"意見","question":"本日結論を出すで、採択を主張します。地域の声もあることですし、木をまだ生かせてあげられたらと思いますので、採択したいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-119"},{"speaker":"西本委員","kind":"確認","question":"不採択でお願いいたします。事実かどうか分からないのですけれども、少し確認をしていただいてということで、その配慮をお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-120"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/733618?Template=document&Id=4294#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":71857,"voices":335}},{"id":"r02-20200629-9","meetingId":"r02-cm06","date":"2020年6月29日","dateIso":"2020-06-29","committee":"文教委員会","time":"午前１０時００分～午前１１時５５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"６月２５日のあべ議員の、という質問なのですけれど、あるいは子育て世代の置かれた実態をつかむ上で必要なことと私も思います。なぜ困難なのか、国の指針の内容なども併せて、教えていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"あべ委員","kind":"質問","question":"６月２６日の中塚議員ならびに松本議員から、学校の校則についての質問が出ました。ちょっと不明な点もありましたので、改めて教育委員会の学校の校則に対する現状の把握と、今後の考え方についてお伺いできればと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"}]},{"id":"topic-02","title":"第４３号議案、品川区立児童センター条例の一部を改正する条例および品川区立保育所条例の一部を改正する条例の一部を改正する条例","agenda":"第４３号議案、品川区立児童センター条例の一部を改正する条例および品川区立保育所条例の一部を改正する条例の一部を改正する条例","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"コロナの関係で工事が遅くなるというのは、大変理解はするところです。細かい区切り方で、当初の２２日後、約３週間後ということなのですけれども、これの竣工そのものというのは何日になっているのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"竣工ですけれども、当初は令和２年８月３１日でございましたが、今回、令和２年９月１８日の予定です。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問","question":"１つだけちょっと心配に思っているのが、ちょっと気分が悪くなるというようなことも、以前大分問題になったと思います。揮発していないままに急いで使い始めるということにならないかという、その辺、いかがお考えか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"浮遊物の検査を含めまして、９月１８日の竣工予定です。前回も当初の予定が８月３１日ですけれど、その際も、浮遊物の検査が終わって引渡しという予定で進めていたところです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"具体的にはどういう状況で休止になってしまったのかというのが分かれば、お伺いしたい。併せて、建替え・改修を終えて現在地でこの保育園と児童センターが開園する時期というのはいつ頃を予定しているのかも伺います。","respondent":"吉田保育施設調整担当課長","answer":"大和リース株式会社より４月２５日から５月１０日まで休工したいという旨の申出について、コロナの状況、休工期間を認めたところです。９月１９日から２２日までの間で児童センター、保育園の引っ越しを行いまして、９月２３日から新しい場所で稼働する予定です。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"学校のほうではコロナの影響はどうかなということと、あと最後のところは、一旦仮移転してまた戻ってきて、元の場所で建替えするではないですか。その建替えが終わって、こちらの元の場所で児童センターと保育園が開園するのは大体いつ頃なのかなというのが分かれば。","respondent":"有馬庶務課長、吉田保育施設調整担当課長","answer":"ゴールデンウイーク前後、影響としては３日程度休業したいという申出があって、その間は休工したという例があります。やはりゴールデンウイーク前後に３日ほど休業要請がありましたので… 東大井公園を利用して建替えが終わり、戻ってくる時期ですけれども、予定としましては２０２２年の１０月を目途としています。","id":"exchange-006"}]},{"id":"topic-03","title":"第４４号議案、品川区放課後児童健全育成事業の設備および運営の基準に関する条例の一部を改正する条例","agenda":"第４４号議案、品川区放課後児童健全育成事業の設備および運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"ちょっと伺いたいのと、この資格研修の主な研修内容と、研修回数や時間というのはどれくらいなのでしょうか。伺います。","respondent":"廣田子ども育成課長","answer":"実施主体が増える経緯ですが、令和２年３月３１日まで経過措置がございまして、当面は修了予定でよかったということがありました。放課後児童クラブにおける子どもの育成支援について、安全・安心の対応について、大きな括りだとそのようなものがあります。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"これ、２３区、特別区が加わるという話というのはなかったのでしょうか。むしろ、人口からいうと２３区もこうした権限を持ってもいいのではないかと思うのですが、そうした議論があったかどうか説明を求めました。","respondent":"廣田子ども育成課長","answer":"東京都で実施している研修が、例えば品川区で実施主体になれたとしても、受けやすいかとは思ってあります。","id":"exchange-008"}]},{"id":"topic-04","title":"第３９号議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第３９号議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"今後の供給体制とか確保の見通しというのはどのように、楽観できるのかどうか、ちょっと伺いたいなというのが１つ。認証を含む私立保育園ですとか幼稚園のほうにはされたのかどうか、すみません、確認させてください。","respondent":"三ッ橋子育て応援課長、若生保育支援課長","answer":"私どもが寄附したり、そのような状況がありますので、現在のところはマスクは十分足りている状況となっております。今後の供給につきましては、子ども食堂ネットワーク事務局と連携を取りながら、何かご要望がないか… こちらは区立等と同様、国ですとか都のほうから配付されている分を、各園のほうに配付するという対応を行っております。それと別に、４月の補正予算で、保健衛生関係の物品購入の補助ということで…","id":"exchange-009"},{"speaker":"安藤委員","kind":"確認","question":"減額された予算の扱いについてちょっと確認したいのですが、都に補助金を申請し直すという感じのイメージでいいのか、教えてください。2)、3)とあるのですけれど、それぞれの対象世帯数というのはどれぐらいいるのか伺いたいと思います。","respondent":"吉田保育施設調整担当課長、三ッ橋子育て応援課長","answer":"オリンピック・パラリンピックの保育園における来年度の予定ですけれども、これは来年度の予算編成の中でまた決めていくものと予定しております。それから各園ごとの熱中症対策として、１園当たり１万円を配付いたしまして… 2)につきましては、公的年金の関係ですので、約７０世帯と想定しております。3)につきましては、実際の児童扶養手当の対象よりは少ないと見込んでおりまして、約１,５００世帯と見込んでおります。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"さらに子どもが２人以上いれば第２子以降１人につき３万円ずつ加算という理解でよろしいでしょうかということを確認させていただきたい。併せて、その収入が減少していることの申請が必要とありますが、実際の申請の内容というのはどういう申請なのでしょうか、伺いたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"収入の見込額、収入が減少したかどうかのチェック、こちらは自己申告になります。そして、そのほかの収入の見込みですが、例えば療育費、給与収入、事業収入などの収入の相当額に関して幾らなのか。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"（２）、そちらの工夫というのをやはりぜひ具体化してほしいと求めましたが、いかがでしょうかということです。大体何事業者ぐらいいらっしゃるのか分かれば、ざっくりでもいいのですけれど伺いたいのと、イメージをつけるために教えてほしいと求めました。","respondent":"三ッ橋子育て応援課長、篠田学務課長","answer":"対象となる方、例えば公的年金で今まで児童扶養手当が全部停止されていた方というのは把握できますので、そちらの方にはお知らせをしていく予定です。… 事業者の数ですけれども、約６０事業者〔翌日「４５事業者」と答弁訂正あり〕が今回こちらの対象となっているものです。魚、野菜… 周知について補足いたしますが、広報紙なども使って周知してまいります。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういう方が対象になっているわけですから、これは要望なのですが、もし何かありましたらぜひご答弁ください。当然、食材納入業者への発注も減ってしまっているということでいいのか伺いたいと思います。","respondent":"三ッ橋子育て応援課長、篠田学務課長","answer":"委員ご指摘のように、周知につきましてはアプリやツイッター、そして民生委員協議会にお知らせするなど、様々な工夫をしてまいります。 コロナウイルスの感染状況が落ち着いたものではないので、当面はこの７月いっぱいまで、この形での提供を続けていくことを予定しているものです。確かに全体の量としては若干、できるだけバランスが取れるような形で…","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"タブレットの件ですが、区立校の児童・生徒数プラス教員数だと伺っているのですけれど、それらの活用というのはどうなるのか伺いたいと思います。その活用の仕方で、その辺についての活用の仕方、そういう観点からの区のお考えを最後に説明を求めました。","respondent":"篠田学務課長、工藤指導課長","answer":"２,６００台のこの機械の取扱いなのですけれども、校内で活用するとかといった形で、一切無駄にならないように考えております。１つの学校で４０台しかございませんので、そういった学校のほうに持っていけば… タブレットの今後の活用の仕方のところについてお答えをします。教職員の研修も含めて効果的な活用の仕方を進めていくのですが、配慮して進めていきたいというふうに考えてあります。","id":"exchange-014"},{"speaker":"あべ委員","kind":"質問","question":"引き続き幾つかお伺いしたいと思います。これ、減額はするのですが、残りの金額というのが少しあるのか尋ねました。","respondent":"三ッ橋子育て応援課長、若生保育支援課長、吉田保育施設調整担当課長、篠田学務課長、工藤指導課長","answer":"委員のご指摘のように、まずは全体の数を予算として見込んでおりまして、順次開催しているところから配っていくというように考えております。… そうしたところで所管するところが適切に支援を行っているところと捉えております。今回、区としてあくまでも事業者に対して支援を行っている… この辺は都のほうとも確認いたしまして、４月の健康診断につきましては今回、やらないとしたところです。これにつきましては既に配付しております。 現実問題として、４月…","id":"exchange-015"},{"speaker":"あべ委員","kind":"質問・要望","question":"健康診断も別に不要不急のものではもちろんないものですから、特に新入学生などについては見落としのないようにしてほしいと求めました。ひとり親で公的年金受給者という、これは障害年金などをイメージしたらいいのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"公的年金を受給している方の場合は、例えば遺族年金、障害年金などの方が対象となります。","id":"exchange-016"},{"speaker":"あべ委員","kind":"質問","question":"遺族年金と障害年金がほとんどのイメージかと。その中で、６月分手当支給が全額停止される方というのは、その中で所得が基準を超えた方というイメージなのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"全額停止された方というのは、公的年金のほうが児童扶養手当よりも多くもらっているので、全額停止となっております。","id":"exchange-017"},{"speaker":"あべ委員","kind":"質問","question":"とすると、対象者が確定するということになるのではないかと思いますが、この方々もやはり申請しないと受け取れないということなのでしょうか。申請が必要であっても少なくともその対象者全てにご案内を送ることぐらいはできるのではないかと思いますけれど、いかがか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"先ほど周知につきまして、（１）の児童扶養手当の方には直接周知と申しましたが、確かに委員おっしゃるとおり、公的年金の方も把握はしておりますので、先ほど触れたのですけれども、分かる方に関しては、全額停止されている方に関しては周知していく予定です。","id":"exchange-018"},{"speaker":"あべ委員","kind":"確認","question":"少なくともここに申し込んでいる方のうち、教育委員会のほうに伺いますけれども、就学援助は今どのくらいの方が受けていらっしゃるのか。それから、特に今年の収入激減で、昨年度の所得に関わらず新たに就学援助の対象になった方はどのくらい今、いらっしゃるのか尋ねました。","respondent":"三ッ橋子育て応援課長、篠田学務課長","answer":"公的年金の部分ですけれども、公的年金を受給されていて児童扶養手当を全額停止されている方については把握できておりますので、その方には通知してまいります。 例年ですと就学援助に関しては４月末に締切りまして、コロナの関係があったものですから、締切りを５月末まで延ばしております。現在はちょうど集計中なものですから、こちらのほうはまた…","id":"exchange-019"},{"speaker":"あべ委員","kind":"質問","question":"これはひとり親ですからお子さんがいらっしゃいますので、１つには就学援助、さらにひとり親の方については特別給付金もありますと。いつ頃までに申請すればいいのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"こちら、３月３１日〔同日後刻に「２月末」と答弁訂正あり〕まで、年度内にきちんと申請してくださった方というふうに考えております。ただ、３１日ぎりぎりではなく、早めに申請していただければと考えています。","id":"exchange-020"},{"speaker":"あべ委員","kind":"質問","question":"実際にはそのひとり親状態、ひとりで子育てをしているけれども、法律的に離婚ができていないという方々は対象になると考えてよろしいのでしょうか。ここの扱いはいかがか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"実際に離婚されている方、また調停中の方、いろいろといらっしゃるかと思いますけれども、その方に関しましてはご相談いただいて、そのときの状況で判断してまいります。","id":"exchange-021"},{"speaker":"あべ委員","kind":"質問","question":"ＩＣＴ活用推進校のほうは、今使っているものというのはもう老朽化で廃棄とかいう感じなのですか。それともダブルで持っているということか尋ねました。","respondent":"篠田学務課長","answer":"パソコン教室用の４０台しか配備してございませんので、そういった学校にも一定程度流すことによって、台数の平準化等が図れるのではないかと。どのようになるかという具体的な形はまだ見えていないのですけれども…","id":"exchange-022"},{"speaker":"あべ委員","kind":"確認","question":"Ｗｉ－ＦｉモデルなのでＷｉ－Ｆｉがあればつながるということで、その学校のＷｉ－Ｆｉにしかつながらないような機械というのはあるのですか。今後その第２波が来年度までに来た場合に、かつ貸与用にも使えるのではないかと思うのですけれど、いかがか尋ねました。","respondent":"篠田学務課長","answer":"これは台数的には４５４台という形なのですけれども、セルラー対応をしていきたいと思っており、その辺の検討を進めているところです。どこまでできるかというのは、まだ問題はあるのですけれども、そういった形での台数の確保もできるだけしていきたいと思っているところです。","id":"exchange-023"},{"speaker":"あべ委員","kind":"質問","question":"新たに入れるものはセルラーモデルとのことなのですけれども、これは学校内で使うときもセルラーでということになるのでしょうか。何かあっという間に終わってしまって、もう今月は無理ね、みたいな話になってしまってはストレスですけれど、そこはどうお考えか尋ねました。","respondent":"篠田学務課長","answer":"学校内においては校内無線ＬＡＮが全て整備をされていますので、無線ＬＡＮがつながるような形での設定をと考えています。それから外に持ち出して、ご家庭に持っていったときにはセルラー対応にするといったようなことを考えているものです。","id":"exchange-024"},{"speaker":"あべ委員","kind":"質問","question":"ということは、休校になったときには動画で使える量というのはかなり制限がされるというイメージでよろしいのでしょうか。そういう学校外で、例えば自宅で授業を受ける、動画を見る、双方向というのはかなり絞って使うイメージか尋ねました。","respondent":"篠田学務課長","answer":"今のところ、回線のほうの契約は１月当たりの上限を１０ＧＢ程度というのを考えているところです。休校期間中がどのぐらいになるかにもよるのですけれども、そういうことも踏まえながら、検討をしていきたいと考えています。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問・要望","question":"ひとり親世帯臨時特別給付金について確認なのですけれど、実施主体は区で、先ほど話に出ました世帯数などを逆算してこの額にしたのかということ。３点ほど質問させてほしいと求めました。","respondent":"三ッ橋子育て応援課長","answer":"最初の２点に関しては、委員のご指摘のとおりです。最後の周知に関しまして、事務費という部分では、例えば児童扶養手当の方に申請のお知らせをしていくという費用も含まれております。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問・要望","question":"先ほど周知のことについて、ほかの委員からもいろいろなご要望がありましたけれども、ぜひ丁寧な周知をお願いします。次に、もしくは既にもう所有などをされているのかを確認したいのですが、その点いかがか尋ねました。","respondent":"吉田保育施設調整担当課長、篠田学務課長","answer":"次亜塩素酸水の噴霧器については、今回の予定の中には入っておりません。 教育委員会での購入予定ですけれども、次亜塩素酸水の噴霧器については、予定はしていないです。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"６月１６日に学校における新型コロナウイルス感染症に関する衛生管理マニュアルで、今後品川区としては、取り扱う予定というのはあるのでしょうか。その見解をお願いします。","respondent":"篠田学務課長","answer":"現状は、通常の雑巾等による拭き取りのほうが確実にできるということがあるので、今のところは、噴霧器を使用して対応するということは考えていないということです。","id":"exchange-028"},{"speaker":"横山委員","kind":"質問","question":"ひとり親世帯臨時特別給付金についてなのですけれども、こちらの周知方法のところに１、（２）、1)の対象者の方へは別途案内を送付というふうに書いてあるのですが、この別途案内については、追加給付についての案内も同封されるということでよろしいのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"はこの周知、今回のひとり親世帯臨時特別給付金のご案内をしまして、加えて辞退届を送付いたします。そして、段階を経て、追加給付のお知らせについてはまた改めて、現況届と同時の状況でお知らせする予定です。","id":"exchange-029"},{"speaker":"横山委員","kind":"質問・要望","question":"そのあたり確認をさせていただきたいと思っていました。ふだん支援を受け慣れていない方というのは、ぜひそういったところもサポートしてほしいなと思っているのですけれども、お考えを説明を求めました。","respondent":"三ッ橋子育て応援課長","answer":"委員のご指摘にありますように、ひとり親世帯の方は就労支援や、また子どもの学習支援など、区が様々行っている支援に気づけない方も非常にいらっしゃると思いますので、鋭意工夫しながら通知していきたいと思います。","id":"exchange-030"},{"speaker":"横山委員","kind":"確認","question":"様々な機会を捉えてこちらから発信をして、キャッチしたり、支援の状況を確認しながら対応していただくようにぜひお願いをしたいと思います。考え方といいますかどういった形で見直していったりというか、全体の方針といいますか、そういったあたりをお聞かせいただけたらと思います。","respondent":"有馬庶務課長、廣田子ども育成課長、工藤指導課長","answer":"今は、修学旅行については大きな課題ということで、検討しているところです。そういったものも６月の段階では中止ということで… 子ども未来部関係に関しましては、やはり後半、３密になるようなものに関しては基本的には行わないような形で検討しています。… 今後授業等が行われる中では、その範囲で行えるものは実施していきたいというふうに考えております。ただ、やはり３密を回避しながら…","id":"exchange-031"},{"speaker":"横山委員","kind":"質問・要望","question":"状況がどうなるかというのも、子どもや保護者の方のお考えですとか、有効性ですとか効率性というところも見てほしいと求めました。何が子どもたちにとって一番の選択肢、今後事業見直し等をしていただけたらというふうに思っているのですが、一言お願いできればと思います。","respondent":"工藤指導課長","answer":"例えば私ども予定していた、現状でいえばそれをいわゆるウェブ配信としているように、そういった対応にする。実施はするのですがその中身についてはやはり効率よくというところを、視点に持ちながら進めたいというふうに考えてあります。","id":"exchange-032"},{"speaker":"たけうち委員","kind":"質問","question":"それをどこに設置をして、熱があると分かったときに音が鳴るのか、誰がチェックをしてどういう対応をするのかというのを教えてください。仮に２月以降とすると、この２月以降どこまでの収入を見て、１２倍してというふうになるのか説明を求めました。","respondent":"篠田学務課長、三ッ橋子育て応援課長","answer":"例えば３７.５度という形に設定すれば、そのお子さんについては個別に保健室等に案内するといった対応になってくると思います。あれよりもかなり精密な形のもの、その３種類を用意しまして… あべ委員との質疑の中で、ちょっと交付金の関係で２０２１年の２月末を給付金の締切りとしますので、訂正いたします。申し訳ありませんでした。","id":"exchange-033"},{"speaker":"たけうち委員","kind":"質問・要望","question":"細かいけれども、一月にこれがあってそれが１２倍して昨年と比べて、みたいなことが分かるようなものをきちんと送っていただくということでしょうか。なるべく早く出したいのだけれど、ただ、いろいろ周知をしていただきたいと要望いたしまして終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"せお委員","kind":"質問","question":"すみません、１点だけお伺いしたいのですけれど、保育園、幼稚園や学校での健康診断のお話がたくさんあったと思うのですが、健康診断をする際の手順といったものというのは、校医とか園医に任せているという感じでよろしいか尋ねました。","respondent":"吉田保育施設調整担当課長、篠田学務課長","answer":"一般的なところでは、遊戯室等に健診を行う先生と補助でつかれる先生がいらっしゃって、そこに保育士が連れていくといった対応をしてきたところです。ただ、今後３密を防ぐというところにつきましては… 今回こういった形でコロナウイルス対応というのがありますので、例えば通常よりも大きい部屋で換気をよくしたりといった形で、学校側でできるだけそういった感染予防に尽くした形での対応を取っていくようにと考えているところです。","id":"exchange-035"},{"speaker":"せお委員","kind":"質問・要望","question":"しっかりしたマニュアルなどを再度確認していただいて、しっかりした、統一した感染症対策をお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"あべ委員","kind":"質問","question":"すみません、１つ聞き損ねておりました。給付金に関係して、外国籍あるいは日本語が十分に理解できないご家庭への周知方法をどのようにお考えか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"確かに委員ご指摘のように、外国籍の区民の方もいらっしゃいますので、例えばホームページ上で工夫するなど、あとは問合せがあったときに対応していこうと考えています。","id":"exchange-037"},{"speaker":"あべ委員","kind":"質問・要望","question":"そこまですごい数字にはならないと思います。保育園そして学校、そうしたところとぜひ連携を取って周知をしていただきたいと思うのですが、いかがか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"関係する所管部署と連携しながら、外国籍の方にもきちんと申請していただけるように周知してまいります。","id":"exchange-038"},{"speaker":"芹澤副委員長","kind":"確認","question":"幾つか確認したいのですが、これから残りの２万３,０００台と同じ機種を使っていって、一緒に使っていくのかということ。これはこれまで使ってきたドリル等の話ではなくて、新たな契約が結ばれるという認識でよろしいのか尋ねました。","respondent":"篠田学務課長","answer":"予定ではそれまでには区のほうで１人１台の配備がされているという前提ですので、そちらの対応は大丈夫なのかなというふうに考えているところです。台数的には例えばタブレット型を３台入れている学校ですとか、様々な形で、必要な形で対応していただいているところです。","id":"exchange-039"},{"speaker":"安藤委員","kind":"意見","question":"感染症対応で今、学校現場が消毒や７時間授業の対応に伴う授業準備が大変になっているなど、現場の負担がかなりなものになっていると思うのです。教員増や学校スタッフ増など、人的配置の支援などもぜひ具体的に支援していっていただけばという意見を申し上げしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/418457?Template=document&Id=5006#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":36271,"voices":148}},{"id":"r02-20200629-5","meetingId":"r02-cm06","date":"2020年6月29日","dateIso":"2020-06-29","committee":"総務委員会","time":"午前１０時００分～午後 ２時５１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を88件整理しています。","topics":[{"id":"topic-01","title":"案審査を行います。 予定表では、(1)第４０号議案からの審査でありますが、会議の運営上、順番を入替え審査を行います。 まず…","agenda":"案審査を行います。 予定表では、(1)第４０号議案からの審査でありますが、会議の運営上、順番を入替え審査を行います。 まず…","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"契約金が１１億円余から６００万円余の減額ということで、適宜確認しているのでこういう変更も可能といいますか、ちょっとその辺のところをご説明いただけますか。","respondent":"松本河川下水道課長","answer":"そういった確認の中で、当初の設計と差異が生じたものについて変更しています。工期は、７月１６日までということで、来月完了となりますので、その前に終わっている工事全てについて、今回、変更した状況となっています。","id":"exchange-001"}]},{"id":"topic-02","title":"第４９号議案 第一日野小学校擁壁改修その他工事請負契約","agenda":"第４９号議案 第一日野小学校擁壁改修その他工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"私も第一日野小学校の歩道橋だったり、擁壁だったりを直接見てきましたけれども、結構な高さがあるなと思い、工事そのものは必要だと考えています。１８ページの資料で、放射２号線計画に協力するため教育財産を都に売るという計画なのかどうか、その点だけ確認させてほしいと求めました。","respondent":"東野経理課長","answer":"こちらの第二グラウンドの工事に合わせまして、計画地のところにつきましては、都へ売却を予定しています。こちらは本年の予算特別委員会でも審査を行っております。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"最後に１点だけ、放射２号線の部分と学校との境界線というのでしょうか、どういう構造になるのでしょうか。単にフェンスが張られるだけなのか、それとも道路と平らにというか、つながるという状況になるのか、そこの工事の形をご説明いただけたらと思います。","respondent":"小林（道）学校施設担当課長","answer":"工事内容につきましては、全てやり替えのときに、要綱に沿って、まず接道緑化があります。道路の接道緑化を行うということで、今現在、放射２号線の通りの面に、接道緑化、緑化帯を設ける予定で計画をしております。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"１７ページの工事内容で、フラットだと思うのですけれども、これもやっぱり擁壁というくくりで工事をするのでしょうか。セットバックして、どれくらいグラウンドが小さくなるのか、もし分かれば説明を求めました。","respondent":"小林（道）学校施設担当課長","answer":"セットバックにつきましては、放射２号線側を除く３面、ここについては、まず歩道状空地ということで１.５ｍの歩道を作ります。今言ったようにセットバックしていきますので、数字的には、約２割ぐらいは小さくなってくると思います。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"その接道緑化について、知識がなくて分からないのですが、学校の施設として道路と接するところは緑化をするという理解でよろしいのでしょうか。接道緑化ということで緑化はいいとは思うのですが、今回はその土地をそのための空間に使うという理解でよろしいのか尋ねました。","respondent":"小林（道）学校施設担当課長","answer":"基準法上では、建物だとか、擁壁みたいな工作物は築造してはならないというふうに法律で決まっております。二重投資を避けるべきだとも思いますので、そういうところでも敷地内で建設をするというところが妥当だと思います。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"では、そこを接道緑化のための敷地に使うのは大丈夫ということか、そういう感じなのか尋ねました。","respondent":"小林（道）学校施設担当課長","answer":"都市計画道路放射２号線の部分は建築基準法上の道路になりますので、現状は周囲４面が道路に接しているという解釈です。その中で今回計画をしています。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"ここの部分は、特に老朽化した擁壁の改修というよりも、むしろ東京都に道路事業として協力するためにセットバックするという工事になるのでしょうか。その部分だけ工事しなければグラウンドの広さはその分だけ残ると、そういう考え方は技術的にもできないものなのか、その点を伺いたいと思います。","respondent":"小林（道）学校施設担当課長","answer":"擁壁の安全性について確認ができないというところで、教育委員会としては、擁壁を改修するということを決めたところです。その後に放射２号線とか、要綱に基づいたセットバックだとか、いろいろなものがありますので、法等に沿って工事を計画しています。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"ということは、放射２号線に接している擁壁もその老朽化が改修工事を行う理由になるのか尋ねました。","respondent":"小林（道）学校施設担当課長","answer":"そのとおりです。周囲４面の擁壁は、３０cm位からあるのですけれども、周囲４面全てを改修するという判断をしたところです。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"反対したいと思います。ぜひ安全に進めてほしいと求めましたが、やはり強い反対の声が挙がっている放射２号線整備に協力するものだと思いますので、反対です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"吉田委員","kind":"意見","question":"生活者ネットワークとしては、やはり放射２号線のことはどうなのかというのはありますし、近隣からもそういうお声はたくさん頂いています。ただ、この擁壁自体は、私も見ましたけれども、結構危ないかなというようなところも、素人目に見てもありましたので…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"}]},{"id":"topic-03","title":"小学校校舎・幼稚園園舎改築その他工事請負契約、(8)第５１号議案 浜川小学校校舎・幼稚園園舎改築その他機械設備工事請負契約…","agenda":"小学校校舎・幼稚園園舎改築その他工事請負契約、(8)第５１号議案 浜川小学校校舎・幼稚園園舎改築その他機械設備工事請負契約…","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"事故なく、ケガなく進めていただきたいと考えていますが、この浜川小学校・幼稚園園舎改築その他工事は規模が大きいので、ここで伺おうかと思っていたのですけれども、コロナ対策と熱中症対策は契約金額にどのように反映されているものなのか、その点を伺いたいと思います。","respondent":"小林（道）学校施設担当課長","answer":"コロナ対策、熱中症対策につきましては、経費の中にそれぞれ含んでおります。それぞれのＪＶが責任を持って対応するというところになっております。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"マスクも熱中症との関係で、それぞれ現場の安全第一で判断がされるべきだとは思いますけれども、やはり心配なところがあるのです。コロナ禍の下、初めての夏を迎えるという意味でも大切なことだなと思っているのですけれども、いかがか尋ねました。","respondent":"小林（道）学校施設担当課長","answer":"それとあと、密集を避けるために、作業間隔をあけたりとか、そういう形で現場のほうは対応しているところです。休憩室にはクーラーを付けて、ただ、新型コロナウイルス感染症対応がありますので換気をとりながら。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"いろいろ対応をとられているということですけれども、現場の方とよく協議しながら、安全に、事故なく、ケガなく進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"工期が約５年間ですか、令和７年までで、すごく長いと思うのです。品川区は嫌われているのですかと逆に思ってしまうのですけれども、もっと入札に参加できるような方向性、仕組みは作れないのか尋ねました。","respondent":"小林（道）学校施設担当課長","answer":"それが今回建設を計画している部分は１万２,０００m2で、かなり大きくなっているので工期が長くなるというところです。そこら辺までは私のほうで把握はできませんけれども、不調にならずに済んでいるというのは、品川区の業者の力があってなのかと考えています。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり我々も総務委員会で何度か確認していますが、改善ということで、経理課として何か方法論は日頃考えていらっしゃるのですか。それとも、このまま、不調というのは困るから、このような状況で今後も継続していくということなのか尋ねました。","respondent":"東野経理課長","answer":"区内業者への発注という部分につきましても、これも長年区として取り組んできたものです。考え方としては、こちらの要綱に従った発注を今後も続けていきたいと思っているところです。","id":"exchange-015"},{"speaker":"須貝委員","kind":"質問・要望","question":"１点だけ。参加できるような仕組みにして、多くの区内業者を育成するような仕組み作りを今後も考えていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問・要望","question":"何点か伺いたいのですが、よく分からないので教えていただきたいのですが、昇降口と職員玄関で２方向というような感じでよいのでしょうか。それと、外の非常階段というのは、どうなのか尋ねました。","respondent":"小林（道）学校施設担当課長","answer":"２方向避難につきましては、委員おっしゃるとおり、屋内階段、屋外階段を利用しての２方向避難等を検討しております。人工芝であれば雨が降ったあと、早い時期から校庭が使用できるというメリットがありますので、現在はそういう方針で動いております。","id":"exchange-017"},{"speaker":"吉田委員","kind":"提案","question":"前に環境課に伺ったら、環境課としては提案するが、今回はそれは難しかったということなのでしょうか。給水設備というのはあるのですけれども、それは違うのか、その辺も確認させてくださいとの意見を述べました。","respondent":"小林（道）学校施設担当課長","answer":"もう１つ、太陽の熱を使って給湯、そこで温めたものを給食室のお湯とかシャワーに省エネのため補助的に使うというところの違いがあります。それとあと、トイレでの雨水の利用につきましては、雨水をためて、ろ過、消毒をした後、トイレの洗浄に使用する計画で今現在進めておりま…","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問","question":"図面に太陽光パネルは出ているのですが、太陽熱はどのように、太陽光パネルとの一体型で熱利用もできるということなのでしょうか。その辺をもう１回お願いします。","respondent":"小林（道）学校施設担当課長","answer":"それを屋上に設置します。１つの建物を造るわけですので、すごい細かくなってきますし、今回は入札の経過ということも含めて、概要ということで多少絞っております。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問・要望","question":"資料で確認していて、もうちょっと自慢してくれてもいいのになというぐらいですので、ぜひそれは今後も進めていってほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"湯澤委員","kind":"質問","question":"この間に児童はどのような形で授業を受けて、また昼休み等はどういった形で過ごすのかということを教えてほしいと求めました。図面にサービス門とあるのですが、これは分からないので、サービス門というのはどういったものなのかも教えてほしいと求めました。","respondent":"小林（道）学校施設担当課長","answer":"これが令和５年度末に建設終了の予定です。最後に、グラウンド整備工事を行いまして、令和７年頃に全てを完了する予定で、現在、進めております。","id":"exchange-021"},{"speaker":"湯澤委員","kind":"質問・要望","question":"本当に学校は子どもたちのためのものでありますので、ぜひ子どもたちを最優先に考えて工事を進めてほしいと求めました。工期が長いので、工事に携わる方々の気のゆるみがないように、ケガ等なく安全第一の工事を行ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"松澤委員","kind":"確認","question":"人工芝のことで１件、確認をしたいのですけれども、そこにやぐらを置けないので使えなくなってしまいます。それとも、ある程度、土のグラウンドは残していくのかというような、もしお考えがありましたら教えていただけると。","respondent":"小林（道）学校施設担当課長","answer":"教育委員会としましては、生徒が使用する校庭につきましては、今現在のところは人工芝を選定して進めているところです。先ほども粉塵等で近隣にご迷惑をおかけしているというところも考えて、いろいろな方面から考えて、苦渋の選択で人工芝化を進めているものです。","id":"exchange-023"},{"speaker":"松澤委員","kind":"意見","question":"雨水が出るようなところに、そういう網を設置するような、そういうようなものは学校施設の中で考えているものはありますかとの意見を述べました。","respondent":"小林（道）学校施設担当課長","answer":"どうしても人工芝は貼り合わせで、メーカーのほうでもそこら辺の処理ができないのかというのは、日々こちらのほうから要望を出しているところです。それとあと、委員がおっしゃるとおり、何かで覆えないかということも含めて、今現在、検討しております。","id":"exchange-024"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"１点だけ確認します。災害があったときの対応というのは、どのように連携をとられていくのかということだけ確認させてほしいと求めました。","respondent":"小林（道）学校施設担当課長","answer":"避難所としては、当然、体育館が壊れたときには避難所ではなくなりますので、これについては防災課とも綿密な打合せをして、建設中はそこから外してもらうというところで現在進めております。","id":"exchange-025"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"いつ起こるか分からない、豪雨もありますし、地震もあります。しっかりまたそこは連携をとって進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"}]},{"id":"topic-04","title":"第５３号議案 マイスクール八潮空調設備改修工事請負契約","agenda":"第５３号議案 マイスクール八潮空調設備改修工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"金額は１億７,０００万円余ということですが、この工事の内容や価格に何か関係があるのかないのか、そこを伺いたいと思います。ちょっと高いような気もするし、八潮団地には独自の熱供給システムがあるではないか尋ねました。","respondent":"小林（道）学校施設担当課長","answer":"時間外で個別に例えば５時とか、不経済になりますので、そこでは個別空調を部分的に付けております。そういうことで使い分けをしているところでの今回の工事です。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"そういう八潮特有の構造によって、価格はむしろ下がるのか、それとも上がるのか、そういう関係はどうなのですか。ぜひ下がってほしいとは思いますけれども。","respondent":"小林（道）学校施設担当課長","answer":"価格がどうなのかということは、工事自体においてそのプラスアルファのお金は出てきます。実際はそういう比較を私のほうでしたことはございませんけれども、そちらのほうで精査というか、それが考えられるのかです。","id":"exchange-028"},{"speaker":"新妻副委員長","kind":"提案","question":"今回、マイスクール八潮の空調設備改修工事ということで提案されております。今回、ここのマイスクール八潮だけでなく、明晴学園のほうの空調設備も併せて改修されるのかというところを確認させてくださいとの意見を述べました。","respondent":"小林（道）学校施設担当課長","answer":"３７年間使っているということで、３７年間使用していたのですけれども、今回は全てを改修するという工事を提案しているものです。","id":"exchange-029"}]},{"id":"topic-05","title":"令和２年陳情第２０号 庁舎建て替えを住民参加で進め情報公開することを求める陳情","agenda":"令和２年陳情第２０号 庁舎建て替えを住民参加で進め情報公開することを求める陳情","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"なので、改めて、Ｄ案がいつどこで決まったのか伺いたいと思います。そもそもこのＤ案が、課長はいつどこで決まったということを知っているのか、そのことについても伺いたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"今のＤ案のことですが、Ｄ案につきましては、現状、最良の位置であるということで区として考えております。今はまだ決定したということではなく、適地であるというふうに考えて検討を進めているところです。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"何がどう違うのか、しっかり説明してほしいと求めました。いわゆる４候補、そしてＤ案の検討が始まったと、そういうスケジュール感になるのかも併せてお伺いしたいと思います。","respondent":"濱中庁舎計画担当課長、多並都市開発課長","answer":"経営会議は、候補地検討の視点や候補地の位置、また候補地の評価等を総合的に勘案して、Ｄ案でいきたいというところでご報告をして了承を得たところです。 以前より共同で検討してきた内容で、一定の合意が方向性として得られるということで、一緒に進めるということを確認して協定を結んだものであります。この中で検討していくということですので、そういう意味では…","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"庁舎は区民のものですから、その検討過程も含めて、しっかり区民に公開して議論を進めるべきだと思います。こうしたことを理由にしてきましたけれども、なぜ混乱するのか、区民にどのような混乱が想定されているのか伺いたいと思います。","respondent":"濱中庁舎計画担当課長、多並都市開発課長","answer":"庁舎の機能検討がまさに今年から始まっておりまして、庁舎機能検討委員会では、庁舎機能検討委員会の結果につきましては。 要するに、まだ公開の前のものは、そのようなＪＲ東日本の公開前の情報を頂いて一緒に検討していくということが非常に重要だと思っています。協議先がある、非常に混乱を生じるだろうと…","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"そして、ＪＲ東日本の企業の利益を非公開としているのは、ＪＲ東日本の企業の利益とは何なのか、改めて伺いたいと思います。区民のための庁舎ですから、ぜひその姿勢を変えてほしいと求めましたが、いかがか尋ねました。","respondent":"濱中庁舎計画担当課長、多並都市開発課長","answer":"今年度予定されます庁舎機能検討委員会では、委員の方に現状と課題や経緯等も知っていただいて、これから求められる庁舎機能について広くご議論をいただきたいと考えています。 要するに、外に公開しないことを前提に情報を頂いて一緒に検討していくということですので、それが前提となるものです。それが出るということは信義則に反しますし…","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"これを伺いたいと思います。少なくとも１週間前には提供して、そうした時間を保証すべきだと思いますけれども、いかがか尋ねました。","respondent":"濱中庁舎計画担当課長、多並都市開発課長","answer":"庁舎機能検討委員会では、現状と課題や経緯等を整理して議論をしていただきます。事前資料に関しましては、配付時期等を委員会でも検討いただいて、適切な時期にお示ししていきたいと考えています。 駅前との連携、そのような全体的に品川区としても公平的な全体的な視点を見ながら協議し進めているものでもありますので、そういう視点でご理解いただければと思います。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう開催通知が届けられておりますけれども、私は１週間前に提供すべきだと思いますが、この点についてはっきりとお答えほしいと求めました。だから、１週間前の提供をぜひやっていただきたいのですけれども、いかがか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"委員からご提案ありました資料の事前提供ですが、今、資料作成中ですので、できる限り、委員の方々が審議しやすいように、配付資料の事前提供等を検討してまいりたいと考えています。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"できる限りとか、事前検討とか、では、まだ決まっていないということですか。決まっていないのだったら、１週間前に提出できるように準備していただきたいのですけれども、いかがか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"配付資料等は、委員の方々が議論しやすいように、今、作成中ですので、今後、資料作成に努めてまいりたいと思います。","id":"exchange-036"},{"speaker":"中塚委員","kind":"提案","question":"決まっていないのだったら、決まっていないと言えばいいのです。私が１週間前はどうですかと提案しているわけですから、Ｄ案の経過や情報公開、これはしっかりと進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"生活者ネットワークも情報公開を求めました。〔「審査請求」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"それに対しての再弁明書が、私たちは１か月弱の日程で出すように求められて、その期日を守りました。それを私たちは求めております。","respondent":"多並都市開発課長","answer":"今のお話につきましては、企画部の広報広聴課が進めているところであります。今、それは広報広聴課が主体となりながら、その時期も含めて検討している段階であります。","id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"やっぱりこの姿勢は、この陳情に限らず、改めていただきたいというふうに思います。この陳情に関しては、先ほどの具体的なことは中塚委員からありましたので、ちょっとそのことだけ申し述べします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"須貝委員","kind":"質問・要望","question":"このたびの情報公開することを求める陳情ですけれども、先ほどからお話を聞いていまして、情報公開するにも難しさがあると思うのです。Ｄ案はどのようにして決められたのですかと、これは私も行財政改革特別委員会に在籍しておりまして、いろいろ案が示されました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"吉田委員","kind":"質問・要望","question":"この陳情の方がどのような記録を求めておられるかは、生活者ネットワークとしては、議論の経過が分かるものを出してほしいというふうに言っています。だから、区としてこういう議論の経過をたどりましたというようなものが分かれば、何も逐語録を出してほしいというところまでは求めておりません。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"湯澤委員","kind":"質問","question":"区内で建て替えに利用可能な候補地が４か所あり、その中で最も早く利用が可能となるであろうという形でＤ案が紹介をされたと認識をしております。公開できるものに関しましては、丁寧な説明とともにしっかりと示していただき、多くの区民が納得して喜ばれるものを造っていくべきだと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"高橋（伸）委員","kind":"質問","question":"本日結論を出すということで、不採択でお願いいたします。これから庁舎計画がある中で、庁舎機能検討委員会の中でこういった議論をしてほしいと求めましたので、今回の態度としては不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"こういう機能の整った新庁舎ができるのだということに関して、しっかりとそこはオープンにできるところはオープンにしてほしいと求めました。今後に関しまして、どういう形で庁舎の建て替えが進んでいったのかということが分かるように公開をしていただきたいということを求めて。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問","question":"本日結論を出すということと、採択でお願いします。示されている情報が黒塗りと、これはやはり問題だと思いますので、採択を主張したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"須貝委員","kind":"質問・要望","question":"私も本日結論を出すということと、不採択でお願いしたいと思います。そして共同事業者の了解の下で、報告していいことがありましたら、それはやっぱり正確にしっかりと区民に報告を逐一してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"吉田委員","kind":"質問・要望","question":"この公開を求めておりますので、それを公開するということであれば、事業者の利害にも決して反するものにはならないと思います。ぜひ採択をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"}]},{"id":"topic-06","title":"第４０号議案 職員の特殊勤務手当に関する条例の一部を改正する条例","agenda":"第４０号議案 職員の特殊勤務手当に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"その仕組みについてご説明いただきたいのと、もう１つは、新型コロナウイルス感染症に限っての対応なのです。そういう仕組みも考えていくことが必要ではないかと思うのですけれども、その点についてのご見解も伺いたいと思います。","respondent":"黒田人事課長","answer":"ほかのウイルスも含めての対応ですが、先ほどご説明いたしました感染症予防法の中に、種類によって分けられております。様々対応しておりますので、法の中で感染症の位置付けがあれば、それに沿った対応をとっていくということになろうかというふうに考えてあります。","id":"exchange-049"},{"speaker":"中塚委員","kind":"意見","question":"いずれにしても、遡及して適用ということですので、これはもちろん賛成したいと思いますけれども、感染症対策は第２波への備えというところで、全体像の解明やワクチンの開発などもまだ大分時間もかかりますけれども、常設の感染症対策というものも必要なのかなと…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"吉田委員","kind":"質問","question":"３番の支給対象となる業務については、具体的に、例えばこういう業務がこれに当たるというようなことがあれば伺いたいと思います。","respondent":"黒田人事課長","answer":"項番３の表の上段の作業１日当たり４,０００円に該当する業務として現在検討しておりますのは、その直接対応ということで、要するに。上段とは区分して、受付業務については３,０００円というような形で、リスクを勘案して業務を区分けするというようなことを考えてあります。","id":"exchange-051"},{"speaker":"吉田委員","kind":"質問","question":"３,０００円と４,０００円の線引き、あまりにもお金のことばかり言うようですけれども、どこでどういうふうな判断をされるのでしょうか。いかがか尋ねました。","respondent":"黒田人事課長","answer":"今、そういった中で検査で陰性化確認に対応したということで、ややリスクが下がった場合については３,０００円の区分というふうに考えてあります。その後の陰性化しているのではないかということの確認ということであれば３,０００円ということで、今、そのように検討していま…","id":"exchange-052"},{"speaker":"吉田委員","kind":"質問・要望","question":"規則とかで確認させていただきたいというふうに思いますが、質問の意図としては、どうしてあの人には手当が付いてと。こういう手当の存在は、とても必要だと考えていますので、不公平感が生じないようにしていただけたらと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"須貝委員","kind":"質問","question":"今回の職員の特殊勤務手当に関する条例ですけれども、これはウイルス名ごとに別々に、そのたびに条例を定めないと駄目なのですか。そういうものを１つの条例で全部包括できるという、そういうことではないのか尋ねました。","respondent":"黒田人事課長","answer":"国は手当を日額４,０００円という形で規定をしておりますが、今後そういった中で、疫学的な解明が進めば位置付けられてくる。それに応じて同じように対応していくというふうに考えているところです。","id":"exchange-054"},{"speaker":"須貝委員","kind":"質問","question":"毎回こういうふうにしなくてもいいのでしょうけれども、ただ、金額や条件等がいろいろ変わってくるからこうなるのでしょうか。包括的なものはないというふうに考えていていいわけですね。","respondent":"黒田人事課長","answer":"先ほど申し上げた一類感染症と同様の対応をとることになりますし、二類感染症に位置付けられるということになれば、二類感染症という形になります。そういった意味では包括的に対応されるというふうに考えております。","id":"exchange-055"},{"speaker":"湯澤委員","kind":"質問・要望","question":"教えていただきたいのですけれども、あと、この特殊勤務手当に該当する方は何人ぐらいいるのかを教えてほしいと求めました。この方だったら手当が４,０００円となる、３,０００円となるというのが明確に分かれているのかということも教えてほしいと求めました。","respondent":"黒田人事課長","answer":"遡及対応をご提案した関係もありまして、それぞれの業務の中で、この対応については直接感染のリスクが高かったということで整理しておりますので。今後につきましては、先ほど申し上げた原則的な考え方を基に業務を区分けしていきたいというふうに考えているところです。","id":"exchange-056"},{"speaker":"湯澤委員","kind":"意見","question":"ぜひ感染リスクがある職員の方が意欲を持ってこれからも勤務に当たれるように、そういった施策を取り組んでいただければなと思いますので、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"}]},{"id":"topic-07","title":"第４６号議案 東大井保育園・児童センター改築その他工事請負契約","agenda":"第４６号議案 東大井保育園・児童センター改築その他工事請負契約","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"２方向避難をどういうふうに確保されているのか、それを伺いたいと思います。そういう配慮が、工事契約の金額の中でどの辺まで担保されているのか、その辺について伺いたいと思います。","respondent":"小林（剛）施設整備課長","answer":"今、設計を進めているところでございまして、そういったところも併せてしっかり検討されているところです。これから改築がありますので、そういうところをさらに情報を蓄えながら、よりよい施設作りにつなげていきたいというふうに考えてあります。","id":"exchange-058"},{"speaker":"吉田委員","kind":"確認","question":"それから、人工芝は流れとしてしようがないのでしょうか。川に流れないような配慮がされているのか、されていると思いますけれども、確認をさせください。","respondent":"小林（剛）施設整備課長","answer":"階段ですが、ご指摘のとおり、屋外階段が北側に１か所、それから東側に１か所ありますので、そちらを使っていただいて避難していただくことになるかと思います。","id":"exchange-059"},{"speaker":"須貝委員","kind":"質問","question":"今回３月から様々な問題がありましたけれども、建て方に何か変化がありましたとか、そういうことはあるのでしょうか。もしあったら参考に説明を求めました。","respondent":"小林（剛）施設整備課長","answer":"ただ一方で、やはり３密を防ぐための１つの基本として、換気は非常に重要だというふうに言われております。必要に応じて設置が義務付けられておりますので、そういうところを使いながらしっかり換気するという形になろうかというふうに思っています。","id":"exchange-060"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"開園に向けてその影響が抑えられているのかどうかというところの確認が１点と、なおかつ、そこら辺をどのように配慮されているのか。住宅地の中にある建物ですので、近隣の方への配慮というところでの、説明会等々がどのように行われていくのかを教えてほしいと求めました。","respondent":"吉田保育施設調整担当課長、小林（剛）施設整備課長","answer":"仮設園舎の工事につきましては、８月３１日が工期でございましたところ、最終的な工期は９月１８日まで延びたところです。１８日に延びたことによる、こちらの本園舎の計画についての影響はないものと考えております。 それから、工事説明という観点ですが、まず昨年の９月に建物の計画に関する説明会は実施させていただきました。この後、議決後、８月中に近隣の方々を改めて対象にしました、今度は工事に関する説明会を開催する予定です。","id":"exchange-061"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"それぞれ、特に近隣への説明会におきましては、配慮をしてほしいと求めました。去年だったでしょうか、ここだけに限らず、丁寧な説明をぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"高橋（伸）委員","kind":"確認","question":"ご説明ありがとうございました。１点だけ確認なのですけれども、屋上から１階まで通じているのですけれども、避難階段という認識でいいのか尋ねました。","respondent":"小林（剛）施設整備課長","answer":"北立面図にかいてある階段の部分ですが、これは屋上にあります児童センターの屋上広場から来る階段と、併せて３階からの児童センターの階段、両方ともこれは屋外階段という考え方で避難階段として使われる階段です。","id":"exchange-063"}]},{"id":"topic-08","title":"第４７号議案 八潮西保育園大規模改修工事請負契約","agenda":"第４７号議案 八潮西保育園大規模改修工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"大規模改修の理由ですけれども、この間、八潮地区内の保育園をいろいろ改修してきましたが、老朽化ということですか。大規模改修の理由を伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"八潮地区の保育園は、昭和５０年代の後半に設置されまして、もう築３０年が経過しております。厨房等も老朽化が進んでいたところから、平成２９年の八潮わかば幼稚園を皮切りに、八潮地区を順繰りに改修工事を進めているところです。","id":"exchange-064"},{"speaker":"吉田委員","kind":"質問","question":"どういう形で工事をされるのか伺いたいのと、そういうことがどういうふうになるのか伺いたいのと、その辺についてもお伺いします。","respondent":"吉田保育施設調整担当課長、小林（剛）施設整備課長","answer":"安全に工期が終わりましたら、また今年度中に工事が終わった場所に戻ってくる予定です。古くなったりしたものにつきましては、この機に交換するとか、その辺は現場と話しながら進めていきたいと考えているところです。 そういった中でも保育園の現地のいらっしゃる先生方の声も聞きながら、床をフローリングにするということも配慮の１つだというふうに思うところです。扉の材質等につきましても、挟まれても痛くないような形になっているかどうかも含め…","id":"exchange-065"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういう配慮はされているように伺いましたので、余地があるのであれば、そのご意見とかを伺いながら工事を進めていっていただけたらと思います。それは要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"須貝委員","kind":"質問・要望","question":"午前中も申し上げましたし、先ほどの東大井保育園もそうですが、今回の保育園も同じ建設会社が落札をされています。これからも考えていただきたいし、多くの区内業者を育成して存続させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"というのは、建物の２階から上は住居になっておりまして、そこへの配慮等をどうされていくのかということを確認をさせてほしいと求めました。この崖地のところの確認というか、調査をしていただけるのかを確認させてほしいと求めました。","respondent":"小林（剛）施設整備課長","answer":"２点目の説明会ですが、今回はこの上に住んでいる方々を対象とした説明会を、まず計画に関する説明会は今年２月に行っておりますが。区分所有者でありますＪＫＫと、その辺のお話を聞きながら、状況は把握してまいりたいというふうに考えてあります。","id":"exchange-068"}]},{"id":"topic-09","title":"第４１号議案 品川区特別区税条例の一部を改正する条例","agenda":"第４１号議案 品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"大きく９項目の変更でありますが、(6)の区民税の執行猶予について伺いたいと思います。同様のケースで免除という形をとっておりますが、区民税は、免除でなく猶予とした理由は何か伺いたいと思います。","respondent":"伊東税務課長","answer":"地方税、区民税に限らず、国税に関しては徴収猶予という形の特例が今回設けられたです。税制全体の部分ですので、それ以上踏み込んでの改正はされなかったというふうに認識しています。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問","question":"２年分の支払いについて、何らかの支援をしていかないと、翌年の支払いが一層苦しいのではないかと思うのです。今回の新型コロナウイルス感染症による経済への影響はすごい深刻ですから、来年度以降の支払いについて、区のお考えを伺いたいと思います。","respondent":"伊東税務課長","answer":"確かに今回は１年の猶予ということで、免除ではございませんので、来年、１年後にまた支払いをしてもらうです。そのケースに応じて対応させていただいているところですので、その会社なりの状況も詳しく相談を受けながら対応していこうかと思っているところです。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問・要望","question":"これが今年分です、これが来年分ですというふうな形になるのか、それとも合算して幾らですという形になるのか。これは来年分と、そういう形になるのか、その仕組みをご説明いただきたい。","respondent":"伊東税務課長","answer":"スタートラインが１年遅れで、仮に同じだとすると、合算みたいになってしまう可能性はあるかと思います。今もそうやっているのですけれども、それは延滞金もなるべく発生しないような形での納付をお願いしていくというところで進めているところです。","id":"exchange-071"},{"speaker":"中塚委員","kind":"質問・要望","question":"私は常日頃、延滞金はおかしいと思っていますけれども、こういうときこそ、せめて延滞金はやめるとか、そういう判断はされるべきだと。区独自でやるかの議論もありますけれども、ぜひ国に対してもいろいろ意見を述べていただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"},{"speaker":"吉田委員","kind":"質問","question":"幾つか言葉の説明というか、伺いたいと思います。低未利用土地を市場に出すことによって、あわさって使える土地になってというのは分かるのですが、(4)のほうを説明を求めました。","respondent":"伊東税務課長","answer":"地方都市で土地を有効に活用していただきたいということで、これは創設ということになりますけれども、そういう形でのものです。これは期限の延長ということですので、もうしばらくという形で、環境のいい住宅を増やしていくという政策なのかというふうに思っております。","id":"exchange-073"},{"speaker":"吉田委員","kind":"質問","question":"それは、何か変な言い方で、誰がどう決めているのでしょうか。どういうふうに決まっているのか尋ねました。","respondent":"伊東税務課長","answer":"一定の中身が精査されて、それをこういう者に売却したのだということで申告をしていただくと、これが適用されるというような形だというふうに思ってあります。","id":"exchange-074"},{"speaker":"吉田委員","kind":"意見","question":"何かその辺が優良住宅地か否かというのが、すごい大規模な開発事業者のほうにその土地が流れていってしまうというのもすごく心配するところです。期限の延長ということですので、その辺のことだけちょっと気になりましたので、意見だけ申し述べしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-075"},{"speaker":"湯澤委員","kind":"質問","question":"(5)については該当するところがないかもしれませんが、周知に力を入れてほしいと考えています。５００万円の所得制限がかけられることによって、条例改正によって受けられなくなる人もいるのではないかというふうに思いますが、どうか尋ねました。","respondent":"伊東税務課長","answer":"それにも解説といいますか、説明書きが付いてありますので、その説明文を読んでいただくというような形になります。今回、６７８万円ということになるのですけれども、それ以上の方々に関してやる必要があるのかどうかというところでの判断に至ったということです。","id":"exchange-076"},{"speaker":"湯澤委員","kind":"質問","question":"それからあと、(7)にあります寄附金控除の適用というところですけれども、区長が例えば指定しない可能性があるということなのでしょうか。それだけ説明を求めました。","respondent":"伊東税務課長","answer":"では、これは確かに条件が合致しているから、この制度を適用しましょうという流れでやります。それをもって、では、品川区が指定しないかということではなくて、その指定されたものは、そのまま品川区としても適用させるという形でいるものです。","id":"exchange-077"},{"speaker":"須貝委員","kind":"質問","question":"(1)で、たばこ税としてどれぐらい増えるのでしょうか、教えてください。低迷している状況ですから、ここも柔軟な対応をしてほしいし、消費刺激をしてほしいと思います。","respondent":"伊東税務課長","answer":"逆に、区としては、それが１本分とかとなれば、少しは税収が上がるという理屈にはなろうかと思います。ただ、ほかのたばこの売渡し具合、いろいろあるので、難しいところです。","id":"exchange-078"},{"speaker":"須貝委員","kind":"意見","question":"片一方はこうやって税が上げていくというのには、違和感を覚えたので、できるだけ多くの区民を助けていただけるよう対応していただければありがたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-079"}]},{"id":"topic-10","title":"令和２年請願第６号 政府に消費税減税を求める意見書提出に関する請願","agenda":"令和２年請願第６号 政府に消費税減税を求める意見書提出に関する請願","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"政府に消費税減税を求める意見書提出に関する請願ということですけれども、採択をしていただいて、区民の暮らし。ぜひご賛同を頂きたいと呼びかけたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"},{"speaker":"須貝委員","kind":"意見","question":"皆さんにこういう請願にご賛同いただき、何とか企業を守ってほしい、そして支えてほしい。それは消費税減税でどこまでできるか分かりませんが、もうこれしかないと思うので、ぜひご協力いただければありがたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-081"},{"speaker":"吉田委員","kind":"質問・要望","question":"以前１０％への消費税引き上げについて、１０％にするのをやめてほしいという意見書の提出を求める請願のときにも申しましたけれども。一般質問で求めましたけれども、廃止ではなくて引き下げですから、こういう意見書は出してしかるべきではないかというふうに考えております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-082"},{"speaker":"湯澤委員","kind":"質問","question":"自民党、３０％のプレミアム付商品券発行といった議案が今定例会で成立することで、区民の皆さんの家計を支えたいというふうに考えております。そして低所得者を支えたい、徴収された税金がきちんと使われていることを示し、国民との信頼関係を構築してほしいというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-083"},{"speaker":"高橋（伸）委員","kind":"意見","question":"そのような中で国も８％の軽減税率を導入しました。そういった中で、財源の確保も重要かと思いますので、よって、国に意見書は行わず、不採択ということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-084"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ちょうど前回、消費税を上げないよう求める請願が出されたときも、私もこの総務委員会に所属しておりまして、議論もさせていただきました。公明党が求めてきた教育費の軽減というところで、この消費税の大きな位置付けがありました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-085"},{"speaker":"中塚委員","kind":"質問・要望","question":"消費税ですから全国に関わることですから、経済を考えたら、消費税の減税を求める意見書をぜひとも提出したいと考えています。税制度がどうあるべきかは、今回の意見書は消費税減税を求めるものでありますので、ぜひ一致できたらなと改めて呼びかけたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-086"},{"speaker":"須貝委員","kind":"意見","question":"もう国も都もどうしようもない、何をしていいか分からない状態に陥ります。これからますます増えていく、そういう危険をはらんだ状況なので、もうあとは国民の消費喚起をするしかないかと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-087"},{"speaker":"吉田委員","kind":"意見","question":"それが１０％ということで、小さな事業者にとっては本当に大きな負担です。将来の子・孫の世代が来るのだろうかというふうに本当に真剣に心配しておりますので、この意見書はぜひ出したいというふうに思っておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-088"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/346628?Template=document&Id=2172#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":63907,"voices":296}},{"id":"r02-20200630-6","meetingId":"r02-cm06","date":"2020年6月30日","dateIso":"2020-06-30","committee":"区民委員会","time":"午前１０時００分～午前１０時３４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件整理しています。","topics":[{"id":"topic-01","title":"」を聴取いたします。 「令和２年国勢調査","agenda":"」を聴取いたします。 「令和２年国勢調査","exchanges":[{"speaker":"小芝委員","kind":"確認","question":"そういったところでインターホン越しに話をしてポスティングという形、非接触でやられているのは大変安心できるものだと思います。少し確認をしたいのですけれども、「回答確認チラシ」や8)の「提出確認状の配布」というのは、単純にポスティングという認識でよろしいのか尋ねました。","respondent":"川島地域活動課長","answer":"回答をお願いする、促すような書類、それから、また追加で提出をお願いしますというものにつきましては、ポスティングをしていただければいいと、こちらでは準備しています。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"調査時期が１０月１日ということですけれども、コロナの関係でずれたということではなくて、最初から１０月だったのかということ。いろいろあるでしょうけれども、どれくらい配られて、どれくらい回答があるのかという平均がわかれば、前回のものを教えていただけたらと思います。","respondent":"川島地域活動課長","answer":"調査の時期というのは、当初の国勢調査が始まってからずっと１０月１日で来ております。それから、回収率のところですけれども、国で公表している数が、ざっくり７割程度の回収率です。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そこまでのトラブルはないのかなとは思うのですが、やはり回収率のところに響いてくるのかなというのは、そうでもないのですかね。調査員の方は町会、コロナのさなかなので、集まりづらい状況だったりするのでしょうかというのを伺いたいと思います。","respondent":"川島地域活動課長","answer":"回収率の見通しといった質問だと思うのですが、国はインターネット回答を引き続き推奨するということです。説明会等でどうしても集まっていただかなければならないものについては、先ほどご説明させていただいたとおり、説明会の時間をかなり短縮しまして。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"意見","question":"調査員の皆様への配慮はわかったのですけれども、調査員の皆様が応募してくる数というのは、今までと余り変わりない。コロナなので、余り外を回るとか、不安みたいなものもあって、集まりが悪かったりするかどうかとの意見を述べました。","respondent":"川島地域活動課長","answer":"平成２７年のときと比べますと、残念ながら町会推薦の方が８４人くらい少なくなっているところではありますが、大変感謝しています。やはりどうしても外に出て、サージカルマスクやアルコールのジェルを用意させていただいて、調査員に使っていただければと準備したところです。","id":"exchange-004"},{"speaker":"大倉委員","kind":"確認","question":"１個だけ確認で、先ほど調査員の訪問回数。そこだけ少し確認で教えてほしいと求めました。","respondent":"川島地域活動課長","answer":"少なくとも３回行って、今回、最低でも２回はインターホンを押していただきたいというのが区からのお願いです。その辺、きっちりやっていただければと思う一方で、なかなか実態に即した形でというところもあると考えています。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"私は、これは制度だからしようがないかなという思いがあるのですけれども、ずっと国勢調査をやっていて、５年置きでしたか、１０年前置きでしたか。伺うのは、１０年置きのほうが大きくて、５年置きのものはそうでもないみたいなことを伺っているのですけれども、その辺についてをお伺いします。","respondent":"川島地域活動課長","answer":"１０年置きのほうが本調査という位置づけで、調査項目が２項目増えるという形になっております。今回の資料では調査項目が１９項目ということですが、前回は１７項目ということで、その辺の変更があるというものになります。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"区がどうしようという話ではないと思うのですが、郵送して戻してもらうという形をとる方法もこれからはあるのではないかという思いが１点と、品川区においてはどのぐらいのお金がかかるのか尋ねました。","respondent":"川島地域活動課長","answer":"直接面会しないまでも、インターホン越しに確認していただきたいというのが調査の正確性を期すという意味でお願いしています。それから、今回の予算ですけれども、予算書上の金額で言うと２億３,４８３万５,０００円という形で予算を計上しています。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"いつから日本という国はこのようになってしまったのという思いが１０年前にあった。今回の調査用紙にも罰則や何かというのは出てくるのか尋ねました。","respondent":"川島地域活動課長","answer":"調査票には書いてございませんが、記入の仕方のところに、委員は義務とおっしゃいましたが、統計法に基づく報告義務がありますということで、法律の関係部分を抜粋したものが記載しています。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"難しいことを聞いているのではなくて、罰則があるということは書いてあるのですかと質問しているから、今回は書いていませんか、書いてありますか。","respondent":"川島地域活動課長","answer":"統計法に基づきます罰則の条文が記載されております。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"小選挙区等の選挙区の割当てに使うというのはよく伺うのですけれども、余り罰則ということを過剰に言っても、私はいかがなものかと。私の質問も余りよくないのかもしれないけれども、どうしてもここだけは言っておきたいので言わせていただいたのです。","respondent":"川島地域活動課長","answer":"より多くの方に回答していただくことが正確な統計につながるということで、このように法律も定められているのだと思います。あくまでも私どもはそれを盾に義務がありますというところではなくて、お願いをするという形で調査をさせていただければと思います。","id":"exchange-010"},{"speaker":"くにば委員","kind":"質問","question":"先ほどご回答があった回収率です。５年前等々のノウハウを活かして、品川区独自でこういったことをやって回答率を上げていこうという施策はありますか尋ねました。","respondent":"川島地域活動課長","answer":"回答をしていないところに言葉を添えてメモのような形で入れるものなど、区でもその辺を標準化しまして、回答を促せるようなものをつくっております。先ほど説明がございませんでしたが、成人式でＰＲしたり…","id":"exchange-011"},{"speaker":"くにば委員","kind":"質問","question":"私がこれで１点伺いたかったのが、このやり方に沿って周知してください、このやり方に沿って回収してくださいということがあると思うのです。例えば、そういった部分でどれぐらい力を入れるかというのは、自治体の裁量で決められているのか尋ねました。","respondent":"川島地域活動課長","answer":"それぞれの区なり自治体が、その地域に合った形でやる部分、アレンジする部分は当然出てくるです。今も少し考えておりまして、多くの方に回答していただける工夫も、少しずつですがやっていきたいと考えています。","id":"exchange-012"},{"speaker":"くにば委員","kind":"質問・要望","question":"Facebook等々も含めて、国勢調査のインターネット回答にぜひご協力をお願いしますと強く打ち出していただきたいなという要望があります。そちらに関していかがお考えか尋ねました。","respondent":"川島地域活動課長","answer":"Twitter、Facebookといった新たな媒体を含めまして、インターネット回答が伸びるということは、多分調査員の方の負担軽減につながりますし、回答する方も回答しやすいということですので、何とか力を入れてやっていきたいと考えています。","id":"exchange-013"},{"speaker":"くにば委員","kind":"質問・要望","question":"ぜひともインターネット回答の部分、今後、５年後に向けてもそうですけれども、さまざまな部分で品川区の行政が区民の方にアプローチする手段としてインターネットを活用していただけるようにアピールしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/297302?Template=document&Id=2874#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":10089,"voices":43}},{"id":"r02-20200630-7","meetingId":"r02-cm06","date":"2020年6月30日","dateIso":"2020-06-30","committee":"厚生委員会","time":"午前１０時００分～午後 ２時２９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件整理しています。","topics":[{"id":"topic-01","title":"はじめに、(1)令和元年度品川区介護保険制度の運営状況","agenda":"はじめに、(1)令和元年度品川区介護保険制度の運営状況","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"総合事業についてお伺いいたします。それから、あるいは実際にこれを利用されている方の評判が寄せられていると思うのですけれども、その辺のことをお教え願えればと思います。","respondent":"菅野高齢者地域支援課長","answer":"東品川ゆうゆうプラザが９月にオープンする予定ですので、サービスとしてそちらのほうを受ける方が増えていくのではないかと推測しております。今後もさわやかサービスの中で、こういった形でボランティアに活躍していってもらえたらと考えています。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"地域ミニデイについて、具体的なイメージは機能訓練というような感じなのか尋ねました。","respondent":"菅野高齢者地域支援課長","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"それと、利用者の具体的な評判というものがもしあれば、少しでも伺えればと思います。","respondent":"菅野高齢者地域支援課長","answer":"まず１０時にお迎えをして、大体約２時間ということで、１２時ぐらいに解散していただくという流れになっております。めまぐるしく機能回復をした方もいらっしゃるということで、大変満足しているというお声は聞いております。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"在宅介護だけではなくて、こういう老人ホームに対する需要は確実にあるということが、この数字でも証明されているということではないでしょうか。特別養護老人ホームへの申請者が毎年５００名近くいるということからも、在宅介護だけではなくて、いかがか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"それから、この表の見方を改めてご説明しますと、サービス開始年度を１００としての指数になっております。そこからの伸び率というのはそれほど大きく変わっていないということなので、特定施設のみが突出して伸びているというふうには考えておりません。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"今おっしゃった平成１８年を基準にしましても、平成１８年は指数で７５７ということですから、３倍程度に伸びているわけですね。そのこと自体はお認めにならざるを得ないのではないか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"ニーズがあるということは先ほども申し上げておりますので、認める、認めないではなくて、認識は持ってあります。そういった設置が可能で、そのままそれが特定施設になっているという、ある意味作る側からすれば比較的設置しやすいというものがありまして。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問・要望","question":"そこを無視しないで、確実に計画的に作っていく姿勢を区として持っていただきたいということを申し上げたいと思います。その点、いかがか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"施設サービス、それから在宅サービス、地域密着型も含めまして、それぞれにニーズがあるということは真正面から受け止めてあります。","id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"平成２７年から始まって、やはり新たな制度を５年やってきたわけですから、そういう５年たったところでの評価・検証はされたのか。課題は何かというところも改めて伺いたいと思います。","respondent":"宮尾高齢者福祉課長、菅野高齢者地域支援課長","answer":"先ほど説明の中でも触れましたが、住民票自体は品川区から移るけれども、住民票上の人数とはここでずれが生じるということになってあります。ですので、国との乖離をもって、品川区が特別な認定をしているという認識はございません。 例えば今回、こちらの介護予防事業の報告もする予定でして、カラダ見える化トレーニングというのを新規事業として取り上げさせていただきました。やっと７月から始めるという形になっているのですけれども、事業を再開したときに…","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そのホームヘルプサービスにしても、総合事業のところでのホームヘルプサービスも、そこのところはどう評価されているのか伺いたいと思います。地域支援事業は、今多分３倍ぐらいに増えていると思うのですけれども、この地域支援事業の財政の割合というのを改めて教えてほしいと求めました。","respondent":"宮尾高齢者福祉課長","answer":"私のほうから、私どもとしましては、特に介護報酬を区が低く抑えているせいで利用が抑えられているという認識は全くございません。包括的支援事業、第一号保険料が２３％、第二号保険料はここには充当されておりません。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もう一つ教えていただきたいのは８ページなのですが、これは区内に施設があるのかどうなのか、ちょっとその点についてお聞かせください。それで、何回ぐらいされることになるのか、またそこの大まかなスケジュールについても教えていただけたらと思います。","respondent":"寺嶋福祉計画課長、宮尾高齢者福祉課長","answer":"それから、一般の方にご説明する方法としては、そういう取扱いをするようになったと設置者のほうからはお聞きしています。そこに１点だけ触れしますけれども、地域包括支援センター運営協議会につきましては… まだ現時点では予定というところで、基本的にはこちらの策定委員会を中心に準備を進めていきたいと考えています。国の動きもいつもの改定の年に比べると若干遅くなっているということもありますが…","id":"exchange-009"}]},{"id":"topic-02","title":"新型コロナウイルス感染症の影響により収入が減少したこと等による第一号被保険者の介護保険料の減免","agenda":"新型コロナウイルス感染症の影響により収入が減少したこと等による第一号被保険者の介護保険料の減免","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"３カ月のうちの１カ月でも半額以下になれば対象ということがあると思うのですけれども、この３割減というのは、そういうところではどこで判断をしたらいいのかということを説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"これは、今実際に申請を頂く時点で昨年と比べて減っている、その減っている状況がこれからも続くというふうに想定をして、算定をしていくという仕組みになってあります。","id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"その後またちょっと持ち直して仕事が増えて１割ぐらいの減になって、年間トータルすると３割までは減らなかったという場合でもずっと１年間減額ということで続くのか、その点についても説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"あくまでも令和２年中の収入見込額で見するので、例えば委員がおっしゃったように、その後急に状況が改善をしてという場合でも対象にはなってきます。逆に、これからもう少し期間が過ぎていって対象になった方は、３月１日より前にご申請を頂ければその方も対象になるです。","id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"では、申込みの段階で、２月から３割以上減っているということが条件ということで捉えていいのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"そこは委員のおっしゃるとおり、２月の時点から申請を頂いた時点でまずは見させていただいて、その時点で３割以上減っているということであれば、こちらの減額の対象であるというご理解でよろしいと思います。","id":"exchange-012"}]},{"id":"topic-03","title":"令和元年度品川区障害福祉計画実績","agenda":"令和元年度品川区障害福祉計画実績","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"２年連続で実績がゼロになっているのですけれども、これはどのようにお考えになって、どうなさるおつもりなのでしょうか。そこをまずお伺いしたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"施設入所者の地域生活への移行の実績が０件ということなのですけれども、在宅生活等が非常に困難な方が入所されております。実態としてなかなか難しい方が多くいらっしゃるというところが現状です。","id":"exchange-013"},{"speaker":"おくの委員","kind":"質問・要望","question":"これはなぜなのですかということが１つ。どうしてなのか説明を求めました。","respondent":"築山障害者施策推進担当課長","answer":"4)行動援護と5)重度障害者等包括支援の記載がないということですけれども、これは当初の計画の段階でも見込みがないだろうということで。それから、９ページの表の記載については委員がおっしゃいますとおり、ここは次回以降また見直しをしたいと思います。","id":"exchange-014"},{"speaker":"おくの委員","kind":"質問","question":"計画では見込みが２になっているのですが、これは２の間違いではないかと思いますが、いかがでしょうか。結局利用できる日数が限られたというようなことだったのではないかと思ったのですけれども、その点はいかがか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"１５ページの3)ですが、ご指摘のとおり計画のほうでは２となっておりますので、こちらは記載ミスです。１６ページについてですけれども、児童発達支援につきまして、むしろ１人あたりの利用日数が増加しています。","id":"exchange-015"},{"speaker":"おくの委員","kind":"質問","question":"これを区内で実施している事業所はそれぞれ何カ所あるのでしょうか。これをお伺いしておきます。","respondent":"築山障害者施策推進担当課長","answer":"2)居宅訪問型児童発達支援について、区内にはございません。それから、5)医療型児童発達支援についても、区内にはございません。","id":"exchange-016"},{"speaker":"おくの委員","kind":"質問・要望","question":"移動支援や同行援護の利用時間数のほうは、利用者が増えていると思うのですけれども、この点どうお考えになるかということをお伺いしたいと思います。その見極めはどうするのか、どうされているのか、そこら辺のお考えを伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"２７ページの部分でご指摘いただきました施設が増えているというところで、実績ということでどのように載せていくかは検討していきたいと思います。最後の見込みより少ない場合の、事業者が少ないことによるものなのか…","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そしてアクション、ＰＤＣＡということであればそういうことが必要ではないかと思うのですが、それが１点お聞かせいただきたいことです。この３年間の間にこういうことでやっていきますよという方針が書かれているわけですけれども、これに対しても、その２点をまず説明を求めました。","respondent":"築山障害者施策推進担当課長","answer":"１点目のＰＤＣＡサイクルの件ですけれども、こちらにつきましては、計画策定委員会等で分析等をしながら反映をしていくというように考えております。それから、これは３カ年の取組みということで掲げたものですので、次期計画の策定につなげていきたいと考えております。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これは例えば、１７６件しか計画は立てていないということで、計画を立てないでサービスを使われているということなのでしょうか。それからあと、１７６件中、区の障害者福祉課で立てている件数は何件ぐらいあるのかについても教えてほしいと求めました。","respondent":"築山障害者施策推進担当課長、松山障害者福祉課長","answer":"今年実施する計画策定委員会ですとか、自立支援協議会等でも意見を頂きますので、そういったことを踏まえて検討をしていくところです。もう一つの１ページのところで実績として載せていただきたいというところなのですけれども… 私からは、障害児の相談支援についてお答えいたします。新しい事業所は５事業所できましたけれども、どうしても区が立てておりますと、そこからの移行というのがなかなか難しいところではあります。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これからどうしていくかというところまで出していただけるような計画の実績という形にぜひしていただきたいということを要望させていただきたいと思…区としてもそういうところでやって、自立支援協議会で計画実績を評価するというよりは、その点はいかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"今回、自立支援協議会とは別に計画策定委員会を設置するにあたりまして、やはりそれぞれのやるべき役割というのを整理したいと考えております。つきましては、計画策定委員会については、今後各年に１回開催することを考えております。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"ずっと継続して、この計画の実績評価というのもその計画策定委員会でしていくということで、確認させていただいていいでしょうか。自立支援協議会とは違うところでされているのか、要綱とかはもうできているのか、ちょっとその点についてだけ説明を求めました。","respondent":"松山障害者福祉課長","answer":"計画策定委員会につきましては、今後年に１回ということを考えております。要綱関係につきましては、これから改定をいたします。","id":"exchange-021"}]},{"id":"topic-04","title":"では、次に(4)ピックアップ型フードパントリー事業の開始","agenda":"では、次に(4)ピックアップ型フードパントリー事業の開始","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"これは対象者が区内在住の生活困窮者となっているのですが、ちょっと抽象的なので、もう少し詳しい要件としてはどのようなことですか。例えばホームレスの方とか、ひとり親家庭の方とか、今挙げたような方を例に挙げながら具体的に説明してくださいますか。","respondent":"櫻木生活福祉課長","answer":"対象者ですが、生活保護には至らないが、食の支援を行うことで自立につながると判断されるような方を想定しております。ホームレスの方等につきましては、自立を目指すような制度ですので、その趣旨に沿った対応ということになるかと思います。","id":"exchange-022"},{"speaker":"おくの委員","kind":"質問","question":"そうすると、収入が何円以上とか、そういう具体的な額で決めているのではなくて、柔軟にというようなことでよろしいか尋ねました。","respondent":"櫻木生活福祉課長","answer":"基本的な要件としましては、相談の中で食の支援が必要と判断された方ということになっております。","id":"exchange-023"},{"speaker":"おくの委員","kind":"質問","question":"それから、フードバンクの最寄りの駅が浅草橋、秋葉原ということなのですけれども、そこへたどり着くまでの交通費などはどうなっているのか尋ねました。","respondent":"櫻木生活福祉課長","answer":"大井町から２２０円程度ということでございまして、ピックアップに伴う交通費を支給する予定はございませんが、そのようなつなぎをすることになるのではないかと考えています。","id":"exchange-024"},{"speaker":"おくの委員","kind":"質問","question":"予算２７万円で委託料ということになっているのですけれども、これはどこへの委託料で、何に使うというようなことなのか尋ねました。","respondent":"櫻木生活福祉課長","answer":"こちらはセカンドハーベストジャパンへの委託料になっておりまして、費用としましては倉庫保管料や運搬料等の各種管理費用の実費に近いところの経費ということで聞いております。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問","question":"いわゆるひとり親世帯を支援する所管課が異なりますけれども、そちらのほうからこの事業の案内があるのかということが１つ。それと、その世帯１カ月分というと相当な量になるのではないかと思うのですけれども、そこのところはどうお考えになっているのか説明を求めました。","respondent":"櫻木生活福祉課長","answer":"事業のご案内ですが、子育て応援課とは連携して周知をする予定です。ご相談いただければ何らかの対応を考えていくということは検討していきたいと考えています。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今、ひとり親世帯は、まず子育て応援課に通常は行くのかなと。うまく連携ができるのかなというところがやはりちょっと心配なところがあって、そこのところをしっかりやっていただきたいということがあります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問","question":"ごめんなさい、まだ質問終わっていないので、いいですか。足立区等の名称は出てくるのですが、品川区の名前がまだ特に出てきていないのですけれども、これは今後掲載をされるということでよろしいか尋ねました。","respondent":"櫻木生活福祉課長","answer":"周知の方法としまして、特に品川区として掲載していただくことに不都合は感じておりませんので、いずれ掲載されるものだと考えています。","id":"exchange-028"},{"speaker":"あくつ委員","kind":"質問","question":"この事業についてはそもそも周知はされるのか尋ねました。","respondent":"櫻木生活福祉課長","answer":"この事業につきましては、基本的にはホームページ等で掲載をするのですが、内容的にはご相談を受けたベースで判断してご案内するという組立てになっておりますので、ひとり親世帯等の所管とは連携して周知はいたしますが、そういう形でやっていこうと思っています。","id":"exchange-029"},{"speaker":"あくつ委員","kind":"質問・要望","question":"せっかく１５キロもこういう食料を頂けるということですから、周知をお願いしたいと要望して、終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"西村委員","kind":"質問","question":"１点だけ、すみません。ホームページを拝見していまして、こういったところで受け取るということはイレギュラーになるので難しいのか尋ねました。","respondent":"櫻木生活福祉課長","answer":"品川区の方がそちらに行って受け取ることは、ひとり親世帯の方については可能となっていると認識しております。これもちょっとほかの所管ではありますが、その大田区のほうが事業を開始する際には、品川区のひとり親世帯の方に周知をされたと聞いております。","id":"exchange-031"},{"speaker":"西村委員","kind":"質問","question":"グッドネイバーズジャパンとこのセカンドハーベストジャパンの関係性というのはどのようなものですか。両者の関係は。","respondent":"櫻木生活福祉課長","answer":"セカンドハーベストジャパンとグッドネイバーズジャパンの関係についてのご質問ですが、どちらも独自に活動されているＮＧＯで、同じような趣旨で活動されている団体と認識しております。","id":"exchange-032"},{"speaker":"西村委員","kind":"質問","question":"セカンドハーベストジャパンのところから飛べましたので、何か連携されていたり関係があるのかなと思ったのですけれども、そうではないですか。連携はあるのか尋ねました。","respondent":"櫻木生活福祉課長","answer":"大本になるのはグッドネイバーズジャパンが企業から食料等を集めて、それを各拠点で活動されている団体のほうにお流しして、そこから各拠点で活動されている方が利用者の方に渡しているという流れになっております。","id":"exchange-033"},{"speaker":"西村委員","kind":"質問・要望","question":"ひとり親家庭の方は受けとれる方向性でというお話かなと思ったのですけれども、浅草橋はやはり遠いかなと思いますので、順次でもなるべく近いところで受け取れるよう要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それと、これは５０世帯ということですけれども、５０世帯を超えて希望が増えてしまった場合は、それでも５０世帯ということで限定されるのか。その次はまた５０世帯が６カ月ということで、１年間で考えると１００世帯ということになるのか、その点についても説明を求めました。","respondent":"櫻木生活福祉課長","answer":"食に困られていて、状況をお伺いして、ご相談に応じながらご案内するということを想定しております。基本的には対象となる世帯が５０世帯で、最大６カ月までという予算組みになっておりますので、その予算の範囲内で対応するということです。","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"例えば離婚したばかりでこの先どうしようかという方だったり、生活保護を受けているけれども、そういう形での対応になるのでしょうか。ちょっとそこの点についても、イメージが持てるようにお願いします。","respondent":"櫻木生活福祉課長","answer":"なので、今生活が非常に困窮されているという方で、食料があれば自立に向かって進んでいける方をメインのターゲットとして想定しております。子育て応援課以外にも子ども家庭支援センター等がありますので、子ども未来部ほかとこれからお話をして…","id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"だから、そういう点では生活保護に至らないようにということでの支援ということですね。そういうことで言えば、失業してしまい仕事を探す間のすごく困窮している状況だったり、そういう方も対象になるということで考えていいのか尋ねました。","respondent":"櫻木生活福祉課長","answer":"基本的にはお仕事をされていても困窮に至って、食の支援があれば自立に向かっていくという意味合いでは、委員がご指摘されたような方も対象になってくると思います。","id":"exchange-037"}]},{"id":"topic-05","title":"新型コロナウイルス感染症の拡大にかかる国民健康保険料の減免","agenda":"新型コロナウイルス感染症の拡大にかかる国民健康保険料の減免","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"あくまでも国保は国保だけみたいになっていますか。手続きはこれもあります、あれもありますと言ってほしいという気がするのですけれども、その辺だけ説明を求めました。","respondent":"池田国保医療年金課長","answer":"ただいまの横の連携ですけれども、それから後期高齢者医療のほうに加入されている方がいるということは事前に分かっております。今、なるべく同じ方が何回も書類を作成しないようにということで、そういったもののご案内は準備しているところではあります。","id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"所得の均等割りだけで、しかも均等割りの７割減免とか５割減免とかいう方は基本対象にならないということで考えられるのかなと思ったのですけれども、そこら辺の目安だけ教えていただけないか尋ねました。","respondent":"池田国保医療年金課長","answer":"一応政策減額以外の方は対象にはなってまいりますけれども、それ以外のもう既に減額を受けている方については、この制度については合致しないということでご理解いただければと思います。","id":"exchange-039"}]},{"id":"topic-06","title":"新型コロナウイルス感染症に係る保健所・保健センターの対応","agenda":"新型コロナウイルス感染症に係る保健所・保健センターの対応","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"このようなことが書いてあるのですが、こういうことを品川区でもされているのでしょうか。こういう点をお伺いしたいと思います。","respondent":"鷹箸保健予防課長","answer":"その検討部署につきましては、医療連携に関しては私ども保健予防課で実施していますが、対応について検討しています。医師会とともに準備をしていますので、そういった対応なども広がっていけば、より一層検査対応が充実していくものと考えております。","id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問","question":"６月２６日が２００名で、こういう見方をしていいのかどうかということはあるのですけれども、大体ひと月に１０名ぐらいの感染者数が出ている。いわゆる感染が拡大しているということは言えないのかどうか、おっしゃっていただける範囲で教えてほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"確かに４月の終わりから５月の終わり、６月の終わりまでは、おかげさまでなだらかな患者数の増加だったと考えています。ちょうど昨日の夜、どきっとしたものです。","id":"exchange-041"},{"speaker":"あくつ委員","kind":"確認","question":"どのような形で再開をすればいいのでしょうかというところで、そういう中で今ご認識を伺って、再確認させていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そのことでどれぐらい検査が増えているのかということを、ちょっとお聞かせほしいと求めました。ここの想定というのは、最大ピーク時１日何件を想定されているのか、そこもありましたらお聞かせいただけたらと思います。","respondent":"鷹箸保健予防課長","answer":"それ以外に、お子さんですとか障害がある方ですとＰＣＲ検査センターで対応できない可能性もあるということで、合わせて３１名という数です。今回国に出した数では、やはり直接対応できる数だけ出していますので、その１２０とかそういった具体的な数についてはまだ出していませ…","id":"exchange-043"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほど、ここの医療機関で唾液の検査ができますよみたいな指定をしたところで行政検査としてできるという形で進められていくのでしょうか。この唾液の検査が、どういう形で医療機関でできるようになるのかということについて説明を求めました。","respondent":"鷹箸保健予防課長","answer":"検査実施可能な医療機関については、その条件で両医師会のほうで、検査にご協力いただける医療機関を募っていると聞いているところです。今のＰＣＲ検査センターもかかりつけ医の先生が検査が必要だと、逆に保健所からご紹介する場合もあろうかと思いますし…","id":"exchange-044"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それと、診察室も２つあるから大丈夫という形で、東京都が認めて許可をするという形になっていくということですね。おおよそいつぐらいからそういうのが可能になるかというのは、見通しがもしもできていたら説明を求めました。","respondent":"鷹箸保健予防課長","answer":"集合契約と言いますと、例えば風しんの第５期の契約も集合契約という形を取ったのですが、最低でもひと月はかかると思っています。十分対応可能と国あるいは東京都が確認した上で始まっていると思いますので、そういう意味では希望的に思っております。","id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/410936?Template=document&Id=3572#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":46624,"voices":136}},{"id":"r02-20200630-8","meetingId":"r02-cm06","date":"2020年6月30日","dateIso":"2020-06-30","committee":"建設委員会","time":"午前１０時００分～午後 ２時５４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を78件整理しています。","topics":[{"id":"topic-01","title":"意見書（案）","agenda":"意見書（案）","exchanges":[{"speaker":"のだて委員","kind":"意見","question":"昨日も私の意見は述べさせていただきました。補助２９号線ですとか駅前での再開発と、このまちづくりのところは入れるべきではないということで、言っておきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"田中委員","kind":"意見","question":"品川・生活者ネットワークとしても、１の東急大井町線戸越公園駅付近の連続立体交差事業の早期事業化に関しては理解をしますが、２のまちづくり関連の事業推進に関しては、今は時期ではないのかなということは、昨日も申し述べましたが、思っておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"}]},{"id":"topic-02","title":"令和２年７月区営住宅入居者募集","agenda":"令和２年７月区営住宅入居者募集","exchanges":[{"speaker":"西本委員","kind":"質問","question":"場所は教えていただけますかというのと、申込みは７戸だけで、そういうものはないのですか。それから、障害者は有利なのかとか、その辺の優先順位をもう少し具体的に知りたいです。","respondent":"森住宅課長","answer":"募集住宅の場所、住宅名といいましょうか、それにつきましては、７月３日の募集冊子を見ていただければと考えています。それから、障害者等の方につきましては、特に優先枠は設けていないです。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"それと、当選者は７人なのですか。いかがか尋ねました。","respondent":"森住宅課長","answer":"補欠につきましては、各住宅で５名まで、抽選のときに設定をするという形にしております。それで、１番の当選の方が辞退された、あるいは審査に不適合ということになりましたら、補欠の１番の方から順次ご案内していくという形になります。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"その場合、途中空きがあったという場合には、それはもうずっと空きの状況ということの理解でよろしいですか。それとも、補欠の人が、“ここでいいですか”と聞いて、そっちに入れるということはないのか尋ねました。","respondent":"森住宅課長","answer":"１戸につきましては、１月に行った募集の入居審査を今しているということになりますので、空きがないというような状況です。例えばずっと空いてしまうということはなく、半年に一遍行っている募集で、基本的にすべて募集をかけて、入居していただくという形になっています。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"途中で空く場合があるではないですか。その場合は、今待っている優先順位の高いところからやっていくことなのか尋ねました。","respondent":"森住宅課長","answer":"７月募集で補欠になった方がそれに入れるかというと、そうではなくて、１月募集でまたもう１回抽選をし直すという形になります。その１月募集のときに、７月から１月の間で空いたものにつきましては、１月の募集で当選された方からご案内していくという形になります。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問","question":"今の質疑の中で、１月に募集をした方を現在も審査中ということだったのですけれども、それだけ時間がかかるということなのか尋ねました。","respondent":"森住宅課長","answer":"募集をかけて抽選をしてから２か月程度あれば、今、そういう状態が続いているという形です。１月の時点でも７戸募集しているのですけれども、残り６戸につきましては、もう入居済みというような状況です。","id":"exchange-007"},{"speaker":"田中委員","kind":"確認","question":"通常なら２か月以内で入居ができるということが確認できたので、安心しました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"募集時期というのは、増やしたりというのはできないのでしょうか。やはり望んでいる方が多くいらっしゃるので、適宜入っていけるようにできたらと思うのですけれども、いかがでしょう。","respondent":"森住宅課長","answer":"募集時期については１月と７月ということで毎年やらせていただいておりまして、そういった事務手続きを考えますと、半年に一遍程度が適当だろうと考えているところです。","id":"exchange-009"},{"speaker":"田中委員","kind":"確認","question":"すみません、聞き忘れてしまったのですけれども、毎回の募集のときの倍率というのを確認させていただいてもいいか尋ねました。","respondent":"森住宅課長","answer":"倍率につきましては、１月募集のときにつきましては、単身の方で８７％、世帯持ちについては全体で３２.５％という形になっております。","id":"exchange-010"}]},{"id":"topic-03","title":"二葉四丁目地区要請型従前居住者用賃貸住宅建設計画説明会","agenda":"二葉四丁目地区要請型従前居住者用賃貸住宅建設計画説明会","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"この９か所のところと、今、開放広場になっているところを交換するということでよろしいですか。そこの確認と、どういった基準、そこのところを伺いたいと思います。","respondent":"佐藤木密整備推進課長","answer":"手続きにつきましては現在進めておりまして、今回、説明会の開催に至ったというところです。その差分については金銭で埋めるといいますか、調整するという形で、等価での交換を予定しております。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"２５戸を従前居住者用住宅にしていくということですが、１回入ってしまうと、どうなってしまうのかと。そこの考え方を伺いたいのと、この活用方法などが今ありましたら、伺いたいと思います。","respondent":"佐藤木密整備推進課長","answer":"それに加えて、今般２５戸を整備して、その上で必要な分、ある程度見込みを立てて、借り上げて運用していくということを予定しております。もう１点、今回の建設予定の施設の隣地について、II期ということで、その後の活用についてお尋ねだと思います。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"事業協力者をどう入れるかというところでお聞きしたので、確保できないのではないかというところがあるので、そこを伺いたかった。具体的に分からなかったのですけれども、今考えているイメージなどがあれば、伺いたいと思います。","respondent":"佐藤木密整備推進課長","answer":"今回説明会を行う新しい従前居住者用住宅について、今までの事業の進んできている経緯を考えますと、計画的に運用していきたいと考えております。もう１点、１つは、そういった形で行うのが１つ。","id":"exchange-013"},{"speaker":"のだて委員","kind":"確認","question":"安全通路を確保して、共用部みたいな形で隣地に確保してあげて、建て替えられますよという形ということでよろしいですか。そこの確認。","respondent":"佐藤木密整備推進課長","answer":"２年間の期間を定めて貸している、協力者の方が入れなくならないような形で、ニーズを捉えて運用していきたいと考えております。そういった手法があろうかと思いますので、ここはＵＲと、あとは対象の地域の方と協議をしながら進めていきたいと考えております。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、ＵＲから借りている人が、逆に追い出されてしまうということになると思うのです。それはそれでまた問題な気がするのですが、そこのところは、補償というか、支援というのはあるのか尋ねました。","respondent":"佐藤木密整備推進課長","answer":"２年間を定めて賃借人と契約するということですので、通常の賃貸借と違って、期間を最初から定めているという形で運用していると聞いております。ご懸念のところは、そういった運用でクリアされるのではないかと考えております。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問","question":"すみません。いろいろ教えてほしいと思うのですけれども、補助２９号線の事業が今どのくらい進んでいるのかといったことを、伺いたいです。","respondent":"佐藤木密整備推進課長、鈴木都市計画課長","answer":"補助２９号線の整備につきましては東京都で進めておりまして、私どもでは、沿道の不燃化ということで、１０年プロジェクトに基づいて不燃化を進めているという形になろうかと思います。 平成３１年３月３１日現在で、補助２９号線、約１７％の用地取得率と聞いてあります。","id":"exchange-016"},{"speaker":"田中委員","kind":"確認","question":"この補助２９号線の事業に関わる方たちが、この賃貸住宅にということではないのですか。そこだけ確認したいのですけれども。","respondent":"佐藤木密整備推進課長","answer":"従前居住者用住宅につきましては、協定に基づいてＵＲも一緒に進めておりますけれども、品川区で木密事業にご協力いただいた方で、住居に困窮される方を対象にして、入居していただいております。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"木密事業に協力いただいた方が、ここに優先的にというか、賃貸住宅に住むということですよね。この地域で協力された方が、ここに住めるといったことなのかどうかという確認をさせていただきたいというか、２５件の根拠も知りたいです。","respondent":"佐藤木密整備推進課長","answer":"現在の施設の中で空きがありますので、ご希望に沿う住居であれば、お入りいただいているという形です。〔「何で今回２５戸にしたのか」と呼ぶ者あり〕 失礼いたしました。２５戸といたしましたのは、入居希望がどのぐらい出るであろうかということが１つと、想定したのが２５戸という形になっております。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問","question":"別の質問です。この「電波障害を受ける」というのが、少し意味が分からなかったので、そこの説明をお願いいたします。","respondent":"佐藤木密整備推進課長","answer":"高い建物ができると、電波障害を受けるということで、ここに説明をする方の範囲として入ってくるということです。建物の２倍の範囲の方を対象としておるのですけれども、今回、説明の対象になっているということで考えております。","id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"６階ということだったのですけれども、あそこに突然６階のものが建つというのは、圧迫感が近隣の方たちにはあるのかと思うのです。前もって早めの説明とか、説明資料とかの周知といったところをぜひしていただきたいと思うのですが、いかがか尋ねました。","respondent":"佐藤木密整備推進課長","answer":"今回、初めてということでご案内しておりますけれども、まちづくり協議会等には、適宜ご説明しているところではあります。説明会が終わりましたら、同じ説明会の資料を同一の地区に配布するということを考えておりまして、周知を図っていきたいと考えております。","id":"exchange-020"},{"speaker":"田中委員","kind":"質問・要望","question":"その説明会についてですけれども、資料は配布されるということですよね。やりとりの議事録の公開というのはどうなっているのかということを確認させていただきたいのと、今、お知らせください。","respondent":"佐藤木密整備推進課長","answer":"説明会の議事録ということですけれども、周辺の方に分かるような形の資料をお配りしたいということを、ＵＲに伝えたいと思います。もう１点、予定しております交換用地については今現在ＵＲが取得しておりまして、現況としましてはすべて更地という形になっております。","id":"exchange-021"},{"speaker":"田中委員","kind":"確認","question":"そんなに影響はないのかとは思うのですけれども、前もって、こちらのほうも周知をしていただけたほうがいいと思います。説明会でどういう説明があったのかといったことを確認できるように、そういったものを渡していただけたらと思いますが、いかがか尋ねました。","respondent":"佐藤木密整備推進課長","answer":"説明会につきましては、周辺の方々に分かりいいような形で、工夫したいと考えます。もう１点、何でしたか……。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"そことの金額相殺の話は、ＵＲとは決着がついているということでの理解でよろしいですか。今どのぐらい進んでいて、どのぐらいの目標という形で考えておられるのか、説明を求めました。","respondent":"佐藤木密整備推進課長","answer":"１つ目は、交換を予定しております土地についてのお尋ねですけれども、権利関係については既に手続きが終わっているという状態です。ただ、いずれこの２５戸というのは埋まっていくであろうとは考えておりまして、この後どうするかということは考えていきたいと考えております。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"それはいつ頃から始まって、現在どういう形で進んでいるのでしょうか。大体８０戸ぐらいは必要だろうとは思ってはいるのですけれども、申込み者がどのぐらいいらっしゃるというか、今の状況はいかがか尋ねました。","respondent":"佐藤木密整備推進課長","answer":"“直近で入りたい”、“まだ二葉については今後です”ということで、今ある施設に入ったという方はいらっしゃいます。協力者の方にお選びいただけるという形で事業を進めてまいりまして、あるいは同一の地域に建て替えたり、本当のところです。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"それと、これにあたっては、補助金とかはあるのでしょうか。品川区独自のお金でやっていくのか、国とか都とかのお金がどのぐらい入ってくるのかということを説明を求めました。","respondent":"佐藤木密整備推進課長","answer":"協力者の方から見れば選択肢の１つとお考えいただいて、区では、ご希望があればお入りいただくような形になろうかと思います。基本的には区は、この時点では何らお金は出していないという形になろうかと思いますので、特にそのような話はないと思います。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"そうすると、建てるときの建設費用は、ＵＲのほうでということですか。独自事業になってしまうのかという、そこのお金の関係で、流れを説明を求めました。","respondent":"佐藤木密整備推進課長","answer":"そのところで、精算というところはありますけれども、経費については大きいところではないかと考えます。入居している方から歳入は受けますけれども、そのほか借上げの経費については、品川区で支出するという形の運用になろうかと思います。","id":"exchange-026"},{"speaker":"西本委員","kind":"確認","question":"確認です。私、少し理解が間違っていますか。","respondent":"佐藤木密整備推進課長","answer":"その際は、等価というか、その価格で購入するという形で進めております。賃貸住宅ですので、共益費ですとか使用料をお支払いいただいた上で、その地域のその施設にお入りいただくというご案内になろうかと思います。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"１点だけ要望なのですけれども、この２から９までの点在しているＵＲの土地について、資料にも住所が載っていると調査がしやすいかと思うのです。そこのところをお願いしたいのですが、いかがか尋ねました。","respondent":"佐藤木密整備推進課長","answer":"すみません。今後、資料の作成に関しては、そのような観点からも考えて、ご提供するようにいたします。","id":"exchange-028"}]},{"id":"topic-04","title":"京浜急行本線連続立体交差事業および北品川駅駅前広場整備事業に関する用地補償説明会","agenda":"京浜急行本線連続立体交差事業および北品川駅駅前広場整備事業に関する用地補償説明会","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"密を避けてやることができるのではないかと思うので、そこのところをぜひ検討して、開催していただきたいと思うのですが、いかがでしょうか。そこを伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"８月から開始いたします個別説明につきましては、このビラを配布いたします権利者の方々全員に対して、行っていくところです。は仮住居等々の補償、また移転費用など、様々な補償について説明をしていくところです。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"個別説明は全員対象になるというご説明だったので、借家人とかも対象になるということでいいかということで、確認させてほしいと求めました。そこら辺は少し文言を、気をつけて記載してほしいと求めましたが、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"説明会に関しましては、個別で柔軟に対応していくのが大事だというところで、書面開催をするものです。書面につきましては、委員のおっしゃるとおり、再度検討いたしまして、今後、内容につきましては柔軟に対応していきたいと考えています。","id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問","question":"これ、用地測量は終わったという前提でいいのでしょうかというのが１つ。私は、もうこの時期になったらそれが一番いいと思っているので、そこら辺の考え方をきっちり言ってほしい。","respondent":"中道まちづくり立体化担当課長","answer":"分譲マンション等につきまして、そこの部分につきましては、東京都の事業と区の駅前広場の事業との、重複地権者の方もおられます。そうした形で、基本的には大部分が都市計画区域の中に入りますので、除却という形で物事を進めていくというところで、今、検討しています。","id":"exchange-031"},{"speaker":"田中委員","kind":"確認","question":"見て確認をしてほしいということで、資料を配布して個別説明を実施するということなので、必ず見てもらうチラシでなければいけないと思うのです。“いつでもこちらは答える姿勢があるよ”といったことも、もう少し分かりやすく書いていただけたらと思うのですが、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"まずこれを７月上旬に配布いたしまして、７月中旬には、補償等に関する資料を再度送付するというところの二段構えです。そういった２回にわたっての周知といったところで、地権者の方には丁寧にご案内をしていくといったところです。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"二段構えで送付して、必ず見てもらう工夫というのは了解しました。その１枚目から、目を引くような工夫をしていただきたいと思うのですが、そのところはいかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"こちらを配布する際には、封筒等ではなくて、ビニール袋等に入れまして、それで、品川区からのおたよりといったところがポストの中等、または郵送等でもすぐに分かるように、そういった工夫はする予定です。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"とにかくこの青色の背景というのは……。手に取る方のことを考えて、目に入れてもらえるような工夫を再度求めます。","respondent":"中道まちづくり立体化担当課長","answer":"委員の言われることを踏まえて、また検討してまいります。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"ある程度は理解されているのだろうという思いはあるので、あとは条件整理なのかなという感じはするのですが、今どういう状況なのでしょうか。現状はどういう状況なのか、教えてもらえますか。","respondent":"中道まちづくり立体化担当課長","answer":"もう１棟の、こちらは不動産投資マンションといったところで、企業が管理をしている投資マンションになってあります。その会社で一括して管理をするという話をいただいてありますので、今、そこと調整をしているといったところです。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"ということは、借家人の方々、企業が介入してということなのですけれども、そこはうまくいっているのか、スムーズにいこうとしているのか、感覚でもいいので、教えていただけますか。","respondent":"中道まちづくり立体化担当課長","answer":"今の企業の方とのお話し合いの中では、否定しているわけではございません。今後の補償内容について、どういうふうに取り組んでいくのかといった、具体的な話になっているところです。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"８月上旬から個別説明実施となっているので、やはり見ただけでは、何か分からないというような方々も多くいらっしゃるのが事実だと思うのです。なので、この８月からの個別説明実施というのは、本当に丁寧にやっていただきたいということでお願いをしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"}]},{"id":"topic-05","title":"木造住宅の耐震診断助成額の変更","agenda":"木造住宅の耐震診断助成額の変更","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"東京都建築士事務所協会から要望があったということで、この要望があった内容というのがこの資料に書かれておりますが、伺いたいと思います。そして、今回の増額によって、区としては診断件数が増えていくと見ているのか、その見方も伺いたいと思います。","respondent":"長尾建築課長","answer":"先ほどご説明した内容のほか、現在は１０％というところも、話としては出ておりました。建物の建て替えを検討されている方が非常に多く、現状、それほど多くはない状況になっております。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問","question":"今回の増額で大きく変わらないということだったので、少し残念なのですが、であれば、やはり自己負担分を全額無料にしていって、診断を促進していく。いかがでしょうかということと、やはり受けやすくなるのかと思うのですけれども、いかがか尋ねました。","respondent":"長尾建築課長","answer":"耐震化という側面はあるのですけれども、区としましては補助率２分の１ということで、支援をしていきたいと考えております。診断の申し込みをいただく時期につきましては、手続きができるだけ円滑に進むように、窓口でも対応しています。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問・要望","question":"申請は円滑にということでした。当然円滑にやってほしいのですけれども、個人所有のために２分の１の補助率というお話でしたけれども、全額補償をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"幾つか伺いたいのですが、まず１つは、分かれば教えていただきたい。先ほど１３件と言っていたけれども、この移っていくというのがどれぐらいか教えていただきたいのと、その金額が出てくるわけです。","respondent":"長尾建築課長","answer":"割合からいうと７割、８割というところで、非常に多い状況です。耐震化だけではなく不燃化も併せてといいますか、住みやすいバリアフリーの状況も確保しながらというところが、選択されているのかと感じております。","id":"exchange-041"},{"speaker":"石田（秀）委員","kind":"質問","question":"ほとんど補助金でやれるので、寝室だけ品川シェルターにして命の安全をとお勧めしても、なかなか結びつかない。ですから、すごく私は思っているので、ぜひそこら辺はお願いだけしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"品川区に災害道路があって、なかなか応えられないところは公表するみたいなことを事業の１つでやっていたと思うのです。ただ、やらねばならぬというところがあったと思うのですが、それはいかがか尋ねました。","respondent":"長尾建築課長","answer":"ご説明した木造住宅の耐震化支援とは別の制度で、緊急輸送道路沿道も、耐震診断から補強工事まで支援をしております。そちらにつきましては、耐震化をこれまでも支援しておりますし、今後も継続してやっていくこととしております。","id":"exchange-043"},{"speaker":"西本委員","kind":"意見","question":"診断してもどうなのだと。は、強制をどれだけ働かせるのかみたいなところも必要になってくるのかと思いますので、これは今後検討していただければと思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"}]},{"id":"topic-06","title":"東京都屋外広告物条例におけるプロジェクションマッピングの取扱い","agenda":"東京都屋外広告物条例におけるプロジェクションマッピングの取扱い","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"何で公益行事だと除外になるかと思ったのですが、どのようにお考えなのか、伺いたいと思います。運転手への幻惑作用というのですか、それをどのようにしていくのか、伺いたいと思います。","respondent":"稲田土木管理課長","answer":"３つ目のご質問で、このような項目を設けて、プロジェクションマッピングをしっかりとしたまちづくりに反映することが目的だという状況です。届出が出された場合、また許可申請の場合におきましても、そういうところを区としてはしっかりとチェックしていきたいと考えております。","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問・要望","question":"都の条例でいろいろ指摘がされているということで、それに則ってということでしたけれども、区としては何か基準というのはあるのでしょうか。安全性というのはやはり大事なことだと思うので、そこをしっかりやっていただきたいと思うのですが、いかがか尋ねました。","respondent":"稲田土木管理課長","answer":"これというものはありませんけれども、場所ごとになかなか条件が違うというのが、こういうものです。どういう状況での設置の仕方とか角度とか、申請とか許可を出す段階、そういう中においてチェックをしていきたいと考えております。","id":"exchange-046"},{"speaker":"田中委員","kind":"確認","question":"申請が出されたときに、区として影響がないかどうかのチェックをしに行って、そういったものをチェックして判断するといったところでしょうか。この確認だけさせてください。","respondent":"稲田土木管理課長","answer":"そういう場合におきましては非常に危険が増すですので、いろいろな場面を想定しながら、そういう中においては現場も見ることがあると思います。とにかく事故があってはならないという観点で見ていきます。","id":"exchange-047"},{"speaker":"田中委員","kind":"質問","question":"なるべく事故が起きない観点というのが本当に重要だと思うのです。なるべく現地に行って、本当に安全性を確かめてほしいと思うのですが、いかがか尋ねました。","respondent":"稲田土木管理課長","answer":"申請が出しやすくなるというか、プロジェクションマッピングが大分、表に出てきたという感じはしています。過去に品川区では天王洲で２回、事故があってはなりませんので、その辺のチェックはしっかりしていきたいです。","id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"例えばこの資料にあるように、天王洲で２回ほどやったということですけれども、これは有料だったのでしょうか。金額がどうだったのかと思うのですけれども、区の後援をもらえば優遇してくれるのかとか、それはいかがか尋ねました。","respondent":"稲田土木管理課長","answer":"広告板５m2までごとについて３,２２０円ということで、天王洲のこの写真に載っているところは３００m2ありました。ということは、３,２２０円掛ける５m2の６０単位ということで、１９万３,２００円ということで、手数料はいただいているという状況です。","id":"exchange-049"},{"speaker":"西本委員","kind":"質問・要望","question":"道路に何か光みたいなので映し出していくという、あれもこのプロジェクションマッピングの範疇になるのでしょうか。それこそ、それはきっちりと指導していかなければいけないことだと思うのですが、それはこれに関わってくるのか尋ねました。","respondent":"稲田土木管理課長","answer":"そういう公益性のあるものに対しては、その状況を考えながら、ということで考えております。一時期、その辺でも見かけましたけれども、今はやっていないです。","id":"exchange-050"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それから、１回の許可だけど、その期間中に中身を変える場合があるではないですか。交渉は民間の人たちがやるからいいけれども、その許可申請でどう捉えるのかという考えを、まず教えていただきたい。","respondent":"稲田土木管理課長","answer":"それから、表示期間というのは、３か月以内というのがあります。そういうものであれば、審議会を発足するという状況ですので、東京都とよく調整をしながらという内容になると思います。","id":"exchange-051"},{"speaker":"石田（秀）委員","kind":"質問","question":"やめてしまったのだけれども、オリンピック期間中、例えばどうしようというのが必ず出てくるではないですか。これ、メインスポンサーが「うん」と言ってくれないと映像自体が流せないというのも、どういうふうに考えるのかというのを改めて説明を求めました。","respondent":"稲田土木管理課長","answer":"非常に具体的に今、お話をしていただいたのですけれども、そういうところを事前にやはり諮る必要はあるというところです。あるいは期間をどうするかというのは、やはり個々のその内容によって相談していきたい、いいものができればと思います。","id":"exchange-052"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"条例の審査については区民委員会でしょうから、そこには触れないですが、ぜひこういうものはどんどん推し進めていただいて。あのトランスの上は全く議論にならなかったのか尋ねました。","respondent":"稲田土木管理課長","answer":"これが２０１９年３月１５日から同年８月３１日までです。トランスの上の広告物については、私のほうは今把握しておりませんので、また、その辺、少し調べてみます。","id":"exchange-053"}]},{"id":"topic-07","title":"第二弾マンホールカード配布","agenda":"第二弾マンホールカード配布","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"幾つか確認させていただきたいのですけれども、いつまでなのかということをお伺いしたいのと、枚数の制限があるのかということ。この「品川区では」から始まる文章については、誰が、どこが考えたのかということを伺いたいです。","respondent":"溝口道路課長","answer":"２,０００枚を１つのロット単位で購入できるような形になっておりまして、今回のカードにつきましても、２,０００枚を既に購入しているものです。カードの中に書いてあります説明文につきましては、品川区から写真ですとか説明の内容、説明文につきましては。","id":"exchange-054"},{"speaker":"田中委員","kind":"質問","question":"ＧＫＰというところにつながるのですかというのと、品川区といったことなのですが、品川区の担当はどこですか。下水道がどれだけ重要かということとかを、１文でもいいから書いていただきたかったという観点から質問をしています。","respondent":"溝口道路課長","answer":"マンホールの蓋のデザインをどのような形で描いていくのか、どういうイメージをしたのかというところで、説明を入れするような形になっております。ただ、委員ご指摘のように重要な都市施設ですので、そういったものも併せて…","id":"exchange-055"},{"speaker":"田中委員","kind":"質問","question":"このカードを活用してほしいといった趣旨で書かれているので、ぜひ下水道の重要性というものも１文添えていただけると、いかがか尋ねました。","respondent":"溝口道路課長","answer":"カードをより知ってもらう、ＰＲすることによって、ひいては下水道の普及啓発といったものにつながってくるのだと考えているものです。引き続きこの２枚の発行したカードが多くの方の手に渡るように、ＰＲですとか、そういったものに努めていきたいと考えているところです。","id":"exchange-056"},{"speaker":"田中委員","kind":"質問・要望","question":"１文添えている自治体もあるので、マンホールだけではなく下水道事業にももっと関心がいくように、ぜひお願いしたいと思います。要望でとどめます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"西本委員","kind":"質問","question":"その宣伝をどうするのですかということ。それも品川区の特徴の１つという形になるので、全国的に広めたいという思いもあるのですけれども、その仕掛けはどうするのか尋ねました。","respondent":"溝口道路課長","answer":"かつ郵送等は一切対応しないというのがルールになっておりまして、やはりそのご当地、そういったものに則ってやってきているものです。場合によっては、第一弾を発行しています大井町にも寄っていただければ幸いだと考えているところです。","id":"exchange-058"},{"speaker":"西本委員","kind":"質問","question":"大井町は、あそこに観光案内所があるのですけれども、ここは結構分かりづらいという感じがあるものですから、そこが少し心配です。一応地域を見ていただくという１つの方法はあるにせよ、何か工夫はできないのか尋ねました。","respondent":"溝口道路課長","answer":"やはりまちを歩いてもらうという視点で考えれば、少し分かりにくいほうが、いろいろほかのところを見て回れるというのもあると思います。いいのだというところはないと考えているところもありますので、そういったものもお聞きしながら、配布をしていきたいと考えているところで…","id":"exchange-059"},{"speaker":"西本委員","kind":"質問","question":"今後第三弾、第四弾はないですか。なので、年に１回、１か所とかという形でやっていただければうれしいと思うのですが、いかがか尋ねました。","respondent":"溝口道路課長","answer":"第２回の抽選を受けるのも、まずは区内、デザインマンホールだけで８か所設置しております。それを活用しながら、まずはしっかりＰＲをしていきたい、区の観光に寄与するような取り組みをしていきたいと考えているところです。","id":"exchange-060"},{"speaker":"田中委員","kind":"確認","question":"すみません、先ほど確認し忘れてしまったのですけれども、予算はどうなっているのか、お知らせください。","respondent":"溝口道路課長","answer":"先ほど１ロット２,０００枚で購入ができるという形、これが税抜きで４万円かかりますので、実際カードの発行ですと４万円。マンホール等を設置する場合には、カードの購入費用の税抜きで４万円というのが、費用としては実際にかかるというものです。","id":"exchange-061"}]},{"id":"topic-08","title":"みどりの実態調査の結果","agenda":"みどりの実態調査の結果","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"公園を整備したことでみどりが減少したということだったので、すごく残念なことだったのですが、なぜそうなってしまったのか。そこのところを少し伺いたいのと、この２つある意味というのですか、教えてほしいと求めました。","respondent":"高梨公園課長","answer":"５年後、１０年後にはしっかりと枝葉を張って、認識をしています。２点目、みどりの実態調査を進めてまいりましたが、みどり率で現在のところその評価を行っているのがスタンダードになっているところです。","id":"exchange-062"},{"speaker":"のだて委員","kind":"質問・要望","question":"それが多分緑被率に大きく寄与していたということだと思うので、そういったところも重視しながら、緑被率を上げてほしいと求めました。緑被率のほうも見ていくべきではないかと思うのですが、いかがでしょうかということと、みどり率で見ている理由を伺いたいと思います。","respondent":"高梨公園課長","answer":"樹木被覆地が減少しているという結果につきましては、公園整備のみならず、公園自体を増やす取り組みというのも、この５年間で進めているところです。しっかりと緑被率のほうも継続して見ていくということは、今までと変わらずに行ってまいりますが…","id":"exchange-063"},{"speaker":"のだて委員","kind":"意見","question":"なので、やはり緑被率の目標をもっていく必要があるのではないかと思います。今後、計画の見直しを検討されていくと思いますので、そういったところでも、ぜひ緑被率の目標ももつような形で検討していただけたらと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"},{"speaker":"田中委員","kind":"質問・要望","question":"どういう意味なのかというのを知りたくて、お知らせいただきたいのと、そのスケジュール感を伺っていきたいです。その中できっと示されているとは思うのですけれども、今どのように豊かにしていくのかというのが検討されているのかを、伺えればと思うのですが。","respondent":"高梨公園課長","answer":"今の予定としましては、年度末までに素案のとりまとめといったところを、１つのコントロールポイントで考えているところです。その後、来年度に入りまして、年度当初からパブリックコメントを実施し、年度中盤ぐらいで計画の改定公表といったところが、現在のスケジュールです。","id":"exchange-065"},{"speaker":"田中委員","kind":"確認","question":"この建設委員会でも、この素案の作成だったり報告だったり、これからきちんと上がってくるのですよね。では、これから確認していきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"西本委員","kind":"質問・要望","question":"この品川区のゴールは何かというところ、何を求めているのだろうか。当然それが入ってくるのだろうと思いますけれども、品川区の現状として、どういう方向性にもっていきたいのかを説明を求めました。","respondent":"高梨公園課長","answer":"現在の状況に合った、今の品川区のまちづくりに合った緑化の目標といったものを、今後考えていかなければいけない。潤いのある暮らしが実現できるいい手法を、今後、計画改定の中でしっかりと議論していこうと考えています。","id":"exchange-067"},{"speaker":"西本委員","kind":"質問・要望","question":"その部分は育っていって、茂ると、そこはみどり率等が高くなるわけではないですか。どういう品川区のみどり環境というか、みどり率というのを求めていくのかとなってくると、何のためにこれをやっているのかということですよね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１年を通じて、１年間通じた、親しめる「色」というのもぜひ取り入れていただきたい。そこら辺の感覚は少し教えていただきたい。","respondent":"高梨公園課長","answer":"そういったところの色という概念は、このみどりの実態調査、もしくは基本計画の中ではございませんでした。今、ヒントをいただきましたので、検討委員会の中では、要素としてしっかり議論をさせていただきたい、このように感じているところです。","id":"exchange-069"},{"speaker":"田中委員","kind":"確認","question":"数値目標は目標でやはり重要かとも思うので、ご答弁の中で、まちづくりのどこに重点を置くかとかでも変わってくると思います。何というのだろう、数値目標は目標としてもっていてもいいのではないかと思ったので、そこの部分だけ少し確認させてください。","respondent":"高梨公園課長","answer":"結論から申しますと、そこも含めて検討なのかなと考えています。そういったものを含めて、検討委員会の中では議論をいただきたい、このように考えております。","id":"exchange-070"}]},{"id":"topic-09","title":"第二戸越幹線整備工事（下水道本管立坑整備）","agenda":"第二戸越幹線整備工事（下水道本管立坑整備）","exchanges":[{"speaker":"西本委員","kind":"質問","question":"この４項目は、やはり事前の調査の中では分からなかったという内容のものなのでしょうか。突発的なことで、通常よりは特殊な状況だったという理解でよろしいのか尋ねました。","respondent":"松本河川下水道課長","answer":"変更の内容につきましては、設計時点で分かっているものについては、設計の中で取り込んです。第１回目の変更のときにお示しさせていただいてはいるのですが、その変更に伴って、今回変更させていただいている状況です。","id":"exchange-071"},{"speaker":"西本委員","kind":"質問","question":"それとも、変わらずこの期間でやるということでしょうか。工期の変更はあるのか尋ねました。","respondent":"松本河川下水道課長","answer":"工期につきましては、今回の変更内容につきましての変更はございません。","id":"exchange-072"},{"speaker":"西本委員","kind":"意見","question":"今ほかのところでいろいろな活動をされているというところもあって、延びると、また説明が必要なのかと思ったのです。そういうものがなければ、このままで進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-073"},{"speaker":"のだて委員","kind":"質問","question":"工期のところで、今回７月１６日までということですが、その後に西品川公園は使えるようになるということですか。いつから使えるのかというところで、伺いたいと思います。","respondent":"松本河川下水道課長","answer":"この工事につきましての工期は７月１６日までとなっています。令和６年までを予定しておりますので、一応、令和６年度まで使用するという予定です。","id":"exchange-074"}]},{"id":"topic-10","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"出ていましたか。ほかの意見もいろいろあったと思うのですが、この２つの項目になった理由というのをもう少し詳しくありましたら、伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-075"},{"speaker":"西本委員","kind":"質問","question":"「まちづくりに関すること」というように入っているのですが、これは、連続立体交差事業とその周辺ということではなくて、もっと広い意味での、例えばマスタープランとかも含めての「関すること」ということの理解でよろしいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"},{"speaker":"田中委員","kind":"確認","question":"私も確認です。今、確認をしたいと思ったのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"線引きは委員長にお任せするけれども、だけど、ここは本当に建設委員会の中でやっていかないと、いろいろ中身で入れないところが相当出てきてしまう。お任せしますが、ぜひそこら辺は考えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-078"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/733618?Template=document&Id=4296#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":55606,"voices":213}},{"id":"r02-20200630-9","meetingId":"r02-cm06","date":"2020年6月30日","dateIso":"2020-06-30","committee":"文教委員会","time":"午前１０時００分～午後 ２時３９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を75件整理しています。","topics":[{"id":"topic-01","title":"学校改築の進捗","agenda":"学校改築の進捗","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回２４学級を想定されているということで、ここに限らず改築時の計画、学級数の設定の考え方について伺いたいと思います。具体的に何の要素などに基づいて決めているのか、全て教えてもらえるとありがたいです。","respondent":"小林学校施設担当課長","answer":"学級数の設定の仕方ですが、就学人口などを見据えて、将来の計画をしております。それと、近隣でのマンションなどの建設も視野に入れて、学級数を最大限とれるように工夫しています。","id":"exchange-001"},{"speaker":"安藤委員","kind":"確認","question":"それはどういうふうに予想しているのかということと、それは都市計画課などと連携して、確認しているのかということを聞きたいと思います。この図面ですが、特別支援学級の教室の場所は１階になっているのですけれど、なぜこういうところにあるのか伺いたいと思います。","respondent":"篠田学務課長、小林学校施設担当課長","answer":"私から、就学人口の予測についてご説明いたします。区のほうでは先々の人口の予測を立ててありますので、そういったものも加味しながら、就学人口の想定をしています。 今お話ししたとおり就学人口ならびに都市計画課などとの連携を図りながら、学級数を最大限とっているところです。１階に特別支援学級があって、特別支援学級でもお子様の状況はいろいろありまして…","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"第四日野小学校の場合は保護者の方でしょうか、当事者家族でしょうか、改善してほしいというような声も伺います。できれば改善してほしいという声も一方で伺うので、様々なご意見をなるべく頂戴した上で、最終的に慎重に判断してほしいと求めました。","respondent":"小林学校施設担当課長","answer":"それと特別支援教室につきましては、基本的には委員がおっしゃるとおり、普通教室に近いところを望むケースが多いと思います。症状が比較的軽微な生徒ということで、普通教室から離してほしいというご要望があったので、今回はそういうふうにしたです。","id":"exchange-003"},{"speaker":"せお委員","kind":"質問","question":"今のお話ですけれど、そもそも特別支援学級ですか。第四日野小学校は１枚目のところで計画学級数、特支（通級１室）となっているのですけれど、これはどういうことか尋ねました。","respondent":"小林学校施設担当課長","answer":"二つとも特別支援学級のことでございまして、授業によって特別支援学級のほうに通所し、そちらで授業を受けたりということを行っているのが通級と。普通教室に在籍しないで特別支援学級に直接行って、そちらで授業を行って帰っていくという…","id":"exchange-004"},{"speaker":"せお委員","kind":"質問","question":"言い方なのですが、品川区では特別支援学級と特別支援教室の通級は違うと思うのです。ということは、第四日野小学校にできるのは、結局、通級１室ができるということでよろしいのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"特別支援教室というのは、１週間に１回ぐらい別の教室に行って、そこで学習するというスタイル。それはもう全都に広がってございまして、その部屋が特別支援教室と言って、全ての小学校、中学校にあります。","id":"exchange-005"},{"speaker":"せお委員","kind":"質問","question":"第四日野小学校でいうと、これは特別支援教室ということですね。この１部屋だけを使うのかということがありまして、やはり私としては、この第四日野小学校でほかに使える部屋とかがあれば説明を求めました。","respondent":"小林学校施設担当課長","answer":"例えば多目的教室とか、これは学校の考え方によって変わってくると思いますが、そういう部屋を使ったりということは可能だと思います。は授業の関係でどうやっていくかというのは、学校が今後決めていくことかと思っているところです。","id":"exchange-006"},{"speaker":"せお委員","kind":"質問","question":"コンセプトの２番に四日野ルームというものが書かれているのですけれど、具体的に何か決まっていることがあれば教えてください。どのような交流をするのか。","respondent":"小林学校施設担当課長","answer":"学年を飛び越えた交流の場をつくったり、ランチをしたり、いろいろなことで使われると思います。これは学校が今後計画していくと思います。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"１点が、工期が大分先のものはあまり関係ないかもしれないですけれども、今日ご説明いただいた中で特段影響があるものがあれば教えてください。日影の関係あるいは校庭に対してどういう時期にどういう影がというような、概略を教えてほしいと求めました。","respondent":"小林学校施設担当課長","answer":"順調にいくものと考えています。方位とかいろいろあるのですけれども、そこで一番近隣に与える影響が少ないよう考えたところで、南西の位置に落ち着いたところです。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"今は違うのですか。近隣に影を落とさないようにというのが校舎の配置計画の第一になってくるものなのか尋ねました。","respondent":"小林学校施設担当課長","answer":"当然日影を校庭に落とすというのは、自分のところではやらなくて、北側に持っていったところが多かったと思います。北側に持っていくと、当然近隣の敷地が日影になってきますので、説明会でもトラブルになる要素になります。","id":"exchange-009"},{"speaker":"あべ委員","kind":"確認","question":"計画学級数と書いてある１８とか２４というのは、普通学級の数字ということでしょうか。一応確認です。","respondent":"小林学校施設担当課長","answer":"計画学級数、１８学級、２４学級などと書いてあるのは、委員おっしゃるとおり普通教室の最大限の数です。それと特別支援学級につきましては委員おっしゃるとおりでございまして、普通教室程度の大きさで設置しています。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"２枚目の第四日野小学校の平面図を見ると、これは通級の特別支援で、いわゆる通級のイメージで考えればよいということで間違いないでしょうか。改善を求められていたところではないかと思うのですが、その点についてどのように、この設計についてお考えか尋ねました。","respondent":"小林学校施設担当課長","answer":"実施設計と、実施設計を進めておりますけれども、先ほどもお話ししましたが設計条件を整えていきます。今回の特別支援通級教室ですけれども、今回、今回はいろいろな条件から判断したところです。","id":"exchange-011"},{"speaker":"あべ委員","kind":"質問","question":"声を聞く相手というのは、教育委員会内、関係部署あるいは学校だけなのでしょうか。保護者の声までは聞くようになっていないか尋ねました。","respondent":"小林学校施設担当課長","answer":"我々は専門の知識を持った人等も含めていろいろな方からご意見をいただき、今お話ししましたように町会長も入れて話し合いもしました。そういうところからの要望があったときは最大限聞き入れるように、計画はしたところです。","id":"exchange-012"},{"speaker":"あべ委員","kind":"質問","question":"そうするとやはり、できるだけ当事者に近い方にそれぞれ聞くということを、今後やってほしいと求めました。最後、ご答弁をお願いします。","respondent":"小林学校施設担当課長、矢部教育総合支援センター長","answer":"我々は今お話ししたとおり、関係部署と綿密な連絡、調整をしております。指導課、教育総合支援センター等とも打ち合わせをしまして、引き続き関連部署との綿密な打ち合わせをもとに進めていきたいと考えています。 学校の実態は、基本的にこの特別支援教室に通うお子さんというのは、１週間に２時間程度ですので、ほぼ教室でみんなと仲よくやっております。それと同時に、比較的落ち着いた静かな場所というのも…","id":"exchange-013"},{"speaker":"たけうち委員","kind":"質問・要望","question":"今、換気も同時にできるようなタイプも、高額だと思うのですけれどそういったものも出てきているやに聞いています。間に合わないとかそれぞれあるとは思うのですが、その辺は何か検討していたり、研究していたりすることがあれば教えていただきたいです。","respondent":"小林学校施設担当課長","answer":"検討段階の中では、普通の換気扇だと効率がよくないので、熱交換をしての換気というものがあります。そのときに熱交換をしてやるという換気方法が全熱交換器というものなのですけれども、そういうものを設置したり、今後研究してまいりたいと思います。","id":"exchange-014"},{"speaker":"たけうち委員","kind":"質問・要望","question":"日進月歩ではないですが、どんどん新しいものが出てくると思うので、その都度またいろいろ検討されると思うのですが、特にコロナの関係でそういう懸念もされているので、ぜひ、可能な限り配慮してほしいと求めましたので、要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"横山委員","kind":"質問・要望","question":"２点は具体的なイメージが分かりましたら教えていただきたいのですけれども、具体的なイメージを教えていただけたらと思います。３点目ですけれども、今年１月に日野学園のプールの更衣室で、分かりましたら教えていただけたらと思います。","respondent":"小林学校施設担当課長","answer":"鉄道からの距離を離しての騒音対策というのがまず１点と、防音対策として植栽等を設置したり、２階からはちょっとセットバックをして建てていること。ここについては屋上に設置しておりますので、温水プールではございませんので、湿気については基本的に大丈夫と考えています。","id":"exchange-016"},{"speaker":"横山委員","kind":"質問・要望","question":"地域の方が入りやすいような動線ですとか、分かりやすい動線を検討していただいているということで、確認させていただきました。更衣室も５階ですので、それほど湿気がたまりやすいかどうかというと、湿気対策もぜひ進めていっていただきたいと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"筒井委員","kind":"確認","question":"確認ですけれど、人口増に柔軟に対応するために作っていくという方針なのかということを、まず１点お伺いいたします。","respondent":"小林学校施設担当課長","answer":"就学人口に合わせて、将来を想定しましてできる範囲、この敷地の中でできる範囲の学級数をとっているところです。委員のおっしゃるとおり、多目的教室というのは現状ではそういうふうに使って、将来就学人口が増えたときに、普通教室に改修して使用するです。","id":"exchange-018"},{"speaker":"筒井委員","kind":"質問","question":"２点目としまして、そうした調査とか、またもし出た場合の対応とかはどのようにお考えなのか尋ねました。","respondent":"小林学校施設担当課長","answer":"埋蔵文化財等につきましては、発見というか出てきた段階で適正な方法をとって、工事のほうを進めていきます。土壌汚染につきましては、撤去をして普通の汚染されていない土に入替えるとか、それについては法律に基づいて対応していくです。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"既に工事をやられたところはあるのですけれども、浜川小学校の調査段階、設計の段階とか、現段階では特に問題は発生しないということでよろしいか尋ねました。","respondent":"小林学校施設担当課長","answer":"はい、そのとおりです。","id":"exchange-020"},{"speaker":"芹澤副委員長","kind":"確認","question":"第四日野小学校で１点だけ確認なのですが、コンセプトの１の二番目、校庭が人工芝になるというお話だったと思うのですね。人工芝になっているのかなと思うのですが、この状況の中での区民まつりの活用というのは、どういった話し合いになっているのか尋ねました。","respondent":"小林学校施設担当課長","answer":"こちらは計画を進めている段階で、準備懇談会と言いまして、地域を入れた打ち合わせを数回行ったところです。学校の校庭を確保するのもかなり難しかったというところで、意見を頂戴しましたけれども、今回はこういう配置で進めていくです。","id":"exchange-021"},{"speaker":"あべ委員","kind":"質問","question":"それぞれのパースを見ると、人工芝、それから舗装のものもあるのでしょうか。比較的影響が少ないのではないかと思うのですけれども、それに対する配慮などは何かされるのか、お願いします。","respondent":"小林学校施設担当課長","answer":"いろいろなことは考えられると思うのですが、災害の対応のほうを優先してやるべきであり、そのような感じです。いろいろとご意見を頂戴しますので、いろいろと検討した中では人工芝が最適ということで、現在のところは考えているところです。","id":"exchange-022"},{"speaker":"あべ委員","kind":"質問","question":"それぞれどうなっていて、なぜ違うものが選択されているのかという質問だったので、もう一度ご答弁をほしいと求めました。途中からだと大変だと思うので、そこを配慮していただけるでしょうかというお話で、もう一度お願いします。","respondent":"小林学校施設担当課長","answer":"一部茶色の部分もありますけれども、ここについても人工芝を考えているところです。そういうところは小まめに清掃をすることにより、流れていかないように努めていきたいと考えています。","id":"exchange-023"},{"speaker":"あべ委員","kind":"質問・要望","question":"人工芝にトラックが書いてあるということなのでしょうか。そういうことが、一時はスタンダードになっていたと思うのですけれどもいかがか尋ねました。","respondent":"小林学校施設担当課長","answer":"鮫浜小学校のトラックにつきましても、白の人工芝とか、色を塗るとか、そういうものはありますので、それについてはこのとおり描いていく予定です。そういう関係で建物自体でも耐震化を図っておりまして…","id":"exchange-024"}]},{"id":"topic-02","title":"その他のうち、(1)所管質問","agenda":"その他のうち、(1)所管質問","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"昨日も申し上げましたけれども、本会議の中で松本議員ならびに中塚議員より、品川区の区立学校、特に中学校の校則についての質問がありました。それから内容について、あるいは今後の対応について、教えてほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"私から、委員ご指摘の２点についてお答えをします。ただ、実際は個別の対応や配慮も多くありまして、弾力的に対応しております。","id":"exchange-025"},{"speaker":"あべ委員","kind":"質問","question":"現実に合わせて、やはりここは変えるべきだと思うのです。適宜そういうことに気づいたら見直す学校であってほしいと思うのですけれども、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"これまでも学校のほうには働きかけておりますので、引き続き、続けていきたいと思います。大事なところは、児童や生徒がきちっと理解をして、行動するということかと思います。","id":"exchange-026"},{"speaker":"あべ委員","kind":"質問・要望","question":"やはり、人には他人から指図されてはいけないものがあるということを、特に子どもたちにはぜひ理解をしてほしいと求めました。それについては、教育委員会のお考えはいかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"特に３、４年生の時点で既に、ルールの意味を考えるという内容があります。子どもたちに廊下を走ってはいけない理由は何かということを考えさせる場面はありますので、上手に組み合わせて指導してまいりたいと考えています。","id":"exchange-027"},{"speaker":"あべ委員","kind":"質問","question":"これについては、また今後の進捗などを教えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"改善を求めていくというか、そういうことも教育委員会としては必要ではないかということなのですが、それについてはいかがでしょうかというのが一つ。自主的な解決を求めているとか、児童・生徒の中で議論してもらいたいとかという話も出たのですが、実際にそういうことは行われているのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"「必要な範囲内では校内で指導や指示を行い、その範疇の中でどこまでが、学校のほうで検討するべきだと考えています。委員ご指摘のとおり、たくさんの教育活動の中の１点ではありますが、市民科を中心に指導しているという事実はあります。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういった実践が行われるように、それこそが生きた教育ではないかと思いますし、よろしくお願いしたいと思います。誰がどう見ても理不尽な内容で、そこら辺も踏まえてしっかりと、これからも取り組んでいってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"せお委員","kind":"質問","question":"一般質問の答弁でも、生徒会などで校則を決めるということであれば、生徒たちに多様性についても学んでほしいと思います。多様性を学ぶ機会というのは、特に中学校ではどういった取り組みとかがありますか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"先ほどちらっとお伝えしましたけれど、個別の対応や配慮がもう既にありまして、実際には校則どおりいかない場合もあると思います。今後とも多様性については、大切だと考えていますので進めてまいります。","id":"exchange-031"},{"speaker":"せお委員","kind":"意見","question":"多様性について学ぶことは、これからはとても大切だと思いますので、先ほども、協調性を育む四日野ルームとあったと思いますけれど、多様性を学んでいけば協調性はついてくるものだと思うので、そういったところも含めて授業でも、授業以外のところでも…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"}]},{"id":"topic-03","title":"ガバメントクラウドファンディングを活用した子どもの食の支援事業～新型コロナウイルス感染症対策に関する緊急支援として～","agenda":"ガバメントクラウドファンディングを活用した子どもの食の支援事業～新型コロナウイルス感染症対策に関する緊急支援として～","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"もう一度お金について確認させていただきたいのですけれども、それからクラウドファンディングは手数料その他の経費がかかると思います。その内訳、そして食品の選定と調達業者をどのように選んで、どこになったのかということを説明を求めました。","respondent":"三ッ橋子育て応援課長","answer":"したがいまして、この残額３１９万１９７円相当額を、第２回目のしあわせ食卓事業として対応してまいります。その残額が保管料、配送料となっております。","id":"exchange-033"},{"speaker":"あべ委員","kind":"質問","question":"そうすると７９万円は２５８世帯ですから、５,０００円分を充てたということなのでしょうか。そこまでいいか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"単純に５５７万３,０７３円から子ども応援基金の１００万円を除き、１３８万２,８７６円を差し引いたものが、３１９万１９７円となっております。こちらは先ほど委員ご指摘のように、１家庭分の商品代と申し上げましたのは、１世帯分として考えてください。","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問","question":"それと最初の質問で、食品の選定ならびに調達業者をどう選んだのかということを説明を求めました。","respondent":"三ッ橋子育て応援課長","answer":"失礼いたしました。食品ロスの削減に取り組む業者であり、しながわＣＳＲ推進協議会会員となっております、株式会社クラダシというところを使っております。","id":"exchange-035"},{"speaker":"あべ委員","kind":"質問","question":"その５,０００円の中で、その企業が自分の手持ちの食品ロスの食材を選んで、つまり幾ら分のものを５,０００円として購入されているのでしょうか。いわゆる一般価格よりは相当安く入手され、販売されている企業かと思いますけれど、どのような感じか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"こちらの商品代は５,５７０円分ですが、一般価格で申し上げますと、１万７,０００円相当です。","id":"exchange-036"},{"speaker":"あべ委員","kind":"質問","question":"そこら辺、どういうものを選ぶかというのは、区としてもきちんと入っていらっしゃるのでしょうか。それだけだとなかなか、ストレートなお声は聞きにくいと思うのですけれども、その選定についてはどのようになさっているのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"特に食品ロスというものが中心になりますので、輸入物ではなく、日本の一般的に売られているものを中心にということを伝えてあります。かなりよい物と、普及されているものの中、一般的なものが中心となっています。","id":"exchange-037"},{"speaker":"あべ委員","kind":"質問","question":"アンケートですが、無料で宅配までしたら、喜びの声というのは当然来ると思うのですけれども、クオリティーを上げていくためには、率直にどう受け止めたかというお声が大切だと思うのですが、それについて何か工夫はされていますか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"いろいろあるので、全てを網羅することはなかなか難しいのですけれども、ご意見は捉えながら対応してまいります。","id":"exchange-038"},{"speaker":"あべ委員","kind":"質問・要望","question":"最後は要望になりますけれども、やはりこういう事業は各自治体でやっていて、主食になるものが一番、困っている方ほど喜ばれるということなのですね。そういうこともぜひ勘案して、こちらの都合というよりは求められているもの、引き続き努力をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問","question":"アンケートですけれども、何人ぐらい返信があって、どういう項目を聞いているかというのを聞かせてください。前回第１回目の２５８世帯に加えて、配送希望というのはどういうふうにつかむのかということで、この事業の周知はどういうふうにやるのか伺います。","respondent":"三ッ橋子育て応援課長","answer":"周知方法ですが、今回はひとり親家庭等医療証と共に発送いたしまして、食の支援が必要な方が申請してくるというものです。広報しながわとホームページではお知らせしております。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問","question":"アンケートの回答数といいますか、何人ぐらいかというのだけ、最後に説明を求めました。","respondent":"三ッ橋子育て応援課長","answer":"アンケートの回答数ですが、最終的には５０％の１２９人でございました。最初にしあわせ食卓事業のお知らせをしたときのアンケートにつきましては１００％の２５８人です。","id":"exchange-041"},{"speaker":"たけうち委員","kind":"質問","question":"第１回目で２５８世帯、４月１日までの新たな方ということですけれど、その方は１回目は希望されなかったと思うのです。今回はあくまで前回、第１回目に送られた方を対象として、それ以外の方については基本的に受けないという考えか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"令和２年度のしあわせ食卓事業につきましては、食の支援が必要かどうかのお知らせをしていき、そしてご要望をとる予定です。それは令和元年度と同様に１２月と考えております。","id":"exchange-042"},{"speaker":"たけうち委員","kind":"質問","question":"これについては直接対象者にご案内するので、今のところ広報とかホームページとか、そういうところで募集をされないのですよね。次の１２月と言わずに何かお知らせして、何か対応できないかという希望があるのですけれど、いかがか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"区としては１２月と考えておりますけれども、東京都が児童扶養手当受給者に対して、カタログで商品も配送するということを考えているようなのです。そちらに手を挙げていただき、希望されれば食品等が来る予定だと考えています。","id":"exchange-043"},{"speaker":"たけうち委員","kind":"質問・要望","question":"では、そちらのほうの周知もしっかりやっていただきながら、ぜひ可能な限り、要望だけさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"横山委員","kind":"質問","question":"アンケートの部分をお聞きしたいのですけれども、配送を希望しなかった理由というのは、今回何かあるのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"配送を希望しない方というのは、今回は食品を配送しますということしかお伝えしていなくて、そのアンケートしかとっておりませんので、皆さん、食品の配送を希望された方という形になっております。","id":"exchange-045"},{"speaker":"横山委員","kind":"確認","question":"確認なのですけれども、配送を希望される方だけを対象にしたアンケートをとったということなのでしょうか。医療証を受給している方全体としてとっていらっしゃるのか、食品を希望された方だけを対象にしたアンケートになっているのか、説明を求めました。","respondent":"三ッ橋子育て応援課長","answer":"医療証の配送のとき、しあわせ食卓事業がありますというお知らせをして、その食品の配送を希望される方から、アンケートの答えをいただいたということになります。","id":"exchange-046"},{"speaker":"横山委員","kind":"質問・要望","question":"その辺りも次回以降、検討していただければと思っていますが、ご見解をお聞かせほしいと求めました。９月以降始めますということを、その辺りもお願いしたいのですが、ご答弁ほしいと求めました。","respondent":"三ッ橋子育て応援課長","answer":"配送を希望しない理由というものをアンケートの項目として入れるかどうかは、じっくりと考えさせていただきたいと思います。しながわ活力応援給付金に関しましても、９月から私どものガバメントクラウドファンディングを実施するということは周知してまいる予定です。","id":"exchange-047"},{"speaker":"あべ委員","kind":"質問・要望","question":"午前中には事実関係の確認を中心にさせていただきましたが、この後、質問をいろいろさせてほしいと求めました。品川区ではどのような配送方法を考えているのか、説明を求めました。","respondent":"三ッ橋子育て応援課長","answer":"今回の第１回のガバメントクラウドファンディング、子どもの食の支援事業を検証し、その辺りを考えていきたいと考えています。ほかの区では確かに、委員ご指摘のように見守りを兼ねているところもありますけれども、今のところは宅配業者というふうに考えております。","id":"exchange-048"},{"speaker":"あべ委員","kind":"質問","question":"今の二つの質問はつながっておりまして、つまりこの事業の目的というのは、困っているから、困窮しているから食材をさしあげましょうということなのか、それとも食材を提供することをきっかけとして、支援につなげるということが主な目的になっているのか、どちらなのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"就労支援、住宅の保証料の支援など、区の支援のお知らせも一緒に届けているところです。そのような考えに基づいております。","id":"exchange-049"},{"speaker":"あべ委員","kind":"質問","question":"その考えはとても賛同するところですけれども、実際にアンケートも半分戻ってきたということで、今回１回目を届けたことで、支援に何件つながったのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"今回の支援の中で関心を持ったものという項目もありまして、学習支援のこと、また就労支援など。就労支援もありますけれども、様々な方のご意見を今回初めて直接いただけたということで、区としても支援につなげていくきっかけとなっております。","id":"exchange-050"},{"speaker":"あべ委員","kind":"意見","question":"そうした形で支援につながっていくのはとてもいいなと考えています。現在２５８世帯ということですけれども、５６０世帯、また工夫をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望なのですが、コロナの影響で新たに希望する方に届けるべきではないかというご意見があり、そのとおりだと思うのです。そこは何とか、こういう事業をやること自体は区民に伝わるわけですから、そういったご希望が寄せられると思うのです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"}]},{"id":"topic-04","title":"ひろまち保育園閉園に伴う在園児の優先転園","agenda":"ひろまち保育園閉園に伴う在園児の優先転園","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"伺いたいのですが、所管課としては、途中転園の子どもへの影響についてどう考えているのか伺いたいというのが１点です。保育園部局としてそういう提案をちゃんとしたのかどうか、それともしなかったのか、伺いたいと思いますとの意見を述べました。","respondent":"立木保育課長、吉田保育施設調整担当課長","answer":"転園に関してのお子さんへの影響ですけれども、やはり環境が変わることに関しまして、お子様にも負担がかかるということは理解しております。保育士のほうがきちっとお子さんの様子を見ながら対応していくということで… 閉園を延ばす方向での検討についてですが、広町の開発がある中で、もともと５年間の期間限定ということで、スタートしたところです。令和３年以降、広町のまちづくりの予定があることから、当初の予定どおり５年で閉園するところです。","id":"exchange-053"},{"speaker":"安藤委員","kind":"提案","question":"この閉園時期を延ばしていただけないですかという提案を、提案したのか、しなかったのかをお答えください。その上で、優先転園を案内するだけでなく、この方針そのものを、閉園延期も含めて再検討してほしいと求めましたけれども、いかがか尋ねました。","respondent":"吉田保育施設調整担当課長、立木保育課長","answer":"それから、所管としてどういうふうな考え方かということですけれども、昨年度から在園児につきましては、優先転園の対応をしてきたところです。現在の２歳児、３歳児、４歳児につきましては、今まで同様… そうした中、ふだんの保育中からお子様の変化は敏感に捉えているところがありますので、そういった中でしっかり見られるということです。お子様の保育という部分に関しては影響が出ないように、しっかりと保育士と共に勉強しながら…","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"子どもたちにものすごいストレスがかかっていますし、コロナの危機を経て社会も大きく、何を求めていくかというのは随分変わってきているのですよね。これまでの決まったものだというふうに進めるのではなく、大胆に見直しをかけていく、子どもを第一に考えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"あべ委員","kind":"質問","question":"１歳児、２歳児、３歳児で募集していたでしょうか。各年齢での現在の人数と、引き続き今年度も、このひろまちの定期保育にご案内していくのかどうかということを説明を求めました。","respondent":"立木保育課長","answer":"６月の在籍数で、１歳児が３０名、２歳児が１５名、３歳児が１０名という形になっております。こちらは空きスペースがあって、定員に余裕がある場合には、今年度中はお預かりをするという形になってあります。","id":"exchange-056"},{"speaker":"あべ委員","kind":"質問","question":"この年間保育、基本的にはフルタイムの方が多いということなのでしょうか。２歳児、３歳児合わせて現在５５人、その辺は把握されていますか。","respondent":"立木保育課長","answer":"詳細、個別のデータを持ち合わせていないので、お答えがはっきりとできないのですけれども、定期利用に関しましてはやはり入園審査がありますので、それなりに時間数等もある方がご利用されるというふうに考えております。","id":"exchange-057"},{"speaker":"あべ委員","kind":"質問・要望","question":"それは、このご報告の中にも数字として示してほしいと求めましたし、来年度はもうないわけですよね、この子どもたちに対しては。３歳、４歳になっていくわけですから、そこの需給予測というのはどうなっているのか尋ねました。","respondent":"立木保育課長","answer":"４歳児、５歳児ということで、現時点で定員ベースでとれているというところです。年間保育利用を含めまして、大きな影響は出ないというところで、計算をしたものです。","id":"exchange-058"},{"speaker":"あべ委員","kind":"質問・要望","question":"少なくとも今の５５人、それはこの３１名だけではなく、当然これは継続の需要は発生するものとして扱ってほしいと求めました。保育の受け皿の拡大というのをぜひ図っていただきたいと思っているのですけれど、その来年度の予測というのはどのようにお考えか尋ねました。","respondent":"立木保育課長","answer":"少し前、５月ごろの入園可能数でいきますと、全体で１,２００名ぐらいの空き枠が、５月ぐらいでもあったわけです。そういったところをきめ細かくすることによって、数的には十分満たしていけるのではないかというところで、考えているところであります。","id":"exchange-059"},{"speaker":"あべ委員","kind":"質問","question":"１,２００人といっても年齢もありますし、地域もありますので、必ずしもそこまで選べる状態だと私は受け止めていません。今後品川区とどのような関係になっていくのか、それを引き継ぐことができるのか、説明を求めました。","respondent":"立木保育課長","answer":"やはり連携という部分で、公立保育園も含めた連携というのは今後、何かしらとっていくべきだろうと。品川区はレベル的には高いものがあるというふうに自負していますが、培ったものはそのまま捨てることなく、活かしていきたいと考えています。","id":"exchange-060"}]},{"id":"topic-05","title":"上大崎三丁目教育・保育施設の整備・運営事業者の選定","agenda":"上大崎三丁目教育・保育施設の整備・運営事業者の選定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"すみません、私は文教委員、相当久しぶりというか、ほぼ初めてなので改めて伺いたいのですが、ここを認定こども園とした理由といいますか、区の考えを伺いたいのと同時に、改めて認定こども園とは、保育園や幼稚園と何が違うのか、教えてほしいと求めました。","respondent":"若生保育支援課長","answer":"教育ですとか在宅子育て支援といったニーズが高いといった観点から、教育機能も備えた認定こども園ということで、今回プロポーザルにかけた次第です。説明の中でも申し上げましたけれども、０歳児から５歳児までをお預かりすると共に…","id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"伺いたいのは、地元との調整や話し合いの現状について伺いたいのですけれど、その辺はどうなっているのか伺いたいと思います。住民の理解というのは率直に得られているということなのか尋ねました。","respondent":"若生保育支援課長","answer":"昨年度の１０月１８日に今度は近隣住民を対象として、内容に関して区としての説明会、こちらを地域センターで行ったところです。自転車といった交通手段、園に通われる保護者ですとか、通行に関するところに十分配慮してほしいといったようなお声が寄せられたところです。","id":"exchange-062"},{"speaker":"安藤委員","kind":"提案","question":"もしかすると既に提案が出ているのかもしれないですが、取り入れられる要望は取り入れながら、丁寧な進め方が必要だと思うのです。そういうこともやっていただきたいのですけれど、いかがか尋ねました。","respondent":"若生保育支援課長","answer":"その後、事業者のほうが主体となって、まずは近隣に対して説明会を行うということで、私どもは聞いてあります。どういう建物を建てていくのかというところは事業者のほうからきちんと説明させていただいて、よりよい施設づくりを進めてまいりたいと考えています。","id":"exchange-063"},{"speaker":"あべ委員","kind":"質問","question":"これは３０年間の貸付で行うということですけれども、国からこれを購入して、定期借地で貸付料というのはどのぐらいになるのでしょうか。これは例えばプレハブみたいなものになるのか、鉄骨とか入れる感じでもなさそうですが、どういうふうになるのか尋ねました。","respondent":"若生保育支援課長","answer":"想定している金額等も検討しつつ調整していきたいと考えていますが、普通に貸し出すとそういった料金がかかるということでございました。教育のほうの人数に関しましては９人から１０人程度ということで、提案いただいているところです。","id":"exchange-064"},{"speaker":"あべ委員","kind":"質問","question":"それから１０月開設ということですが、あまり教育部門の年度途中開設というのは、これは少し時間差になるのでしょうか。子育て支援機能というのは１０月スタートということになるか尋ねました。","respondent":"若生保育支援課長","answer":"来月以降、先ほど申し上げたとおり地域等に説明等を行いまして、これからこういう内容で実施していきますということできちんと周知した上で。教育部門と子育て支援機能の部分が１０月から開始できるかですけれども、子育て支援機能、１０月開始ということで考えております。","id":"exchange-065"},{"speaker":"あべ委員","kind":"意見","question":"最後になりますけれども、これから解体工事に入られるということで、あの地域もなかなか、道路といいますか入りにくかったり、住宅街で道も狭めということで、そこは十分理解を得ながら、かつ安全にやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"６月２９日のあべ議員の、潜在的待機児童数の公表をという質問で、子育て世代の置かれた実態をつかむ上では、必要なことだと私は思うのです。あるいは現在の待機児童数が１３名ですが、不承諾数は１,１７５名ということで、ご説明ほしいと求めました。","respondent":"若生保育支援課長","answer":"平成１３年度に国において認証保育所の入所者は待機児童から除くことと変更しておりましたので、それに合わせて区のほうも見直したところです。平成２７年度以降は、子ども・子育て支援制度を開始したことによって、待機児童から除く取り扱いに変わったものです。","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問","question":"区民が混乱と言いますけれど、それはどうなのでしょうか。待機児童数が１３人になるということなのですが、この１,１７５名の具体的な項目と内訳を教えてもらいたいのですけれど、。","respondent":"若生保育支援課長","answer":"認可以外の保育施設をご利用されている方が３８６名、特定の保育所を希望されている方が４９７名、そういった方が１名。この合計が１,１６２名でございまして、これを除いた待機児童数が１３名ということで、１,１７５名の内訳となっています。","id":"exchange-068"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういうふうに思いますので、ぜひそういう形で公表してほしいと求めましたけれども、いかがでしょうか。伺いたいと思います。","respondent":"若生保育支援課長、立木保育課長","answer":"今後につきましては、区民等に分かりやすいのはどういう公表の仕方なのか、十分検討してまいりたいと考えております。一定の範囲、通常の交通手段で３０分以内程度で通える範囲に空きがあるといった場合… 希望園数は８園まで書けますので、そういった方もいれば、逆に１園しか書かないというご家庭もあるということです。統計的なところはとっておりませんので、申し訳ございません。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問・要望","question":"あえて１園のみを希望というのは大体どれぐらいなのか、４９７名のうち何人なのかというのは、ご答弁ほしいと求めました。求職活動を中止したというところは深刻な実態だと思うのですけれども、これは区はどのように捉えているのか、最後にご答弁をお願いします。","respondent":"立木保育課長、若生保育支援課長","answer":"特定の１園というところで申し上げますと、２１２名ということです。 区の入園の相談の段階で、今ここに示されている内訳として示せる形での聞き取りというのは行っていないところです。将来等の働く、保育園に入れなかったから必ずしも求職活動を中止したのかというところは…","id":"exchange-070"},{"speaker":"安藤委員","kind":"意見","question":"しっかりと具体的に数字をつかみ、そして公表していくことが必要だと、改めて認識を持たせていただきましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-071"},{"speaker":"あべ委員","kind":"質問・要望","question":"１３人まで数字が少なくなってよかったということではなくて、どうやって保育を提供するかという、そこを考えていただきたいのです。１３人ですといって終わってしまったら、そこの改善をしようというスタートラインに立てないわけではないか尋ねました。","respondent":"若生保育支援課長、立木保育課長","answer":"申し込みされて不承諾となった方に関しての手当という趣旨のご質問だと認識していますが、定期利用保育、ベビーシッターの支援制度も含めまして。相談の段階でどこまで救えるかということはありますけれども… ただいま保育支援課長が申し上げたとおり、そういったトータルでの保育の必要性の部分を提供させていただいているという形になっております。入園相談のほうでも行った上で、トータルできちっと手当てできるような形で…","id":"exchange-072"},{"speaker":"あべ委員","kind":"質問・要望","question":"そこを上げていくのはやはり行政側の責任だと思いますけれども、その部分も考えていらっしゃるかどうかということ。それを選ばないからといって、私は親のわがままだとは全く思わないので、そうしたこともやってほしいと求めましたが、この点をお願いします。","respondent":"立木保育課長、若生保育支援課長","answer":"希望の園数に関しましては、どの程度までいけるかというところは今後、検討させていただきたいと思います。公立が一つ、レベルを上げていくというお役に立てればというところでは、今後も引き続きやっていきたいと考えています。 私立園につきましても、新規開設の園に関して、少しでも園庭を作ってもらえるように事業者に補助を行うというような事業も進めております。そういった事業も考えながら、今後質の向上に努めてまいりたいと考えております。","id":"exchange-073"},{"speaker":"あべ委員","kind":"質問・要望","question":"入れなかった人たち、コロナに関連しての保育料の返還ですとか、認可園に入れるかどうかでやはり差がついてきてしまうのですよね。そうしたところで入れなかった方々に不利が続くようなことがないように、目を配ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-074"},{"speaker":"あべ委員","kind":"意見","question":"行政視察については、やはり今後、おっしゃったように不透明な部分がたくさんあると思います。あるいは場合によっては遠隔での研修など、何かできる形で学んでいくというようなことも、併せて考えていただけるとありがたいですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-075"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/418457?Template=document&Id=5008#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":48839,"voices":184}},{"id":"r02-20200630-5","meetingId":"r02-cm06","date":"2020年6月30日","dateIso":"2020-06-30","committee":"総務委員会","time":"午前１０時００分～午後 １時５３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件整理しています。","topics":[{"id":"topic-01","title":"説明に入る前に、各所管委員会における審査結果","agenda":"説明に入る前に、各所管委員会における審査結果","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"国に対して増額を要求すべきだと思いますけれども、区はどう思っているのか、いかがでしょうか。同様の質問ですけれども、今後追加の財源はどのように確保していくのか、それぞれ伺いたいと思います。","respondent":"品川財政課長","answer":"それから、新型コロナウイルス感染症対応地方創生臨時交付金の金額につきましては、特別区として要望書を出して対応を図ってあります。やはり数億円単位で行っているというところですので、現在２２億円あるとすれば、対応が十分可能ではないかと考えております。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまりは増額を求めているということでよろしいのか、その点を確認させてください。巨額な税金を使うこうした超高層の再開発事業は、少なくとも延期という姿勢を持つべきではないと思うのですけれども、いかがか尋ねました。","respondent":"品川財政課長","answer":"その時々の状況に応じて随時対応していきたいと考えております。ですので、必要な事業においては、それを実施していくというのが基本的な考え方です。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"これで最後にしますけれども、財源確保については、再開発は少なくとも延期としていただきたいと改めて要望しておきたいと思います。例えば、現状でできるかどうか分からないのですけれども、いろいろな対策が取れるというところをもう少し具体的にご説明ほしいと求めました。","respondent":"品川財政課長","answer":"ただ、いろいろと工夫によりましては活用できる方向等もあるかもしれませんので、そういったところで検討するというのはあるかと思います。いろいろ検討して財源を考えていかなければいけませんので、そういった視点をもとにしまして考えていくという説明になります。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"限られた財源を有効に使っていただきたいという意味で、１点伺いたいのですが、有効に使っていただきたいと思っています。後で確認します。","respondent":"品川財政課長","answer":"委員のお話にありましたとおり、購入の際には当然国の基準等いろいろ照らし合わせて、よりよいものを購入していきたいと考えております。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"国の基準というより、それが有効でないと表示されているので、限られた財源をそこはちゃんとぜひ有効なものに使っていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"今回感染症ということですから、どうしても動きが難しいかと思うのですが、その中でできるだけの支援をしてほしいと求めました。さらにそれにプレミアムが付くということですから、ありがたいと思うのですが、その辺について財政課としてどのようなご見解をお持ちか尋ねました。","respondent":"品川財政課長","answer":"区の対応としては今回しながわ活力応援給付金等を出して、無駄がない給付にし、とにかく今回は全区民の皆さんに届くような対応という形にしています。今後も区内の経済状況をしっかり注視しながら、必要な対策は講じていきたいと考えております。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"プレミアムが付くとしても、お金がない方にそれを買い求めろというのは現実論としては厳しい、買いにくいものだと思うのです。終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"鈴木（真）委員長","kind":"確認","question":"国の給付金は今、福祉計画課でやっていますが、その方が移って作業していく感じになるのですか。その辺の流れを、まず確認したいと思います。","respondent":"佐藤企画調整課長","answer":"６月２日に組織を立ち上げた時点で、その辺は給付の状況を見ながら、柔軟に対応していきたい。一方で委託事業者については、もう契約の見込みが立っていますので、そういう形でやっていくというところです。","id":"exchange-008"},{"speaker":"中塚委員","kind":"意見","question":"賛成します。第２波に備えて、引き続き検査や病院、区民や事業所への支援をよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"一般質問でも言いましたが、お金の手当てが必要ではないかと思いますので、そのことだけは今後検討してほしいと求めました。そういう意見を述べて、これについては賛成をいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"}]},{"id":"topic-02","title":"品川区総合庁舎免震オイルダンパー交換","agenda":"品川区総合庁舎免震オイルダンパー交換","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"そこで、データ改ざんと検査機器の不正操作を行った理由について、品川区は相手からどのように説明を受けているのか、その辺を伺いたいと思います。それには自分たちがなぜこのような行為に至ったのか、先方がどのような理由というか、間違いを説明しているのか伺いたいと思います。","respondent":"東野経理課長","answer":"それによりますと、これが主たる理由として改ざんが行われていたという事実があったと聞いてあります。これを社内できちんと検査できる体制が整っていなかったことも理由の一つだと聞いているところです。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回新たに設置されるものは国の確認がされているということですが、基準に合っているかどうかは、国による検査について説明してほしいと求めました。","respondent":"東野経理課長","answer":"国の検査責任といいますか、どういう担保を取れるのかという部分ですが、国が検査チェックをするというところで今回の改ざんも分かったので、国の検査が最終手段だと考えています。","id":"exchange-012"},{"speaker":"中塚委員","kind":"意見","question":"いずれにしてもこの間の区の毅然とした態度は評価したいと思います。総務委員会で言うのは変ですけれども、建設行政といいますか、契約も含めて引き続きよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"その辺はどうなのですか。何を担保にして、今回これを承認、また区としてもどういうふうに承認したのか尋ねました。","respondent":"東野経理課長","answer":"今回の大きな事件をもとに、国も検査体制を強化しているものと思われます。国としても最終的には発覚したという部分がありまして、それをもとに今回国が適合品と判断したというところは信憑性が高いものと思ってあります。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"免震の安全保証があったわけですが、この数年間それが全然機能しなかったことに関して、賠償責任を先方に問うわけにはいかないのでしょうか。その辺はどうなのか尋ねました。","respondent":"東野経理課長","answer":"それと、この１年半ぐらいの間、機能していなかった部分があることはたしかだと思ってあります。それを区は交換でと判断したものでございまして、特に賠償責任を求める考えではございません。","id":"exchange-015"},{"speaker":"須貝委員","kind":"質問","question":"たしかまたそこに埋め込み直すというのもできないというご説明だったと思うのですが、それが何でできるようになったのですか。ちょっと説明を求めました。","respondent":"東野経理課長","answer":"高さが１メートルもないようなところに付いているので、腰をかがめていくような、作業しにくいところになってあります。ダンパー自体を付けたときには、工事作業員が作業できてありますので、決して交換できないという状況ではないというように受け止めてあります。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問・要望","question":"安全に、しかもしっかり取り付けている状態になったかどうかは、区としても確認をしてください。付けるときは付けられても、外すときはなかなかできないという状況もありますから、そこは区でしっかり確認をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"聞き漏らしたのかもしれないのですけれども、私は去年の決算特別委員会の１０月３日の総務費のところで、免震オイルダンパーのことを伺っております。１１月１１日の元データの保証ができないためというのは、１０月３日の答弁とどういうふうに整合性が取れるのか、ちょっと教えていただきたい。","respondent":"東野経理課長","answer":"委員がおっしゃっているのは、ダンパーそのものの数値のことかと思います。震度７程度では倒壊しないという評価をいただいているので、全体での評価とダンパーそのものの評価での差になってくるかと思います。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問","question":"ただ、そのとき私ももう一回質問していて、１１月１１日の元データの保証ができないためというのはどういうことなのでしょうか。説明を求めました。","respondent":"東野経理課長","answer":"ただ、それも元の数値がきちんと合っているかどうかという信憑性がないものと判断したところです。そういった意味で、決算特別委員会の当時に発言したものと思われます。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問・要望","question":"将来的に区民に説明を求められて、あの件はどうなったといったときには、みんな不安だと思うのです。しっかりやっていただくことを要望するしかないわけですが、伺いたいと思いますが、いかがか尋ねました。","respondent":"東野経理課長","answer":"区民に示すという意味では、まさにこの委員会での報告になってくるのかなと思います。結局は全部の取替えにつながったことになりますので、区民に対してはそういう説明をしていきたいと考えています。","id":"exchange-020"},{"speaker":"湯澤委員","kind":"確認","question":"不正があってから、この不正行為が平成３０年１０月１６日に報道で発表されて、総務委員会でも平成３０年１０月２９日に報告があったということです。例えば、工期は７月１１日から２３日ということで、ここに至るまでにはどういった経過でこういうことになったのかということを確認させてください。","respondent":"東野経理課長","answer":"先ほどご説明しましたが、区として交渉した結果、昨年１１月に４基全部取り替えますというところまで引き出したものと捉えています。ちょうど２月、３月の新型コロナウイルス感染症対策で、７月のこの時期になったものです。","id":"exchange-021"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"説明を受けて、内容は確認させていただきました。そして工事はこのように行いますということは、ホームページ、またＳＮＳ等を使って公表されるのか確認させてほしいと求めました。","respondent":"東野経理課長","answer":"区民の安全・安心のために、ホームページでの公表もきちんとしていきたいと思います。ぜひ前向きにやっていきたいと考えております。","id":"exchange-022"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"東京全体でああいうふうに新聞・テレビ報道が出たり、あとは今度受け入れる側の対応が皆さんそれぞれあると思うのです。どういう感染ルート、どういう状況になるか、それは一言だけ言わせていただきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/346628?Template=document&Id=2174#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":21323,"voices":75}},{"id":"r02-20200630-10","meetingId":"r02-cm06","date":"2020年6月30日","dateIso":"2020-06-30","committee":"議会運営委員会","time":"午後 ０時４５分～午後 ０時４６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/101132?Template=document&Id=5370#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":969,"voices":8}},{"id":"r02-20200701-14","meetingId":"r02-cm07","date":"2020年7月1日","dateIso":"2020-07-01","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１１時４９分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"皆さんの税金で建てて、一体どういうふうに使えば税金を納めた区民の皆さんの役に立つのかということを精いっぱい考えてやっていくべきものですから。品川区でもやりたいのかなと非常に思いましたので、私は改めて思ったのですが、その点はどうお考えなのか伺いたい。","respondent":"品川財政課長","answer":"それを急遽名前を変更するというところについては、非常に抵抗感があるのかなというところは、一つの課題としてはあるのかというふうに思います。そういった部分も検討しながら、やはり進めていかなければならないという点があるかというふうに思います。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"利益を得ている人がその得た受益、利益に対して負担すべきだという考え方だと思うのですけれども、こういう理解でよろしいでしょうか。お伺いします。","respondent":"品川財政課長","answer":"本人に受益が出ているという部分で、一定部分については当然お金を支払ってもらうということで、先ほど委員がお話しした考えで特に間違いございません。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"区もそういう施設を増やしてきているということですから、一般的、普通なことだと思うのです。そうやったとしても、多分大した費用ではないというふうに私は思うのですけれども、いかがか尋ねました。","respondent":"品川財政課長","answer":"いろいろな区民の方から公共施設を借りるというところの目線で見れば、さまざまな考え方があるかと思います。総合的な考え方としては、こういう受益者負担の考え方というのが必要ではないかと、このように思っております。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問・要望","question":"そこいら辺を転換していく方向で頑張っていただきたいというのが私の要望です。お願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その点をお聞かせいただきたいのと、受益者負担というのを、その点はいかがでしょうか。誰もが使うものですから、それはぜひやめていただきたいと思うのですが、いかがか尋ねました。","respondent":"品川財政課長","answer":"区としてそういうニーズにどういうふうに応えていくかというところは、やはり区政運営をする中でも非常に難しいところではないかと考えています。やはり一定のニーズがあれば対応していくというところが区としての判断になるかと思いますので…","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どういうふうに区民の中で使われるべきなのか、権利を保障する、そういうふうなところで考えていただきたい。だから、本当に取るとしても負担にならない低廉なものでぜひやっていただきたいと、そういうことでお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"さまざま２３区の中で大分打撃を受けて、やはりふるさと納税の対応策というのですか、やはりそこが主眼になるのでしょうか。それとも、そちらのほうで少しでもいいから担っていくほうがいいのか、どのように区としては考えていらっしゃるのか尋ねました。","respondent":"品川財政課長","answer":"そういう中で、特別区一体として、ふるさと納税に対しての一つの対応策というところではやっているところです。新たな一つの手法ではないかというところで、こういった面を少し検討していきながら新たな展開を探っていきたいと、このように考えております。","id":"exchange-007"},{"speaker":"須貝委員","kind":"意見","question":"高齢化する、その中、そろそろやむを得ないものとして返礼品競争にもっと本格的に力を入れるべきではないかなというふうに私は思うのですね。そうすると、何かやっている意味がないのではないかなという気がするのですが、この辺についてちょっとご見解を説明を求めました。","respondent":"品川財政課長","answer":"競争にならないようにというふうに先ほど答弁しておりますが、返礼品についても当然工夫をして対応していきたいというふうに考えております。ガバメントクラウドファンディングのようなところを重視しながら、今後も税外収入に努めていきたいと、このように思っております。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"税外収入というのはどういうものだという見解をしっかり区が出すべきだ。そこら辺の考え方も含めて教えてほしい。","respondent":"品川財政課長、堀越企画部長","answer":"今後のあり方についてはやはりいろいろと検討していかなければいけないという必要性があるかというふうに考えております。ぜひこれは税外収入を今後進めていくためにも、いろいろな成功事例を取り入れて研究をしながら進めていきたいと… 在勤者といいますか、そういった考え方もあると思いますので、それはまた研究していきたいというふうに思います。なじみですとか、いろいろと研究して進めていく必要があると考えていますので…","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"提案","question":"どこの商店街とどこがどうやってやれるのというのがあって、できないのではないかと思うと、それは引き込めないではないですか。ぜひ２３区でいろいろな例、それでどういう形だったらこれぐらいの収入があって、との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"塚本委員","kind":"提案","question":"昨年、この事業はガバメントクラウドファンディングを使ってやってみようよというような話というのは、どういうふうに広げていけるのか。これはどうだ、その辺の考え方とか進め方…","respondent":"品川財政課長","answer":"こういう中では、あと毎年８月に予算の依命通達の説明会を管理職全員で集まって、私が話すような場があるのですけれども。所管は所管でということで連携をしながら、今後こういうガバメントクラウドファンディング等をやっていきたいと、このように考えております。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"少し空気が変わってきているのかもしれないというところで、今ご答弁があったとおり、企画からも積極的な働きかけをお願いしたいと思います。いわゆる民間活力、ＰＦＩだとか、最後にどのように捉えていらっしゃるのかをお伺いしたいと思います。","respondent":"品川財政課長","answer":"２０年前ぐらいからＰＦＩというような形で民間のノウハウを入れながら事業を進めていくというようなやり方が大分出てきたかというふうに思います。それから他の市町村、そういった事例も参考にしながらぜひ考えていきたいと、このように思っております。","id":"exchange-012"},{"speaker":"せお委員","kind":"提案","question":"２点提案をさせていただきたいと思うのですけれど、１点目は、こちらが提案として１点あります。そういったところも検討していただきたいなと思うのですけれども、この２点、品川区はどうお考えかと思ってお聞きしますとの意見を述べました。","respondent":"品川財政課長","answer":"水辺、公共関係のところで、そういったところも一つ一つ適合するような形で進めていくというのが一つかと思います。こういうカフェ等を出すことができるかどうかというところは、いろいろと工夫をしながらうまくやっていきたいと、このように思っております。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"品川区は人口も増えていますし、毎年基金も数十億円ため込んでいます。私は必要ないのではないかなと思うのですけれども、もともとの財源をどう振り分けるかということが問題だと思うのですが、いかがか尋ねました。","respondent":"品川財政課長","answer":"ほぼ書類の厚さとしては１cm、２cm、かなりの量の書類を書いて提出をしなければいけないというような作業量があります。当然区として歳入が入る部分ですので、これは区の考え方としては税外収入、これは必要というふうに考えてあります。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問","question":"人口推計でも今の人口に戻ってくるまでに２５年ぐらいかかるということだったと思うのですが、現在そんなに財源を心配する必要はないのではないかと思うのですけれども、いかがか尋ねました。","respondent":"品川財政課長","answer":"全体の財源というところの目線ではなく、当然区としていろいろなところから歳入を確保すると、こういうところが大事ですので、そういった面でも税外収入は必要というふうに考えてあります。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問","question":"これは本来区がやるべきことであって、寄附で賄っていくというのは自助共助の助け合いに置き換えていくということだと思うのですね。しっかり区が事業を行って、その上でそこに上乗せをしていくということで活用していくべきだと思うのですけれども、いかがか尋ねました。","respondent":"品川財政課長","answer":"ガバメントクラウドファンディングというところは、当然区の歳入を、収入を幅広いところから得るというような形でやっているものです。ですので、より多くのところから、より多くの手法を使って歳入を得ていくと、こういうやり方をしていくという考え方です。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり、今回の子ども食堂とかひとり親への食品配送というのは、万が一の事態になれば人の命に関わることなのですよね。それにさらに上乗せをしていくという形でガバメントクラウドファンディングなどは活用していっていただきたいというふうに言っておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"ですから、先ほどのいわゆる助成金、補助金を取れるところはしっかり取っていく。これもふるさと納税ですから、税務課が担当されていらっしゃるのですかね、企画にも相談はするのでしょうけれども。","respondent":"品川財政課長","answer":"例えば、千本桜についても、税務課だけで全部をやるというのは非常に難しいというところは私たちのほうも心得ております。全体的にこういう税外収入については、いろいろな事例を参考にしながら積極的に進めていきたいと、このように思っております。","id":"exchange-018"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"一般質問でも申し上げましたが、人の情緒に訴えるものがなければ、やはり寄附というものは勢いがつかない。これから先のことを考えて、取れるものは全部取っていくというぐらいの民間の経営感覚で臨んでいただきたいというふうに希望したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"小芝委員","kind":"提案","question":"１点ですけれども、例えば改修工事をクラウドファンディングで提案してみてはいかがでしょうかと思います。いかがか尋ねました。","respondent":"品川財政課長","answer":"そのニーズに合ったところとか、目立つ場所とか、さまざまなところを検討しながらやっていかなければいけないなというふうに思っております。そういう部分も考慮しながら今後いろいろな、税外収入のところについても考えていきたいと考えています。","id":"exchange-020"},{"speaker":"若林委員","kind":"質問・要望","question":"ネーミングライツのご説明の中で、企業の地域貢献的なところの観点でのお話がありました。品川区において、いわゆる行政関連で企業の社会貢献というと、今はどのように把握をされて活動されているか教えていただきたい。","respondent":"品川財政課長","answer":"いろいろと細かな部分については、品川区内にある企業は、区のほうに非常に貢献していただいているという印象を私は持っております。非常に区のことを思っていただいて、いろいろな部分で区の事業のほうに協力していただいているような状況であるというふうに思っております。","id":"exchange-021"},{"speaker":"若林委員","kind":"質問・要望","question":"そういう意味では、もう設立して１０年、２０年ぐらい経つのかな。例えば本当に社会福祉協議会で事務局をお任せしていていいのかどうかということも含めて、そろそろ１回お話し合いをして、お聞かせいただきたい。","respondent":"品川財政課長","answer":"大分課題等もわかってきているので、そういった解消に向けては進めていく方向ではあるかというふうに考えております。ですので、これは一つのやり方ではないかと思いますので、こういう手法なども参考にしながら今後どういうふうにやるか考えていきたいと思います。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"提案","question":"区民の方々、会社もお世話になっているということを考えるのであれば、区民の皆さんにいろいろな形で社会貢献したいということがあるではないですか。一段進むとそういうこともありではないかなという意味で、一つだけ、提案だけとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"芹澤委員","kind":"確認","question":"１点確認したいのですが、今のガバメントクラウドファンディングの制度として確認なのですが、実際にできている仕組みになっているのか。手続きがいろいろとあってできないというようなお話をされていたように思っていまして、そこの確認だけお願いします。","respondent":"品川財政課長","answer":"すみません、ガバメントクラウドファンディングのほうでこれが対応できているかどうかまではちょっと調べがついておりません。申しわけございません。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/988746?Template=document&Id=6092#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":32503,"voices":52}},{"id":"r02-20200702-18","meetingId":"r02-cm07","date":"2020年7月2日","dateIso":"2020-07-02","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午前１１時２９分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"情報共有や定期的な打合せなどの体制はどうなっているのかを伺いたいと思います。前回お伺いしたときにはご答弁があった、結果としては区はどう受け止めていらっしゃるのか、併せてお考えをお伺いしたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"１点目の都との連携ですが、特別区、それから組織委員会等を合わせたオリンピック・パラリンピックの課長会というものがあります。来年に向かっても私どももどうやって準備の事業を構成していくか、そういったことも含めて考えていきたいと思っているところです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"ホッケー教室は年３回ということで、これはもともと大会中に開催する想定だったのが８月から１１月に３回と変更になったのかを伺いたいと思いますし。それぞれこの時期に決まった、行う理由を、もう少しご説明ほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"次回は７月に開かれる予定になっております。それから、ホッケー教室なのですが、もともとは大会前に１回、終わった後に２回という予定でおりました。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"日常生活ですとか、このようなスポーツ活動を両立させてやっていく工夫が求められる中で、区としての判断基準をもう少し具体的に。このブラインドサッカーについて言うと、何をどう見極めるのかという点をもう少し具体的に教えていただけたらと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"室内で狭いところだったら難しいとか、そういったものに代えるだとか、そういったことは可能です。“何人になったらこうだ”というようなことはお答えが難しいところですが、またいろいろ日々の状況を見ながら判断するというような感じです。","id":"exchange-003"},{"speaker":"こんの委員","kind":"質問・要望","question":"何点か確認させてほしいと求めました １つは、１年前どうしようか会議、３つ目にホッケー教室の３点について何点かお聞きしたいと思います。１年前どうしようか会議ですけれども、主な目的、どういった人たちをターゲットにＹｏｕＴｕｂｅで配信しようと考えられたのか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"当初から予定していたものではございません。まだ会議アクセス用のＱＲコードも入っていませんし、その辺も入れた形で作る予定です。","id":"exchange-004"},{"speaker":"こんの委員","kind":"確認","question":"これは７月２３日ですから、もう今日は７月２日で、そこら辺の周知を早めにしたらどうですかということ。しな助２名がこのトークに入られるということですけれども、これはどのように選ばれていくのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"７月に入ってしまって、２３日まであまり時間がないのですが、ＳＮＳですとか、ホームページも明日から載ります。チラシも関係機関に配って周知したいと思います。","id":"exchange-005"},{"speaker":"こんの委員","kind":"質問","question":"１１月なので、どのようにこれを準備されていこうとするのか、もう少し具体的に教えていただけますでしょうか。イメージ的に湧くような、湧かないような感じなので、少しそこら辺のところを説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今のところ考えているのは、体の使い方だとか、そういったことで工夫しながら。そういった形で多くの人たちに楽しんでもらえるようなオンラインのホッケー教室を、今、企画中です。","id":"exchange-006"},{"speaker":"こんの委員","kind":"質問・要望","question":"開催自体がどうなるのかというところもあるかと思いますけれども、その点、どうぞよろしくお願いします。ぜひいろいろな工夫でオンライン教室を開催していただきたいとの要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"何点かお聞きしたいのですけれども、１年前どうしようか会議、窓口を締めたのですよね。もうしな助の募集はしていないのですよね。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"しな助の応募については、特にまだ締めてはいないのですが、今の時期ですと、なかなか新規に入られる方は増えない状況です。","id":"exchange-008"},{"speaker":"松澤委員","kind":"質問・要望","question":"こういった会議を見て、“ボランティアはすばらしいですね”みたいな形でもっと増えていくと、大変すばらしい取り組みになるのかと思っています。今後、しな助をどういった位置づけで考えていくのか、方向性があれば教えていただきたい。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"東京２０２０大会に向けた機運醸成のための集まりですので、大会が終わった後は、しな助という形での継続はなかなか現状では難しいと思っています。ご本人が見つけるのか、私どもも紹介していくのかということは、考えていきたいと思います。","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問","question":"確かに５００名近いボランティアがそのままいなくなってしまうのは非常にもったいないので、しっかりとそういった形で残していただけたらと思います。最後に、聖火リレーは中止になりましたが、あれは来年度に向けたときに再募集するのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"聖火リレーについてのご質問です。聖火リレーは来年に延びまして、今決まっている方に走ってもらうということで、新たな再募集はないと聞いております。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"ブラインドサッカーを荏原第六中学校で練習されていたと思いますが、現状はどうなっているのかお伺いしたいのです。もしお答えできるようでしたら、お願いしたいのですが。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今現在は新型コロナウイルス感染症の関係もありまして、日本代表の選手の練習はずっと休止されておりました。委員ご指摘のとおり、以前は荏原第六中学校の校庭を使って練習していたのですが、今現在はそちらのほうは休止しております。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"新型コロナウイルス感染症の影響によって練習を休止したということですけれども、では、休校に入る前からだったのか、いつ頃から練習が休止になったのかをお伺いできればと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"荏原第六中学校の練習に関しましては、新型コロナウイルス感染症の影響がある前から一旦休止をしております。今はまた休止になっているのですけれども、今、立会小学校のほうを使わせていただいて練習をする形になっております。","id":"exchange-012"},{"speaker":"田中委員","kind":"確認","question":"何らかの理由があって行われて、現在、立会小学校でも新型コロナウイルス感染症の影響で休止しているということなのですか。その辺を確認させてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"委員ご指摘のとおり、荏原第六中学校から立会小学校に代わったのは、新型コロナウイルス感染症とは直接は関係ございません。今現在は、やはり新型コロナウイルス感染症の関係もございまして立会小学校でも練習はしておりません。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"非常に面白いと思っていまして、特にこの「１年前どうしようか会議」のタイトルとか、非常に関心があるところが取り上げられるかと期待しております。まず確認をさせていただきたいのが、どうなっているのかが１点と、そのやり方を教えてほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"抽選があって漏れるということもないので、その意味ではオンラインでやるのは一つのメリットもあると感じるところです。会議の会場ですが、参加者は１つのところに集まって、おしゃべりをしているところを配信する、そのような予定になっております。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"委員会に出ていなかったので分からないのですけれども、例えば設計費用とかそこら辺まで手配していたのかどうか。それをまず説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"こちらはスポル品川大井町を借りて開く予定で、仮設のテント等も設置する予定です。その辺りの事務の精査も出てくることはあります。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"確認","question":"手続きしたことによって建築確認を１回取っておけば、そのままいけるはずですよね。今年やったものが来年に向けて活かしていけるのか、その辺はどうなのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"区の財政としても、なかなか今、予定していた規模での実施は厳しいかなという実感をもっております。もう一度、一から考えていきたいと考えています。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ありがとうございました。これからどう考えていくかということは、その辺、改めて頑張っていただきたいということで要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"渡部副委員長","kind":"確認","question":"確認はできましたけれども、その他の事業において、来年度に持ち越しで今回中止と出ているものはやっていけるのかどうなのかがまず一点です。１年前どうしようか会議は今までは考えていなかったことで、考えていらっしゃるのかどうなのかを、併せて説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"１年延びたことで、子ども関係のところですとかいろいろなところで予定しておりましたところ、今現在はどこの課もできない状況です。その辺りは、選択と集中で調整しながら、来年に向けて進めていきたいと考えているところです。","id":"exchange-018"},{"speaker":"渡部副委員長","kind":"質問","question":"これはもう出来上がっているわけですから、例えばですけれども、組織委員会のオーケーが出るのであれば、区民対象に開放することはできないですか。例えば潮風公園のほうでも、真っさらではなくてある程度仮設が進んだわけではないか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それで仮設を造る関係で資材等があるので危険を伴うということで、メインピッチのほうは難しいと言われています。６割方ということは、そこが一つのポイントかと思いますので、その辺を確認しながら進めていきたいと思います。","id":"exchange-019"},{"speaker":"つる委員","kind":"質問","question":"１３番に書かれていることはそうしたことも含めた新しいものを作るだとかということでしょうか。メインのデザインは変わらないのでしょうけれども、その辺、分かれば説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"私どもが予定していたのは、道路のガードレールに付けるとか、そのようなことでいろいろ考えておりました。１年延びたということで、もう一度、どこに付けるのが適切かということも含めまして検討をしていくです。","id":"exchange-020"},{"speaker":"つる委員","kind":"質問・要望","question":"希望となるのが、この４コマ漫画を私も拝見しましたし、すごくいい意味での特異な形であるなと思っています。意見だったり、主なものでいいですが、教えてほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"その辺を含めて４コマ漫画をやってみようということで、逆に寂しいといいますか、もう少し反応がいただきたいという。私ども、毎日、「いいね」の数だとか、何人ぐらい見てくれているのだろうかとかを確認しているのですけれども、あまり反応がなくて寂しいところです。","id":"exchange-021"},{"speaker":"つる委員","kind":"確認","question":"前回の委員会でもその辺を確認したり、教えていただいたりしたのですけれども、それからストレストレーニングですとか。そのようなものはこれまでも既にやったのか、もしやっていなければやってほしいというところがあるのですが、いかがか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"私どもの職員のホッケー元日本代表の方を中心に、今までは家で簡単にできるストレッチ、それから筋力トレーニング的なものを発信してまいりました。メンタルトレーニングとかストレス関連のほうは、今まではなかったかと思いますので、その辺りも含めて…","id":"exchange-022"},{"speaker":"つる委員","kind":"意見","question":"それがそのまま対新型コロナウイルスになるかどうかは別ですが、アスリート食だとか、それは栄養士さんと連携してやる。今度の１年前どうしようか会議でもトークテーマの１つに入れてもらうとか、ぜひそうしたメニューも増やしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"湯澤委員","kind":"質問","question":"この１年前どうしようか会議を開くという情報も、多分、ホームページでもお知らせするのだと思うのです。その辺、スケジュールはいかがか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"その辺りの新しい注意喚起のこともありますので、区のホームページは今現在、カウントダウン表示は載せる予定はございません。１年前どうしようか会議については、もちろん区のホームページにも掲載しますので、それがなるべく目立つようにお知らせはしたいと考えています。","id":"exchange-024"},{"speaker":"湯澤委員","kind":"質問","question":"新型コロナウイルス感染症のことが本当に第一だと思うのですけれども、機運醸成のためには、ホームページへの掲載も必要な一つの手段だと思います。その辺をどうお考えか、教えていただけますか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"委員ご指摘のとおり、人を知ることは、やはりすごく親近感をもってその競技をより好きになるもとだと考えています。このような面白い話があるのだというのに気付いてもらう、もうひとつ広くできるのはどういった形なのかを考えながら進めていきたいと思います。","id":"exchange-025"},{"speaker":"湯澤委員","kind":"意見","question":"最後に会場についてですけれども、予定どおり行うとなると、暑さ対策もあると思うのです。そういった方々に、アピールしていけばいいのではないかと思いますので、そういったところもお願いしたいということを言わせていただいて終わりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"筒井委員","kind":"確認","question":"確認ですけれども、キャナルアートモーメント品川２０２０というイベントは、どういった内容のものか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"キャナルアートモーメント品川２０２０についてのご質問です。これを当初は、パラリンピックが行われている８月２９日から３０日に行いまして、それから品川区の文化を世界中にアピールする予定でございましたが。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"たとえ実際に人を大量に集めることができなくても、そうしたオンラインでの配信をぜひやっていただきたいと考えております。ぜひそうしたオンライン配信もやっていただきたいと考えておりますけれども、実際その辺りはどのようにお考えなのかをお知らせください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"キャナルアートモーメント品川２０２０の集客と配信の方法です。ただ、新型コロナウイルス感染状況等によっては、そういった場合にはオンライン配信も検討の俎上に上がってくるかとは思っているところです。","id":"exchange-028"},{"speaker":"西村委員","kind":"提案","question":"１点目が、逆に区民の方に盛り上げるためのアイデアを募集するのはどうかと思います。手詰まり感というか、なかなか私たちでは考えられないようなアイデアもいただけるのではないかという期待も込めましてご提案しますとの意見を述べました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"その中にアイデアを募集するのもいいかなと思いますので、検討したいと思います。今は、ワークショップの中で１人ずつに“私はこのようなことを目指す”とか、そのような形で取り入れられるかと思っています。","id":"exchange-029"},{"speaker":"西村委員","kind":"意見","question":"スポーツの祭典ではありますけれども、文化、語学、手話も、何かみんなで目指していき、レガシーとしてみんなの心に残るような取り組みが、オンラインを通してでもできるのではないかと思いますので、期待を込めまして引き続きとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"木村委員","kind":"意見","question":"１年前どうしようか会議ということでありますから、これをいいほうに捉えて、これをどのようにプラスに替えていこうかと考えることができるかどうか。この東京２０２０大会が本当に成功裏に終わることを私たちも願っているところでありますけれども、この１年間、お答えくださいとの意見を述べました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今、このピンチをチャンスとしてどうやって取り組んでいくかということが、私たち行政にも問われているところだとは認識しております。それからみんなが混ざり合う社会を作っていくということを今年１年かけてどのような形でできるのかということを考えつつ…","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/312568?Template=document&Id=6578#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":27045,"voices":82}},{"id":"r02-20200707-10","meetingId":"r02-cm07","date":"2020年7月7日","dateIso":"2020-07-07","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/101132?Template=document&Id=5372#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":9245,"voices":50}}]);
